/// A declared constructor value has no class declaration or synthetic class shell.
#[derive(Clone, Debug, Eq, PartialEq)]
struct DeclaredClassBaseMembers {
    value: DeclaredConstructorValuePlan,
    constructor: PropertyObjectPlan,
    instance: PropertyObjectPlan,
    identities: ClassBaseIdentities,
    signatures: Vec<ValidatedSingleCallable>,
    instance_properties: Vec<SemanticSymbolId>,
    static_properties: Vec<SemanticSymbolId>,
    bindings: Vec<SourceClassBinding>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum SourceClassBaseMembers {
    Class(ClassMembers),
    Constructor(Box<DeclaredClassBaseMembers>),
}

impl SourceClassBaseMembers {
    fn identities(&self) -> ClassBaseIdentities {
        match self {
            Self::Class(base) => ClassBaseIdentities {
                symbol: base.shells.symbol,
                instance_type: base.shells.instance_type,
                value_type: base.shells.value_type,
            },
            Self::Constructor(base) => base.identities,
        }
    }

    fn instance_properties(&self) -> &[SemanticSymbolId] {
        match self {
            Self::Class(base) => base.instance_properties(),
            Self::Constructor(base) => &base.instance_properties,
        }
    }

    fn static_properties(&self) -> &[SemanticSymbolId] {
        match self {
            Self::Class(base) => base.static_properties(),
            Self::Constructor(base) => &base.static_properties,
        }
    }

    fn default_construct_signature(&self) -> SignatureId {
        match self {
            Self::Class(base) => base.default_construct_signature,
            Self::Constructor(base) => base.signatures[0].signature,
        }
    }
}

impl SourceClassProvenance {
    pub(super) const fn symbol(&self) -> SemanticSymbolId {
        self.prepared.plan.symbol()
    }

    pub(super) const fn instance_type(&self) -> TypeId {
        self.prepared.instance_type
    }
}

fn source_class_body(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    declaration: NodeRef,
    body: ts_ast::NodeId,
) -> Result<NodeRef, ClassError> {
    let body = NodeRef::new(declaration.arena, declaration.file, body);
    let record = preflight_node(store, host, body)?;
    let NodeData::Block(block) = &record.data else {
        return Err(invariant(ClassInvariant::InvalidDeclaration(body)));
    };
    let owner = preflight_node(store, host, declaration)?;
    if record.kind != SyntaxKind::Block
        || record.parent != Some(declaration.node)
        || record.flags.0 != 0
        || record.range.start < owner.range.start
        || record.range.end != owner.range.end
        || block.facts != 0
        || block.statements.has_trailing_comma
    {
        return Err(invariant(ClassInvariant::InvalidDeclaration(body)));
    }
    let mut previous_end = record.range.start;
    for &statement in &block.statements.nodes {
        let statement = NodeRef::new(body.arena, body.file, statement);
        let child = preflight_node(store, host, statement)?;
        if child.parent != Some(body.node)
            || child.range.start < previous_end
            || child.range.end > record.range.end
        {
            return Err(invariant(ClassInvariant::InvalidDeclaration(statement)));
        }
        previous_end = child.range.end;
    }
    Ok(body)
}

fn source_constructor_parameter(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    parameter: ClassConstructorParameterPlan<ClassBodyParameterType>,
) -> Result<ClassBodyParameterPlan, ClassError> {
    let record = preflight_node(store, host, parameter.declaration)?;
    let NodeData::ParameterDeclaration(data) = &record.data else {
        return Err(invariant(ClassInvariant::InvalidProperty(
            parameter.declaration,
        )));
    };
    let type_ = match parameter.type_ {
        ClassBodyParameterType::Known(type_) => ClassBodyParameterType::Known(
            optional_constructor_parameter_type(
                store,
                type_,
                parameter.optional,
                parameter.declaration,
            )?
            .ok_or_else(|| {
                unsupported(ClassUnsupported::PropertyType {
                    node: parameter.type_node,
                    kind: SyntaxKind::Parameter,
                })
            })?,
        ),
        reference @ (ClassBodyParameterType::ClassReference { .. }
        | ClassBodyParameterType::Tuple(_)
        | ClassBodyParameterType::PrimitiveUnion(_)
        | ClassBodyParameterType::Annotation(_)) => reference,
    };
    Ok(ClassBodyParameterPlan {
        declaration: parameter.declaration,
        name_node: NodeRef::new(
            parameter.declaration.arena,
            parameter.declaration.file,
            data.name,
        ),
        symbol: parameter.symbol,
        property_symbol: parameter.property.map(|property| property.symbol),
        annotation: Some(parameter.type_node),
        initializer: parameter.initializer,
        type_,
        optional: parameter.optional,
    })
}

fn source_parameter_property<T>(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    parameter: &ClassConstructorParameterPlan<T>,
) -> Result<Option<ClassPropertyPlan>, ClassError> {
    let Some(property) = parameter.property else {
        return Ok(None);
    };
    let record = preflight_node(store, host, parameter.declaration)?;
    let NodeData::ParameterDeclaration(data) = &record.data else {
        return Err(invariant(ClassInvariant::InvalidProperty(
            parameter.declaration,
        )));
    };
    let name_node = NodeRef::new(
        parameter.declaration.arena,
        parameter.declaration.file,
        data.name,
    );
    let name_record = preflight_node(store, host, name_node)?;
    let NodeData::Identifier(identifier) = &name_record.data else {
        return Err(invariant(ClassInvariant::InvalidName(name_node)));
    };
    let (initializer_text, initializer_string) = match parameter.initializer {
        None => (None, None),
        Some(initializer) => match &preflight_node(store, host, initializer)?.data {
            NodeData::NumericLiteral(literal) => (Some(literal.text.clone()), None),
            NodeData::StringLiteral(literal) => (None, Some(literal.text.clone())),
            _ => return Err(invariant(ClassInvariant::InvalidProperty(initializer))),
        },
    };
    Ok(Some(ClassPropertyPlan {
        declaration: parameter.declaration,
        symbol: property.symbol,
        name_node,
        type_node: parameter.type_node,
        initializer_node: parameter.initializer,
        initializer_text,
        initializer_string,
        initializer_parameter_name: None,
        initializer_assertion: None,
        merged_interface_annotation: None,
        auto_accessor: false,
        name: identifier.text.clone(),
        side: ClassPropertySide::Instance,
        optional: parameter.optional,
        definite: false,
        abstract_property: false,
        readonly: property.readonly,
        ambient_private_modifier: None,
        parameter_property: true,
        javascript_constructor_assignment: false,
    }))
}

fn plan_source_class_constructor(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    header: &ClassDeclarationHeader,
    declaration: NodeRef,
    type_context: Option<&ClassTypeQueryContext>,
) -> Result<(SourceClassConstructorPlan, Option<ClassBodyPlan>), ClassError> {
    let record = preflight_node(store, host, declaration)?;
    let NodeData::ConstructorDeclaration(data) = &record.data else {
        return Err(invariant(ClassInvariant::InvalidDeclaration(declaration)));
    };
    if record.kind != SyntaxKind::Constructor
        || record.flags.0 != 0
        || record.parent != Some(header.declaration.node)
        || data.asterisk_token.is_some()
        || data.end_flow_node.is_some()
        || data.full_signature.is_some()
        || data.next_container.is_some()
        || data.return_flow_node.is_some()
        || data.symbol.is_some()
        || data.type_.is_some()
        || data.type_parameters.is_some()
        || data.facts != 0
        || data.parameters.has_trailing_comma
    {
        return Err(invariant(ClassInvariant::InvalidDeclaration(declaration)));
    }
    let visibility = class_constructor_visibility(
        store,
        host,
        declaration,
        data.parameters.range.start,
        data.modifiers.as_ref(),
    )?;
    let symbol = bound_symbol(store, host, declaration)
        .ok_or_else(|| invariant(ClassInvariant::InvalidConstructSignature(header.symbol)))?;
    let owner = store
        .symbol(symbol)
        .ok_or_else(|| invariant(ClassInvariant::InvalidConstructSignature(header.symbol)))?;
    if owner.flags() != SymbolFlags::CONSTRUCTOR
        || owner.check_flags() != CheckFlags::NONE
        || owner.name() != InternalSymbolName::Constructor.as_ref()
        || !source_constructor_group_is_exact(store, host, header, symbol, declaration)?
        || owner.value_declaration().is_some()
        || owner.parent() != Some(header.symbol)
        || owner.members().is_some()
        || owner.exports().is_some()
        || owner.export_symbol().is_some()
        || store.get_merged_symbol(symbol) != Some(symbol)
        || header
            .instance_members
            .and_then(|table| store.symbol_table(table))
            .and_then(|table| table.get(InternalSymbolName::Constructor.as_ref()))
            != Some(symbol)
    {
        return Err(invariant(ClassInvariant::InvalidConstructSignature(
            header.symbol,
        )));
    }
    let mut parameters = Vec::new();
    let mut body_parameters = Vec::new();
    let mut literal_defaults = Vec::new();
    let mut previous_end = data.parameters.range.start;
    let mut names = HashSet::new();
    for &parameter in &data.parameters.nodes {
        let parameter = NodeRef::new(declaration.arena, declaration.file, parameter);
        let parameter_record = preflight_node(store, host, parameter)?;
        if parameter_record.range.start < previous_end
            || parameter_record.range.end > data.parameters.range.end
        {
            return Err(invariant(ClassInvariant::InvalidProperty(parameter)));
        }
        previous_end = parameter_record.range.end;
        let planned = match plan_constructor_parameter_with_body_mode(
            store,
            host,
            header.symbol,
            declaration,
            parameter,
            header.instance_members,
            type_context,
            true,
        )? {
            PlannedConstructorParameter::Primitive(planned) => {
                planned.with_type(ClassBodyParameterType::Known(planned.type_))
            }
            PlannedConstructorParameter::SourceBody(planned) => planned,
            PlannedConstructorParameter::Annotated(annotation) => {
                if annotation.initializer.is_some() || annotation.property.is_some() {
                    return Err(unsupported(ClassUnsupported::Member {
                        node: parameter,
                        kind: SyntaxKind::Parameter,
                    }));
                }
                let context = type_context
                    .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(declaration)))?;
                let proof = preflight_constructor_parameter_annotation(
                    store,
                    host,
                    context,
                    annotation.type_node,
                    None,
                )?;
                if !proof.bindings_are_published(store) {
                    return Err(unsupported(ClassUnsupported::PropertyType {
                        node: annotation.type_node,
                        kind: SyntaxKind::Parameter,
                    }));
                }
                let type_ = proof
                    .cached_type(store, host, Some(&context.global_types))?
                    .ok_or_else(|| {
                        unsupported(ClassUnsupported::PropertyType {
                            node: annotation.type_node,
                            kind: SyntaxKind::Parameter,
                        })
                    })?;
                ClassConstructorParameterPlan {
                    declaration: annotation.declaration,
                    symbol: annotation.symbol,
                    type_node: annotation.type_node,
                    type_: ClassBodyParameterType::Known(type_),
                    optional: annotation.optional,
                    initializer: None,
                    decorator: None,
                    property: None,
                }
            }
        };
        if !names.insert(planned.symbol)
            || planned.decorator.is_some()
            || header.ambient && planned.initializer.is_some()
        {
            return Err(unsupported(ClassUnsupported::Member {
                node: parameter,
                kind: SyntaxKind::Parameter,
            }));
        }
        if matches!(planned.type_, ClassBodyParameterType::Annotation(_))
            && let Some(initializer) = planned.initializer
        {
            literal_defaults.push(plan_source_constructor_literal_default(
                store,
                host,
                planned.declaration,
                planned.type_node,
                initializer,
            )?);
        }
        body_parameters.push(source_constructor_parameter(store, host, planned)?);
        parameters.push(planned);
    }
    i32::try_from(parameters.len())
        .map_err(|_| invariant(ClassInvariant::Capacity(declaration)))?;
    let body = match (data.body, header.ambient) {
        (None, true) => None,
        (None, false) if owner.declarations().is_some_and(|group| group.len() > 1) => None,
        (Some(body), false) => {
            let body = source_class_body(store, host, declaration, body)?;
            if preflight_node(store, host, body)?.range.start < data.parameters.range.end {
                return Err(invariant(ClassInvariant::InvalidDeclaration(body)));
            }
            Some(ClassBodyPlan {
                class_declaration: header.declaration,
                class_symbol: header.symbol,
                declaration,
                body,
                kind: ClassBodyKind::Constructor,
                parameters: body_parameters,
                return_annotation: None,
            })
        }
        _ => {
            return Err(unsupported(ClassUnsupported::Member {
                node: declaration,
                kind: SyntaxKind::Constructor,
            }));
        }
    };
    Ok((
        SourceClassConstructorPlan {
            declaration,
            symbol,
            visibility,
            parameters,
            literal_defaults,
        },
        body,
    ))
}

fn source_constructor_group_is_exact(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    header: &ClassDeclarationHeader,
    symbol: SemanticSymbolId,
    declaration: NodeRef,
) -> Result<bool, ClassError> {
    let Some(declarations) = store.symbol(symbol).and_then(|owner| owner.declarations()) else {
        return Ok(false);
    };
    if declarations == [declaration] {
        return Ok(true);
    }
    if header.ambient
        || header.abstract_class
        || header.base.is_some()
        || header.null_base.is_some()
        || declarations.len() < 2
    {
        return Err(unsupported(ClassUnsupported::Member {
            node: declaration,
            kind: SyntaxKind::Constructor,
        }));
    }
    let NodeData::ClassDeclaration(class) = &preflight_node(store, host, header.declaration)?.data
    else {
        return Ok(false);
    };
    let actual = class
        .members
        .nodes
        .iter()
        .filter_map(|&node| {
            let node = NodeRef::new(declaration.arena, declaration.file, node);
            host.node(node)
                .is_some_and(|record| record.kind == SyntaxKind::Constructor)
                .then_some(node)
        })
        .collect::<Vec<_>>();
    if actual != declarations || !declarations.contains(&declaration) {
        return Ok(false);
    }
    for (index, &node) in declarations.iter().enumerate() {
        let record = preflight_node(store, host, node)?;
        let NodeData::ConstructorDeclaration(constructor) = &record.data else {
            return Ok(false);
        };
        if record.parent != Some(header.declaration.node)
            || bound_symbol(store, host, node) != Some(symbol)
            || constructor.body.is_some() != (index + 1 == declarations.len())
        {
            return Ok(false);
        }
        if index > 0 {
            let Some(previous) = class
                .members
                .nodes
                .iter()
                .position(|member| *member == declarations[index - 1].node)
            else {
                return Ok(false);
            };
            if class.members.nodes.get(previous + 1) != Some(&node.node) {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

fn source_property_origin(
    store: &CanonicalTypeMapperStore,
    class: SemanticSymbolId,
    property: &ClassPropertyPlan,
) -> ClassMemberSource {
    let origin = if property.parameter_property {
        ClassMemberOrigin::ParameterProperty {
            parameter: property.declaration,
        }
    } else if property.javascript_constructor_assignment {
        ClassMemberOrigin::JavaScriptAssignment {
            assignment: property.declaration,
        }
    } else if property.auto_accessor {
        ClassMemberOrigin::AutoAccessor {
            initializer: property.initializer_node,
        }
    } else {
        ClassMemberOrigin::Field {
            initializer: property.initializer_node,
        }
    };
    ClassMemberSource {
        symbol: property.symbol,
        declaring_class: class,
        declaration: property.declaration,
        origin,
        side: property.side,
        visibility: if store
            .symbol(property.symbol)
            .is_some_and(|symbol| symbol.name().is_private_identifier())
        {
            ClassConstructorVisibility::Private
        } else {
            class_member_visibility(store, property.declaration)
        },
        readonly: property.readonly,
        abstract_: property.abstract_property,
    }
}

/// Plans owned members and body nodes. Body expressions are planned by the source provider.
#[cfg(test)]
pub(super) fn plan_source_class_members(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
) -> Result<SourceClassPlan, ClassError> {
    let retained = store.source_class_provenance_for_symbol(symbol);
    plan_source_class_members_with_context(
        store,
        host,
        symbol,
        retained.and_then(|provenance| provenance.prepared.plan.array_targets),
        retained.and_then(|provenance| provenance.prepared.plan.type_query_context.as_ref()),
    )
}

pub(super) fn plan_source_class_members_with_type_context(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
    type_context: Option<&ClassTypeQueryContext>,
) -> Result<SourceClassPlan, ClassError> {
    let array_targets = type_context
        .map(|context| CanonicalArrayTargets::from_global_types(&context.global_types))
        .or_else(|| {
            store
                .source_class_provenance_for_symbol(symbol)
                .and_then(|provenance| provenance.prepared.plan.array_targets)
        });
    plan_source_class_members_with_context(store, host, symbol, array_targets, type_context)
}

pub(super) fn plan_source_class_members_with_context(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
    array_targets: Option<CanonicalArrayTargets>,
    type_context: Option<&ClassTypeQueryContext>,
) -> Result<SourceClassPlan, ClassError> {
    let header = plan_class_declaration_header(store, host, symbol, true)?;
    let record = preflight_node(store, host, header.declaration)?;
    let NodeData::ClassDeclaration(class) = &record.data else {
        return Err(invariant(ClassInvariant::InvalidDeclaration(
            header.declaration,
        )));
    };
    if class.type_parameters.is_some()
        || !header.namespace_exports.is_empty()
        || header.null_base.is_some()
        || header
            .base
            .as_ref()
            .is_some_and(|base| !base.type_arguments.is_empty())
    {
        return Err(unsupported(ClassUnsupported::Generic(header.declaration)));
    }
    if let Some(base) = &header.base
        && base.constructor_value.is_none()
    {
        preflight_class_override_visibility(store, header.symbol, base.symbol, base.expression)?;
    }
    let revision = host
        .source(header.declaration)
        .ok_or_else(|| invariant(ClassInvariant::InvalidDeclaration(header.declaration)))?
        .0
        .revision();
    let mut plan = SourceClassPlan {
        header,
        array_targets,
        revision,
        type_query_context: type_context.cloned(),
        annotations: Vec::new(),
        properties: Vec::new(),
        annotated_properties: Vec::new(),
        function_properties: Vec::new(),
        initialized_properties: Vec::new(),
        methods: Vec::new(),
        constructor: None,
        constructor_overloads: Vec::new(),
        bodies: Vec::new(),
        sources: Vec::new(),
        bindings: Vec::new(),
    };
    let mut previous_end = class.members.range.start;
    for &member in &class.members.nodes {
        let member = NodeRef::new(plan.declaration().arena, plan.declaration().file, member);
        let record = preflight_node(store, host, member)?;
        if record.parent != Some(plan.declaration().node)
            || record.range.start < previous_end
            || record.range.end > class.members.range.end
        {
            return Err(invariant(ClassInvariant::InvalidProperty(member)));
        }
        previous_end = record.range.end;
        match &record.data {
            NodeData::ConstructorDeclaration(data) => {
                if plan.constructor.is_some() {
                    return Err(unsupported(ClassUnsupported::Member {
                        node: member,
                        kind: record.kind,
                    }));
                }
                let (constructor, body) =
                    plan_source_class_constructor(store, host, &plan.header, member, type_context)?;
                if data.body.is_none() && !plan.header.ambient {
                    if constructor.visibility != ClassConstructorVisibility::Public
                        || constructor.parameters.iter().any(|parameter| {
                            parameter.property.is_some() || parameter.initializer.is_some()
                        })
                    {
                        return Err(unsupported(ClassUnsupported::Member {
                            node: member,
                            kind: record.kind,
                        }));
                    }
                    plan.constructor_overloads.push(constructor);
                    continue;
                }
                if !plan.constructor_overloads.is_empty()
                    && constructor.visibility != ClassConstructorVisibility::Public
                {
                    return Err(unsupported(ClassUnsupported::Member {
                        node: member,
                        kind: record.kind,
                    }));
                }
                for parameter in &constructor.parameters {
                    if let Some(property) = source_parameter_property(store, host, parameter)? {
                        plan.sources
                            .push(source_property_origin(store, symbol, &property));
                        match parameter.type_ {
                            ClassBodyParameterType::Known(type_) => {
                                plan.properties.push((property, type_));
                            }
                            ClassBodyParameterType::Annotation(_) => {
                                plan.annotated_properties.push(property);
                            }
                            ClassBodyParameterType::ClassReference { .. }
                            | ClassBodyParameterType::Tuple(_)
                            | ClassBodyParameterType::PrimitiveUnion(_) => {
                                return Err(invariant(ClassInvariant::InvalidProperty(
                                    parameter.declaration,
                                )));
                            }
                        }
                    }
                }
                if let Some(body) = body {
                    plan.bodies.push(body);
                }
                plan.constructor = Some(constructor);
            }
            NodeData::MethodDeclaration(_) => {
                let method = plan_method_with_body_mode(
                    store,
                    host,
                    symbol,
                    member,
                    (plan.header.instance_members, plan.header.static_members),
                    plan.header.ambient,
                    true,
                    array_targets,
                    type_context,
                )?;
                let return_type = method
                    .return_type_node
                    .map(|annotation| {
                        let record = preflight_node(store, host, annotation)?;
                        if record.flags.0 != 0 {
                            return Err(unsupported(ClassUnsupported::PropertyType {
                                node: annotation,
                                kind: record.kind,
                            }));
                        }
                        if !matches!(record.data, NodeData::KeywordTypeNode(_)) {
                            if type_context.is_some()
                                && annotations::source_class_method_return_annotation_is_owned(
                                    store, host, symbol, annotation,
                                )
                            {
                                return Ok(ClassBodyParameterType::Annotation(annotation));
                            }
                            return Err(unsupported(ClassUnsupported::PropertyType {
                                node: annotation,
                                kind: record.kind,
                            }));
                        }
                        let type_ = primitive_keyword_type(store, annotation, record.kind)?;
                        validate_index_type_cache(store, annotation, type_)?;
                        Ok(ClassBodyParameterType::Known(type_))
                    })
                    .transpose()?;
                let (arena, _) = host
                    .source(member)
                    .ok_or_else(|| invariant(ClassInvariant::InvalidDeclaration(member)))?;
                if !plan
                    .sources
                    .iter()
                    .any(|source| source.symbol == method.symbol)
                {
                    plan.sources.push(ClassMemberSource {
                        symbol: method.symbol,
                        declaring_class: symbol,
                        declaration: member,
                        origin: ClassMemberOrigin::Method,
                        side: method.side,
                        visibility: if store
                            .symbol(method.symbol)
                            .is_some_and(|symbol| symbol.name().is_private_identifier())
                        {
                            ClassConstructorVisibility::Private
                        } else {
                            class_member_visibility(store, member)
                        },
                        readonly: false,
                        abstract_: ts_binder::canonical_has_syntactic_modifier(
                            arena,
                            member.node,
                            SyntaxKind::AbstractKeyword,
                        ),
                    });
                }
                if let Some(body) = method.body {
                    let mut parameters = Vec::new();
                    for parameter in &method.parameters {
                        let record = preflight_node(store, host, parameter.declaration)?;
                        let NodeData::ParameterDeclaration(data) = &record.data else {
                            return Err(invariant(ClassInvariant::InvalidProperty(
                                parameter.declaration,
                            )));
                        };
                        parameters.push(ClassBodyParameterPlan {
                            declaration: parameter.declaration,
                            name_node: NodeRef::new(member.arena, member.file, data.name),
                            symbol: parameter.symbol,
                            property_symbol: None,
                            annotation: parameter.type_node,
                            initializer: None,
                            type_: if parameter.optional {
                                ClassBodyParameterType::Known(class_method_parameter_type(
                                    store, *parameter,
                                )?)
                            } else {
                                parameter.type_
                            },
                            optional: parameter.optional,
                        });
                    }
                    plan.bodies.push(ClassBodyPlan {
                        class_declaration: plan.declaration(),
                        class_symbol: symbol,
                        declaration: member,
                        body,
                        kind: ClassBodyKind::Method {
                            symbol: method.symbol,
                            side: method.side,
                        },
                        parameters,
                        return_annotation: method.return_type_node,
                    });
                }
                plan.methods.push(SourceClassMethodPlan {
                    method,
                    return_type,
                });
            }
            NodeData::PropertyDeclaration(_) => {
                let property = plan_property_with_body_mode(
                    store,
                    host,
                    symbol,
                    member,
                    plan.header.instance_members,
                    plan.header.static_members,
                    true,
                )?;
                if property.initializer_parameter_name.is_some()
                    || property.initializer_assertion.is_some()
                {
                    return Err(unsupported(ClassUnsupported::PropertyInitializer(member)));
                }
                plan.sources
                    .push(source_property_origin(store, symbol, &property));
                if let Some(initializer) = property.initializer_node
                    && (matches!(
                        store.source_node_kind(initializer),
                        Some(
                            SyntaxKind::PropertyAccessExpression
                                | SyntaxKind::ArrowFunction
                                | SyntaxKind::Identifier
                                | SyntaxKind::NullKeyword
                                | SyntaxKind::ObjectLiteralExpression
                        )
                    ) || source_enum_member_const_assertion(store, host, initializer)?)
                {
                    plan.bodies.push(ClassBodyPlan {
                        class_declaration: plan.declaration(),
                        class_symbol: symbol,
                        declaration: member,
                        body: initializer,
                        kind: ClassBodyKind::PropertyInitializer {
                            symbol: property.symbol,
                            side: property.side,
                        },
                        parameters: Vec::new(),
                        return_annotation: (property.type_node != initializer)
                            .then_some(property.type_node),
                    });
                    plan.initialized_properties.push(property);
                } else if store.source_node_kind(property.type_node)
                    == Some(SyntaxKind::FunctionType)
                    && property.initializer_node.is_none()
                {
                    let function = super::functions::plan_function_type(
                        store,
                        host,
                        property.type_node,
                        None,
                        false,
                        None,
                    )
                    .map_err(|_| {
                        unsupported(ClassUnsupported::PropertyType {
                            node: property.type_node,
                            kind: SyntaxKind::FunctionType,
                        })
                    })?;
                    if !function.type_parameters.is_empty() {
                        return Err(unsupported(ClassUnsupported::PropertyType {
                            node: property.type_node,
                            kind: SyntaxKind::FunctionType,
                        }));
                    }
                    plan.function_properties.push((property, function));
                } else if property.initializer_node.is_none()
                    && type_context.is_some()
                    && !matches!(
                        preflight_node(store, host, property.type_node)?.data,
                        NodeData::KeywordTypeNode(_)
                    )
                {
                    if property.optional
                        && !matches!(
                            preflight_node(store, host, property.type_node)?.data,
                            NodeData::TypeReferenceNode(_)
                        )
                    {
                        return Err(unsupported(ClassUnsupported::PropertyType {
                            node: property.type_node,
                            kind: preflight_node(store, host, property.type_node)?.kind,
                        }));
                    }
                    plan.annotated_properties.push(property);
                } else {
                    let type_ = planned_property_type(store, host, &property)?;
                    validate_property_cache_state(store, &property, type_)?;
                    plan.properties.push((property, type_));
                }
            }
            NodeData::ClassStaticBlockDeclaration(data) => {
                if record.kind != SyntaxKind::ClassStaticBlockDeclaration
                    || record.flags.0 != 0
                    || data.facts != 0
                    || data.symbol.is_some()
                    || data.next_container.is_some()
                    || data.return_flow_node.is_some()
                {
                    return Err(invariant(ClassInvariant::InvalidDeclaration(member)));
                }
                if let Some(modifiers) = &data.modifiers {
                    let [modifier] = modifiers.list.nodes.as_slice() else {
                        return Err(invariant(ClassInvariant::InvalidDeclaration(member)));
                    };
                    let modifier = NodeRef::new(member.arena, member.file, *modifier);
                    let token = preflight_node(store, host, modifier)?;
                    if modifiers.flags.0 != 0
                        || modifiers.list.has_trailing_comma
                        || token.kind != SyntaxKind::StaticKeyword
                        || token.flags.0 != 0
                        || token.parent != Some(member.node)
                        || !matches!(token.data, NodeData::Token(_))
                    {
                        return Err(invariant(ClassInvariant::InvalidDeclaration(member)));
                    }
                } else {
                    return Err(invariant(ClassInvariant::InvalidDeclaration(member)));
                }
                let body = source_class_body(store, host, member, data.body)?;
                plan.bodies.push(ClassBodyPlan {
                    class_declaration: plan.declaration(),
                    class_symbol: symbol,
                    declaration: member,
                    body,
                    kind: ClassBodyKind::StaticBlock,
                    parameters: Vec::new(),
                    return_annotation: None,
                });
            }
            _ => {
                return Err(unsupported(ClassUnsupported::Member {
                    node: member,
                    kind: record.kind,
                }));
            }
        }
    }
    plan_source_class_expandos(store, host, &mut plan)?;
    validate_source_class_member_tables(store, &plan)?;
    if let Some(context) = &plan.type_query_context {
        plan.annotations = plan
            .annotated_properties
            .iter()
            .map(|property| property.type_node)
            .chain(plan.initialized_properties.iter().filter_map(|property| {
                (property.initializer_node != Some(property.type_node)
                    && store.source_node_kind(property.type_node) != Some(SyntaxKind::FunctionType))
                .then_some(property.type_node)
            }))
            .chain(
                plan.constructor_overloads
                    .iter()
                    .chain(plan.constructor.iter())
                    .flat_map(|constructor| {
                        constructor.parameters.iter().filter_map(|parameter| {
                            match parameter.type_ {
                                ClassBodyParameterType::Annotation(node) => Some(node),
                                _ => None,
                            }
                        })
                    }),
            )
            .chain(plan.methods.iter().flat_map(|method| {
                method
                    .method
                    .parameters
                    .iter()
                    .filter_map(|parameter| match parameter.type_ {
                        ClassBodyParameterType::Annotation(node) => Some(node),
                        _ => None,
                    })
            }))
            .chain(
                plan.methods
                    .iter()
                    .filter_map(|method| match method.return_type {
                        Some(ClassBodyParameterType::Annotation(node)) => Some(node),
                        _ => None,
                    }),
            )
            .collect();
        plan.annotations.sort_unstable();
        plan.annotations.dedup();
        for &annotation in plan.annotation_nodes() {
            preflight_source_class_annotation(
                store,
                host,
                &context.global_types,
                context.options,
                annotation,
                symbol,
            )?;
        }
        for property in &plan.annotated_properties {
            if property.optional && !property.parameter_property {
                let expected = preflight_source_class_annotation(
                    store,
                    host,
                    &context.global_types,
                    context.options,
                    property.type_node,
                    symbol,
                )?
                .cached_type(store, host, Some(&context.global_types))?;
                validate_property_value_cache_state(store, property, expected)?;
            } else {
                annotations::validate_source_annotation_value_cache(
                    store,
                    host,
                    context,
                    symbol,
                    property.type_node,
                    property.symbol,
                )?;
            }
        }
    }
    plan.bindings = capture_source_class_bindings(store, &plan)?;
    if let Some(retained) = store.source_class_provenance_for_symbol(symbol)
        && plan.array_targets != retained.prepared.plan.array_targets
        && !plan.methods.iter().any(|method| {
            method.method.parameters.iter().any(|parameter| {
                parameter.type_node.is_some_and(|annotation| {
                    store.source_node_kind(annotation) == Some(SyntaxKind::ArrayType)
                })
            })
        })
    {
        // Methods without array annotations do not read these targets.
        // Reuse a saved input only when every other source-plan field matches.
        let current_targets = plan.array_targets;
        plan.array_targets = retained.prepared.plan.array_targets;
        if plan != retained.prepared.plan {
            plan.array_targets = current_targets;
        }
    }
    Ok(plan)
}

fn constructor_heritage_error(
    node: NodeRef,
    symbol: SemanticSymbolId,
    error: DeclaredConstructorValueError,
) -> ClassError {
    match error {
        DeclaredConstructorValueError::DeclaredType(error) => error.into(),
        DeclaredConstructorValueError::Capacity(node)
        | DeclaredConstructorValueError::Members(PropertyObjectError::Capacity(node)) => {
            invariant(ClassInvariant::Capacity(node))
        }
        DeclaredConstructorValueError::Unsupported { .. }
        | DeclaredConstructorValueError::Members(PropertyObjectError::UnsupportedMember {
            ..
        }) => unsupported(ClassUnsupported::Heritage(node)),
        _ => invariant(ClassInvariant::InvalidHeritageCache(symbol)),
    }
}

fn constructor_base_member_error(node: NodeRef, error: PropertyObjectError) -> ClassError {
    match error {
        PropertyObjectError::Capacity(node) => invariant(ClassInvariant::Capacity(node)),
        PropertyObjectError::UnsupportedMember { .. } => {
            unsupported(ClassUnsupported::Heritage(node))
        }
        _ => invariant(ClassInvariant::InvalidHeritage(node)),
    }
}

fn validate_declared_heritage_edge_cache(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    edge: &DirectClassBasePlan,
) -> Result<(), ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidHeritageCache(edge.symbol));
    let value = edge.constructor_value.as_ref().ok_or_else(invalid)?;
    let constructor = resolve_declared_constructor_value(store, host, value)
        .map_err(|error| constructor_heritage_error(edge.expression, edge.symbol, error))?;
    let declaration = value.construct_declarations().next().ok_or_else(invalid)?;
    let signature = resolve_declared_construct_signature(store, host, value, declaration)
        .map_err(|error| constructor_heritage_error(edge.expression, edge.symbol, error))?;
    for (node, expected) in [
        (
            edge.expression,
            constructor.map(|value| value.constructor_type()),
        ),
        (
            edge.node,
            signature.map(|signature| signature.return_type()),
        ),
    ] {
        if store.type_node_links(node).is_some_and(|links| {
            links != &TypeNodeLinks::default()
                && expected.is_none_or(|type_| {
                    links
                        != &TypeNodeLinks {
                            resolved_type: Some(type_),
                            ..TypeNodeLinks::default()
                        }
                })
        }) {
            return Err(invalid());
        }
    }
    if store
        .symbol_node_links(edge.expression)
        .is_some_and(|links| {
            links != &SymbolNodeLinks::default()
                && links
                    != &SymbolNodeLinks {
                        resolved_symbol: Some(edge.symbol),
                    }
        })
        || store
            .symbol_node_links(edge.node)
            .is_some_and(|links| links != &SymbolNodeLinks::default())
    {
        return Err(invalid());
    }
    Ok(())
}

fn declared_class_base_bindings(
    store: &CanonicalTypeMapperStore,
    value: &DeclaredConstructorValuePlan,
    constructor: &PropertyObjectPlan,
    instance: &PropertyObjectPlan,
) -> Result<Vec<SourceClassBinding>, ClassError> {
    let mut symbols = vec![value.value_symbol(), constructor.symbol, instance.symbol];
    for plan in [constructor, instance] {
        symbols.extend(plan.properties.iter().map(|property| property.symbol));
        for signature in &plan.call_signatures {
            symbols.push(signature.symbol);
            symbols.extend(
                signature
                    .parameters
                    .iter()
                    .map(|parameter| parameter.symbol),
            );
        }
    }
    symbols.sort_unstable();
    symbols.dedup();
    symbols
        .into_iter()
        .map(|symbol| source_class_binding(store, symbol))
        .collect()
}

/// Uses the declared constructor provider, with the expression's real value owner.
fn declared_class_base_members(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    edge: &DirectClassBasePlan,
) -> Result<DeclaredClassBaseMembers, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidHeritageCache(edge.symbol));
    let value = edge.constructor_value.as_ref().ok_or_else(invalid)?;
    let resolved = resolve_declared_constructor_value(store, host, value)
        .map_err(|error| constructor_heritage_error(edge.expression, edge.symbol, error))?
        .ok_or_else(|| unsupported(ClassUnsupported::Heritage(edge.expression)))?;
    let constructor = plan_interface(store, host, value.owner_symbol())
        .map_err(|error| constructor_base_member_error(edge.expression, error))?;
    if !interface_state(store, &constructor, resolved.constructor_type())
        .map_err(|error| constructor_base_member_error(edge.expression, error))?
        .is_resolved()
    {
        return Err(unsupported(ClassUnsupported::Heritage(edge.expression)));
    }
    let signatures = constructor
        .call_signatures
        .iter()
        .filter(|signature| signature.is_construct())
        .map(|planned| {
            let signature = super::object_members::validate_resolved_call_signature(store, planned)
                .ok_or_else(invalid)?;
            source_class_callable_projection(
                store,
                resolved.constructor_type(),
                signature,
                edge.symbol,
            )
        })
        .collect::<Result<Vec<_>, ClassError>>()?;
    let instance_type = signatures
        .first()
        .and_then(|signature| signature.return_type)
        .ok_or_else(invalid)?;
    if signatures
        .iter()
        .any(|signature| signature.return_type != Some(instance_type))
    {
        return Err(unsupported(ClassUnsupported::Heritage(edge.expression)));
    }
    let instance_symbol = store
        .type_payload(instance_type)
        .and_then(TypeRecord::symbol)
        .ok_or_else(|| unsupported(ClassUnsupported::Heritage(edge.expression)))?;
    if !store.type_payload(instance_type).is_some_and(|record| {
        matches!(record.data(), TypeData::Interface(instance)
            if super::object_members::valid_thisless_interface_identity(instance))
    }) {
        return Err(unsupported(ClassUnsupported::Heritage(edge.expression)));
    }
    let instance = plan_interface(store, host, instance_symbol)
        .map_err(|error| constructor_base_member_error(edge.expression, error))?;
    let instance_properties = instance
        .properties
        .iter()
        .map(|property| property.symbol)
        .collect();
    let static_properties = constructor
        .properties
        .iter()
        .filter(|property| {
            store
                .symbol(property.symbol)
                .is_some_and(|record| record.name().as_utf8() != Some(PROTOTYPE_NAME))
        })
        .map(|property| property.symbol)
        .collect();
    let bindings = declared_class_base_bindings(store, value, &constructor, &instance)?;
    let base = DeclaredClassBaseMembers {
        value: value.clone(),
        constructor,
        instance,
        identities: ClassBaseIdentities {
            symbol: resolved.value_symbol(),
            instance_type,
            value_type: resolved.constructor_type(),
        },
        signatures,
        instance_properties,
        static_properties,
        bindings,
    };
    if !declared_class_base_is_current(store, &base) {
        return Err(invalid());
    }
    Ok(base)
}

/// Rechecks the original declared plans before any warm class or call answer.
fn declared_class_base_is_current(
    store: &CanonicalTypeMapperStore,
    base: &DeclaredClassBaseMembers,
) -> bool {
    let value = &base.value;
    if base.identities.symbol != value.value_symbol()
        || base.constructor.symbol != value.owner_symbol()
        || store.source_direct_type_annotation(value.value_declaration())
            != Some(value.value_annotation())
        || store.value_symbol_links(value.value_symbol())
            != Some(&ValueSymbolLinks {
                resolved_type: Some(base.identities.value_type),
                ..ValueSymbolLinks::default()
            })
        || store.type_node_links(value.value_annotation())
            != Some(&TypeNodeLinks {
                resolved_type: Some(base.identities.value_type),
                ..TypeNodeLinks::default()
            })
        || store.symbol_node_links(value.value_annotation())
            != Some(&SymbolNodeLinks {
                resolved_symbol: Some(value.owner_symbol()),
            })
        || base
            .bindings
            .iter()
            .any(|binding| source_class_binding(store, binding.symbol).as_ref() != Ok(binding))
        || !store.source_merged_symbol_declarations_match(value.value_symbol())
        || !store.source_merged_symbol_declarations_match(base.constructor.symbol)
        || !store.source_merged_symbol_declarations_match(base.instance.symbol)
        || !matches!(
            interface_state(store, &base.constructor, base.identities.value_type),
            Ok(super::object_members::PropertyObjectState::Resolved(_))
        )
    {
        return false;
    }
    if !matches!(
        interface_state(store, &base.instance, base.identities.instance_type),
        Ok(super::object_members::PropertyObjectState::Resolved(_))
    ) || !store
        .type_payload(base.identities.instance_type)
        .is_some_and(|record| {
            matches!(record.data(), TypeData::Interface(instance)
            if super::object_members::valid_thisless_interface_identity(instance))
        })
        || base.instance.heritage.is_some()
        || !base.instance.call_signatures.is_empty()
        || base
            .instance
            .properties
            .iter()
            .map(|property| property.symbol)
            .collect::<Vec<_>>()
            != base.instance_properties
        || base
            .constructor
            .properties
            .iter()
            .filter(|property| {
                store
                    .symbol(property.symbol)
                    .is_some_and(|record| record.name().as_utf8() != Some(PROTOTYPE_NAME))
            })
            .map(|property| property.symbol)
            .collect::<Vec<_>>()
            != base.static_properties
        || base.signatures.is_empty()
    {
        return false;
    }
    let planned = base
        .constructor
        .call_signatures
        .iter()
        .filter(|signature| signature.is_construct())
        .collect::<Vec<_>>();
    if planned.len() != base.signatures.len()
        || planned
            .iter()
            .map(|signature| signature.declaration)
            .collect::<Vec<_>>()
            != value.construct_declarations().collect::<Vec<_>>()
    {
        return false;
    }
    planned
        .iter()
        .zip(&base.signatures)
        .all(|(planned, callable)| {
            super::object_members::validate_resolved_call_signature(store, planned)
                == Some(callable.signature)
                && callable.return_type == Some(base.identities.instance_type)
                && source_class_callable_projection(
                    store,
                    base.identities.value_type,
                    callable.signature,
                    value.value_symbol(),
                )
                .as_ref()
                    == Ok(callable)
        })
}

/// The store publishes this edge only from the prepared source-class receipt.
pub(super) fn source_constructor_heritage_is_exact(
    store: &CanonicalTypeMapperStore,
    instance: TypeId,
    edge: DirectClassHeritageProvenance,
) -> bool {
    let Some(provenance) = store.source_class_provenance(instance) else {
        return false;
    };
    let Some(SourceClassBaseMembers::Constructor(base)) = &provenance.base_members else {
        return false;
    };
    let plan = &provenance.prepared.plan;
    provenance.prepared.instance_type == instance
        && provenance.prepared.value_type == edge.owner_value_type
        && plan.symbol() == edge.owner_symbol
        && plan.header.base.as_ref().is_some_and(|planned| {
            planned.symbol == edge.base_symbol
                && planned.constructor_value.as_ref() == Some(&base.value)
                && store.source_node_parent(planned.expression)
                    == Some(SourceNodeParent::Parent(planned.node))
                && store.source_node_parent(planned.node)
                    == Some(SourceNodeParent::Parent(planned.clause))
                && store.source_node_parent(planned.clause)
                    == Some(SourceNodeParent::Parent(plan.declaration()))
        })
        && base.identities
            == ClassBaseIdentities {
                symbol: edge.base_symbol,
                instance_type: edge.base_instance_type,
                value_type: edge.base_value_type,
            }
        && instance != edge.base_instance_type
        && declared_class_base_is_current(store, base)
}

pub(super) fn source_constructor_base_member_owner(
    store: &CanonicalTypeMapperStore,
    instance: TypeId,
    side: ClassPropertySide,
    owner: SemanticSymbolId,
) -> Option<bool> {
    let provenance = store.source_class_provenance(instance)?;
    let SourceClassBaseMembers::Constructor(_) = provenance.base_members.as_ref()? else {
        return None;
    };
    let edge = store.direct_class_heritage_provenance(instance)?;
    Some(
        source_constructor_heritage_is_exact(store, instance, edge)
            && store
                .type_payload(match side {
                    ClassPropertySide::Instance => edge.base_instance_type,
                    ClassPropertySide::Static => edge.base_value_type,
                })
                .and_then(TypeRecord::symbol)
                == Some(owner),
    )
}

/// Proves an inherited interface property on the receiver's actual class side.
pub(super) fn source_constructor_base_property_is_exact(
    store: &CanonicalTypeMapperStore,
    receiver: TypeId,
    property: SemanticSymbolId,
) -> bool {
    let Some(provenance) = store
        .type_payload(receiver)
        .and_then(TypeRecord::symbol)
        .and_then(|owner| store.source_class_provenance_for_symbol(owner))
    else {
        return false;
    };
    let side = if receiver == provenance.prepared.instance_type {
        ClassPropertySide::Instance
    } else if receiver == provenance.prepared.value_type {
        ClassPropertySide::Static
    } else {
        return false;
    };
    let Some(SourceClassBaseMembers::Constructor(base)) = &provenance.base_members else {
        return false;
    };
    let Some(edge) = store.direct_class_heritage_provenance(provenance.prepared.instance_type)
    else {
        return false;
    };
    if validate_source_class_stored_header(store, provenance).is_err()
        || !source_constructor_heritage_is_exact(store, provenance.prepared.instance_type, edge)
    {
        return false;
    }
    let (base_type, owner, properties) = match side {
        ClassPropertySide::Instance => (
            base.identities.instance_type,
            base.instance.symbol,
            &base.instance_properties,
        ),
        ClassPropertySide::Static => (
            base.identities.value_type,
            base.constructor.symbol,
            &base.static_properties,
        ),
    };
    let Some(member) = store.symbol(property) else {
        return false;
    };
    store.get_parent_of_symbol(property) == Some(owner)
        && store.get_merged_symbol(property) == Some(property)
        && properties.contains(&property)
        && [receiver, base_type].into_iter().all(|type_| {
            store
                .type_payload(type_)
                .and_then(|record| record.data().structured())
                .filter(|structured| {
                    structured
                        .properties
                        .as_deref()
                        .is_some_and(|properties| properties.contains(&property))
                })
                .and_then(|structured| structured.members)
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get(member.name()))
                == Some(property)
        })
}

fn source_class_base_members(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &SourceClassPlan,
) -> Result<Option<SourceClassBaseMembers>, ClassError> {
    let Some(base) = &plan.header.base else {
        return Ok(None);
    };
    if base.constructor_value.is_some() {
        let members = declared_class_base_members(store, host, base)?;
        if store
            .declared_type_links(plan.symbol())
            .and_then(|links| links.declared_type)
            == Some(members.identities.instance_type)
        {
            return Err(unsupported(ClassUnsupported::Heritage(base.expression)));
        }
        return Ok(Some(SourceClassBaseMembers::Constructor(Box::new(members))));
    }
    let instance = store
        .declared_type_links(base.symbol)
        .and_then(|links| links.declared_type)
        .ok_or_else(|| unsupported(ClassUnsupported::Heritage(base.expression)))?;
    if let Some(provenance) = store.source_class_provenance_for_symbol(base.symbol) {
        validate_source_class_header(store, host, provenance)?;
        if !provenance.complete {
            return Err(unsupported(ClassUnsupported::Heritage(base.expression)));
        }
        return Ok(Some(SourceClassBaseMembers::Class(
            provenance.members.clone(),
        )));
    }
    let query = plan_nongeneric_class_member_query(store, host, base.symbol)?;
    let members = match &query {
        ClassMemberQueryPlan::Direct(class) => class_member_state(store, host, class)?,
        ClassMemberQueryPlan::Derived { class, base } => {
            let base_instance = store
                .declared_type_links(base.class.symbol)
                .and_then(|links| links.declared_type)
                .ok_or_else(|| unsupported(ClassUnsupported::Heritage(base.class.declaration)))?;
            let base_value = resolved_class_value_type(store, base.class.symbol)
                .ok_or_else(|| unsupported(ClassUnsupported::Heritage(base.class.declaration)))?;
            let base_members =
                completed_class_members(store, host, base, base_instance, base_value).ok_or_else(
                    || invariant(ClassInvariant::InvalidHeritageCache(base.class.symbol)),
                )?;
            let value = resolved_class_value_type(store, class.class.symbol)
                .ok_or_else(|| unsupported(ClassUnsupported::Heritage(class.class.declaration)))?;
            let surfaces = prepare_derived_member_surfaces(store, class, base)?;
            completed_derived_class_members(store, class, &base_members, instance, value, &surfaces)
        }
    }
    .ok_or_else(|| unsupported(ClassUnsupported::Heritage(base.expression)))?;
    Ok(Some(SourceClassBaseMembers::Class(members)))
}

fn source_class_entries(
    store: &CanonicalTypeMapperStore,
    plan: &SourceClassPlan,
    side: ClassPropertySide,
    base: Option<&SourceClassBaseMembers>,
) -> Result<(Vec<(EscapedName, SemanticSymbolId)>, usize), ClassError> {
    let table = match side {
        ClassPropertySide::Instance => plan.header.instance_members,
        ClassPropertySide::Static => Some(plan.header.static_members),
    };
    let owned = plan
        .sources
        .iter()
        .filter(|source| source.side == side)
        .map(|source| source.symbol)
        .collect::<HashSet<_>>();
    let mut entries = table
        .and_then(|table| store.symbol_table(table))
        .into_iter()
        .flat_map(ts_binder::semantic::SymbolTable::iter)
        .filter(|(_, symbol)| owned.contains(symbol))
        .map(|(name, symbol)| (name.to_owned(), symbol))
        .collect::<Vec<_>>();
    let mut names = entries
        .iter()
        .map(|(name, _)| name.clone())
        .collect::<HashSet<_>>();
    if let Some(base) = base {
        let inherited = match side {
            ClassPropertySide::Instance => base.instance_properties(),
            ClassPropertySide::Static => base.static_properties(),
        };
        for &symbol in inherited {
            let record = store
                .symbol(symbol)
                .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(plan.symbol())))?;
            if names.insert(record.name().to_owned()) {
                entries.push((record.name().to_owned(), symbol));
            }
        }
    }
    let mut ordered = Vec::with_capacity(entries.len());
    for (name, symbol) in entries {
        let record = store
            .symbol(symbol)
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(plan.symbol())))?;
        let first = record
            .declarations()
            .and_then(|declarations| declarations.first())
            .copied()
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(symbol)))?;
        let declaration = record
            .value_declaration()
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(symbol)))?;
        let contained = source_declaration_is_within(store, declaration, plan.declaration());
        let file = store
            .source_file_rank(first.file)
            .ok_or_else(|| invariant(ClassInvariant::InvalidDeclaration(first)))?;
        let start = store
            .source_node_start(first)
            .ok_or_else(|| invariant(ClassInvariant::InvalidDeclaration(first)))?;
        ordered.push((!contained, file, start, name, symbol));
    }
    ordered.sort();
    let contained_count = ordered.iter().take_while(|entry| !entry.0).count();
    Ok((
        ordered
            .into_iter()
            .map(|(_, _, _, name, symbol)| (name, symbol))
            .collect(),
        contained_count,
    ))
}

fn source_class_inherited_indexes(
    store: &CanonicalTypeMapperStore,
    base: Option<&SourceClassBaseMembers>,
) -> Result<Option<Vec<IndexInfoId>>, ClassError> {
    let Some(base) = base else {
        return Ok(None);
    };
    let structured = store
        .type_payload(base.identities().instance_type)
        .and_then(|record| record.data().structured())
        .ok_or_else(|| {
            invariant(ClassInvariant::InvalidInstanceMembers(
                base.identities().symbol,
            ))
        })?;
    Ok(structured.index_infos.clone())
}

fn source_declaration_is_within(
    store: &CanonicalTypeMapperStore,
    declaration: NodeRef,
    container: NodeRef,
) -> bool {
    let mut current = Some(declaration);
    let mut seen = HashSet::new();
    while let Some(node) = current {
        if node == container {
            return true;
        }
        if !seen.insert(node) {
            return false;
        }
        current = match store.source_node_parent(node) {
            Some(SourceNodeParent::Parent(parent)) => Some(parent),
            _ => None,
        };
    }
    false
}

fn source_inherited_values(
    store: &CanonicalTypeMapperStore,
    base: Option<&SourceClassBaseMembers>,
) -> Result<Vec<(SemanticSymbolId, TypeId, Option<SignatureId>)>, ClassError> {
    let Some(base) = base else {
        return Ok(Vec::new());
    };
    base.instance_properties()
        .iter()
        .chain(base.static_properties())
        .map(|&symbol| {
            let type_ = store
                .value_symbol_links(symbol)
                .and_then(|links| links.resolved_type)
                .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))?;
            let signature = if store
                .symbol(symbol)
                .is_some_and(|symbol| symbol.flags().contains(SymbolFlags::METHOD))
            {
                let record = store
                    .type_payload(type_)
                    .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))?;
                let TypeData::Object(object) = record.data() else {
                    return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
                };
                let [signature] = object.structured.signatures.as_deref().unwrap_or_default()
                else {
                    return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
                };
                Some(*signature)
            } else {
                None
            };
            Ok((symbol, type_, signature))
        })
        .collect()
}

fn source_class_minimum<T>(
    parameters: &[ClassConstructorParameterPlan<T>],
) -> Result<i32, ClassError> {
    parameters
        .iter()
        .enumerate()
        .rev()
        .find(|(_, parameter)| !parameter.optional && parameter.initializer.is_none())
        .map_or(Ok(0), |(index, parameter)| {
            i32::try_from(index + 1)
                .map_err(|_| invariant(ClassInvariant::Capacity(parameter.declaration)))
        })
}

fn source_class_signature_valid(
    store: &CanonicalTypeMapperStore,
    signature: SignatureId,
    declaration: Option<NodeRef>,
    flags: SignatureFlags,
    parameters: &[SemanticSymbolId],
    return_type: Option<TypeId>,
    minimum: i32,
) -> bool {
    let parameter_types = parameters
        .iter()
        .map(|symbol| {
            store
                .value_symbol_links(*symbol)
                .and_then(|links| links.resolved_type)
        })
        .collect::<Option<Vec<_>>>();
    store.signature(signature).is_some_and(|record| {
        record.declaration() == declaration
            && record.flags() == flags
            && record.parameters() == parameters
            && record.type_parameters().is_empty()
            && record.this_parameter().is_none()
            && record.min_argument_count() == minimum
            && (record.resolved_min_argument_count() == -1
                || record.resolved_min_argument_count() == minimum)
            && record.resolved_return_type() == return_type
            && record.resolved_type_predicate().is_none()
            && record.target().is_none()
            && record.mapper().is_none()
            && record.isolated_signature_type().is_none()
            && record.composite().is_none()
            && store
                .callable_signature_parameter_types(signature)
                .is_none_or(|cached| parameter_types.as_deref() == Some(cached))
    })
}

fn source_constructor_flags(
    store: &CanonicalTypeMapperStore,
    plan: &SourceClassPlan,
    base: Option<&SourceClassBaseMembers>,
) -> Result<SignatureFlags, ClassError> {
    let inherited = if plan.inherited_construct_count() != 0 {
        let signature = base
            .ok_or_else(|| invariant(ClassInvariant::InvalidHeritageCache(plan.symbol())))?
            .default_construct_signature();
        store
            .signature(signature)
            .ok_or_else(|| invariant(ClassInvariant::InvalidConstructSignature(plan.symbol())))?
            .flags()
            & !SignatureFlags::ABSTRACT
    } else {
        SignatureFlags::CONSTRUCT
    };
    Ok(inherited
        | if plan.header.abstract_class {
            SignatureFlags::ABSTRACT
        } else {
            SignatureFlags::NONE
        })
}

fn source_class_object_valid(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
    symbol: SemanticSymbolId,
    structured: &StructuredTypeData,
) -> bool {
    store.type_payload(type_).is_some_and(|record| {
        record.flags() == TypeFlags::OBJECT
            && record.object_flags() == (ObjectFlags::ANONYMOUS | ObjectFlags::MEMBERS_RESOLVED)
            && record.symbol() == Some(symbol)
            && record.alias().is_none()
            && matches!(record.data(), TypeData::Object(object) if object == &ObjectTypeData {
                structured: structured.clone(), ..ObjectTypeData::default()
            })
    })
}

fn source_class_method_signatures(
    prepared: &PreparedSourceClass,
    symbol: SemanticSymbolId,
) -> Vec<SignatureId> {
    prepared
        .plan
        .methods
        .iter()
        .zip(&prepared.methods)
        .filter(|(method, _)| {
            method.method.symbol == symbol
                && (!method.method.overload || method.method.body.is_none())
        })
        .map(|(_, (_, signature))| *signature)
        .collect()
}

fn class_method_parameter_type(
    store: &CanonicalTypeMapperStore,
    parameter: ClassMethodParameterPlan,
) -> Result<TypeId, ClassError> {
    optional_constructor_parameter_type(
        store,
        parameter.type_.resolved(store)?,
        parameter.optional,
        parameter.declaration,
    )?
    .ok_or_else(|| {
        invariant(ClassInvariant::InvalidPropertyTypeCache(
            parameter.declaration,
        ))
    })
}

fn class_method_minimum(method: &ClassMethodPlan) -> Result<i32, ClassError> {
    let count = method
        .parameters
        .iter()
        .rposition(|parameter| !parameter.optional)
        .map_or(0, |index| index + 1);
    i32::try_from(count).map_err(|_| invariant(ClassInvariant::Capacity(method.declaration)))
}

fn source_table_matches(
    store: &CanonicalTypeMapperStore,
    table: Option<SymbolTableId>,
    entries: &[(EscapedName, SemanticSymbolId)],
) -> bool {
    match table {
        None => entries.is_empty(),
        Some(table) => store.symbol_table(table).is_some_and(|table| {
            table.len() == entries.len()
                && entries
                    .iter()
                    .all(|(name, symbol)| table.get(name.as_ref()) == Some(*symbol))
        }),
    }
}

/// Rechecks the full source plan with its retained array and type-query inputs.
pub(super) fn source_class_plan_is_current(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &SourceClassPlan,
) -> Result<bool, ClassError> {
    Ok(plan_source_class_members_with_context(
        store,
        host,
        plan.symbol(),
        plan.array_targets,
        plan.type_query_context.as_ref(),
    )? == *plan)
}

fn validate_source_class_header(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    provenance: &SourceClassProvenance,
) -> Result<(), ClassError> {
    let prepared = &provenance.prepared;
    let plan = &prepared.plan;
    if !source_class_plan_is_current(store, host, plan)? {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    if source_class_base_members(store, host, plan)? != provenance.base_members {
        return Err(invariant(ClassInvariant::InvalidHeritageCache(
            plan.symbol(),
        )));
    }
    validate_source_class_stored_header(store, provenance)
}

fn validate_source_class_stored_header(
    store: &CanonicalTypeMapperStore,
    provenance: &SourceClassProvenance,
) -> Result<(), ClassError> {
    validate_source_class_stored_layout(store, provenance)?;
    let plan = &provenance.prepared.plan;
    let reject = || invariant(ClassInvariant::InvalidInstanceMembers(plan.symbol()));
    for (index, method) in plan.methods.iter().enumerate() {
        let returned = provenance.method_returns[index];
        let body_complete = plan
            .bodies
            .iter()
            .position(|body| body.declaration == method.method.declaration)
            .is_some_and(|body| provenance.completed_bodies[body]);
        if store
            .signature(provenance.prepared.methods[index].1)
            .is_none_or(|signature| signature.resolved_return_type() != returned)
            || source_class_method_return_type(store, method)?
                .is_some_and(|annotation| returned != Some(annotation))
            || method.method.return_type_node.is_none() && (returned.is_some() != body_complete)
        {
            return Err(reject());
        }
    }
    if provenance.complete
        && (!provenance.completed_bodies.iter().all(|complete| *complete)
            || provenance.method_returns.iter().any(Option::is_none)
            || provenance.property_types.iter().any(Option::is_none))
    {
        return Err(reject());
    }
    Ok(())
}

/// Authenticates synthetic this without completing the source class's bodies.
pub(super) fn source_class_this_type_owner(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
) -> Option<SemanticSymbolId> {
    let symbol = store.type_payload(type_)?.symbol()?;
    let provenance = store.source_class_provenance_for_symbol(symbol)?;
    (provenance.symbol() == symbol
        && provenance.this_type == type_
        && validate_source_class_stored_header(store, provenance).is_ok())
    .then_some(symbol)
}

fn completed_source_class_header_is_valid(
    store: &CanonicalTypeMapperStore,
    symbol: SemanticSymbolId,
    instance_type: Option<TypeId>,
) -> bool {
    let instance = instance_type.and_then(|instance| store.source_class_provenance(instance));
    let owner = store.source_class_provenance_for_symbol(symbol);
    match (instance, owner) {
        (None, None) => true,
        (Some(provenance), Some(owner)) => {
            provenance.symbol() == symbol
                && provenance.instance_type() == owner.instance_type()
                && provenance.complete
                && validate_source_class_stored_header(store, provenance).is_ok()
        }
        _ => false,
    }
}

// Adoption checks the complete legacy layout before changing its return lifecycle.
fn validate_source_class_stored_layout(
    store: &CanonicalTypeMapperStore,
    provenance: &SourceClassProvenance,
) -> Result<(), ClassError> {
    let prepared = &provenance.prepared;
    let plan = &prepared.plan;
    let members = &provenance.members;
    let reject = || invariant(ClassInvariant::InvalidInstanceMembers(plan.symbol()));
    let owner = store.symbol(plan.symbol()).ok_or_else(reject)?;
    if stored_class_owner_declaration(store, plan.symbol(), owner) != Some(plan.declaration())
        || owner.members() != plan.header.instance_members
        || owner.exports() != Some(plan.header.static_members)
        || plan
            .bindings
            .iter()
            .any(|expected| source_class_binding(store, expected.symbol).as_ref() != Ok(expected))
    {
        return Err(reject());
    }
    if prepared.instance_type != members.shells.instance_type
        || prepared.value_type != members.shells.value_type
        || prepared
            .constructor_overloads
            .first()
            .copied()
            .unwrap_or(prepared.construct_signature)
            != members.default_construct_signature
        || prepared.constructor_overloads.len()
            != plan.constructor_overloads.len() + plan.inherited_construct_count()
        || members.shells.symbol != plan.symbol()
        || members.shells.declaration != plan.declaration()
        || prepared.annotation_types.len() != plan.annotation_nodes().len()
        || prepared.methods.len() != plan.methods.len()
        || provenance.method_returns.len() != plan.methods.len()
        || provenance.property_types.len() != plan.initialized_properties.len()
        || provenance.completed_bodies.len() != plan.bodies.len()
        || store
            .declared_type_links(plan.symbol())
            .and_then(|links| links.declared_type)
            != Some(prepared.instance_type)
        || store.value_symbol_links(plan.symbol())
            != Some(&ValueSymbolLinks {
                resolved_type: Some(prepared.value_type),
                ..ValueSymbolLinks::default()
            })
    {
        return Err(reject());
    }
    for ((node, type_), expected) in prepared
        .annotation_types
        .iter()
        .zip(plan.annotation_nodes())
    {
        if node != expected
            || store.type_payload(*type_).is_none()
            || store.type_node_links(*node)
                != Some(&TypeNodeLinks {
                    resolved_type: Some(*type_),
                    ..TypeNodeLinks::default()
                })
        {
            return Err(reject());
        }
    }
    validate_source_class_member_tables(store, plan)?;
    validate_prototype(store, plan.symbol(), plan.header.static_members)?;
    let instance = exact_class_instance_identity(store, plan.symbol(), prepared.instance_type)
        .ok_or_else(reject)?;
    let base = provenance.base_members.as_ref();
    if base.map(|base| base.identities().symbol)
        != plan.header.base.as_ref().map(|base| base.symbol)
    {
        return Err(reject());
    }
    let expected_base = base.map(|base| base.identities().value_type).or_else(|| {
        store
            .intrinsic_bootstrap()
            .map(|bootstrap| bootstrap.undefined_type)
    });
    if instance.this_type != Some(provenance.this_type)
        || store
            .type_payload(prepared.instance_type)
            .is_none_or(|record| {
                record.object_flags()
                    != (ObjectFlags::CLASS | ObjectFlags::REFERENCE | ObjectFlags::MEMBERS_RESOLVED)
            })
        || !instance.declared_members_resolved
        || instance.declared_members != plan.header.instance_members
        || instance.declared_call_signatures.is_some()
        || instance.declared_construct_signatures.is_some()
        || instance.declared_index_infos.is_some()
        || !instance.base_types_resolved
        || instance.resolved_base_constructor_type != expected_base
        || instance.resolved_base_types != base.map(|base| vec![base.identities().instance_type])
    {
        return Err(reject());
    }
    let expected_heritage = base.map(|base| DirectClassHeritageProvenance {
        owner_symbol: plan.symbol(),
        owner_value_type: prepared.value_type,
        base_symbol: base.identities().symbol,
        base_instance_type: base.identities().instance_type,
        base_value_type: base.identities().value_type,
    });
    if store.direct_class_heritage_provenance(prepared.instance_type) != expected_heritage
        || members.base != base.map(SourceClassBaseMembers::identities)
    {
        return Err(reject());
    }
    if let Some(SourceClassBaseMembers::Class(base)) = base
        && (base.shells.instance_type == prepared.instance_type
            || validate_class_heritage_members(store, base.shells.instance_type) != ClassHeritageMembersValidation::Valid
            || store.value_symbol_links(base.shells.symbol).and_then(|links| links.resolved_type) != Some(base.shells.value_type)
            || store.type_payload(base.shells.value_type).is_none_or(|record| {
                !matches!(record.data(), TypeData::Object(object)
                    if object.structured.signatures.as_deref() == Some(&[base.default_construct_signature]))
            }))
    {
        return Err(reject());
    }
    if let Some(SourceClassBaseMembers::Constructor(base)) = base
        && (base.identities.instance_type == prepared.instance_type
            || !declared_class_base_is_current(store, base))
    {
        return Err(reject());
    }
    let (instance_entries, instance_count) =
        source_class_entries(store, plan, ClassPropertySide::Instance, base)?;
    let (mut static_entries, static_count) =
        source_class_entries(store, plan, ClassPropertySide::Static, base)?;
    if members.declared_instance_property_count != instance_count
        || members.declared_static_property_count != static_count
        || members.instance_properties
            != instance_entries
                .iter()
                .map(|(_, symbol)| *symbol)
                .collect::<Vec<_>>()
        || members.static_properties
            != static_entries
                .iter()
                .map(|(_, symbol)| *symbol)
                .collect::<Vec<_>>()
        || !source_table_matches(store, members.instance_members, &instance_entries)
        || instance.reference.object.structured
            != (StructuredTypeData {
                members: members.instance_members,
                properties: (!members.instance_properties.is_empty())
                    .then(|| members.instance_properties.clone()),
                index_infos: source_class_inherited_indexes(store, base)?,
                ..StructuredTypeData::default()
            })
    {
        return Err(reject());
    }
    static_entries.push((
        store
            .symbol(members.prototype)
            .ok_or_else(reject)?
            .name()
            .to_owned(),
        members.prototype,
    ));
    let mut static_properties = members.static_properties.clone();
    static_properties.push(members.prototype);
    if !source_table_matches(store, Some(members.static_members), &static_entries)
        || !source_class_object_valid(
            store,
            prepared.value_type,
            plan.symbol(),
            &StructuredTypeData {
                members: Some(members.static_members),
                properties: Some(static_properties),
                signatures: Some(if prepared.constructor_overloads.is_empty() {
                    vec![prepared.construct_signature]
                } else {
                    prepared.constructor_overloads.clone()
                }),
                call_signature_count: 0,
                ..StructuredTypeData::default()
            },
        )
        || !source_class_signature_valid(
            store,
            prepared.construct_signature,
            provenance.constructor_declaration,
            source_constructor_flags(store, plan, base)?,
            &provenance.constructor_parameters,
            Some(prepared.instance_type),
            provenance.constructor_minimum,
        )
        || source_inherited_values(store, base)? != provenance.inherited_values
    {
        return Err(reject());
    }
    if plan.inherited_construct_count() != 0 {
        let Some(SourceClassBaseMembers::Constructor(base)) = base else {
            return Err(reject());
        };
        for (source, &signature) in base.signatures.iter().zip(&prepared.constructor_overloads) {
            let original = store.signature(source.signature).ok_or_else(reject)?;
            let flags = (original.flags() & !SignatureFlags::ABSTRACT)
                | if plan.header.abstract_class {
                    SignatureFlags::ABSTRACT
                } else {
                    SignatureFlags::NONE
                };
            if signature == source.signature
                || !source_class_signature_valid(
                    store,
                    signature,
                    original.declaration(),
                    flags,
                    original.parameters(),
                    Some(prepared.instance_type),
                    original.min_argument_count(),
                )
            {
                return Err(reject());
            }
        }
    }
    for (constructor, signature) in plan
        .constructor
        .iter()
        .map(|constructor| (constructor, prepared.construct_signature))
        .chain(
            plan.constructor_overloads
                .iter()
                .zip(prepared.constructor_overloads.iter().copied()),
        )
    {
        if !source_class_signature_valid(
            store,
            signature,
            Some(constructor.declaration),
            SignatureFlags::CONSTRUCT
                | if plan.header.abstract_class {
                    SignatureFlags::ABSTRACT
                } else {
                    SignatureFlags::NONE
                },
            &constructor
                .parameters
                .iter()
                .map(|parameter| parameter.symbol)
                .collect::<Vec<_>>(),
            Some(prepared.instance_type),
            source_class_minimum(&constructor.parameters)?,
        ) {
            return Err(reject());
        }
        if store.signature_links(constructor.declaration)
            != Some(&SignatureLinks {
                resolved_signature: ResolvedSignatureState::Resolved(signature),
                ..SignatureLinks::default()
            })
        {
            return Err(reject());
        }
        for parameter in &constructor.parameters {
            let annotation_type = parameter.type_.resolved(store)?;
            let type_ = optional_constructor_parameter_type(
                store,
                annotation_type,
                parameter.optional,
                parameter.declaration,
            )?
            .ok_or_else(reject)?;
            if store.value_symbol_links(parameter.symbol)
                != Some(&ValueSymbolLinks {
                    resolved_type: Some(type_),
                    ..ValueSymbolLinks::default()
                })
                || store.type_node_links(parameter.type_node)
                    != Some(&TypeNodeLinks {
                        resolved_type: Some(annotation_type),
                        ..TypeNodeLinks::default()
                    })
            {
                return Err(reject());
            }
        }
        let defaults_complete = plan
            .bodies
            .iter()
            .position(|body| body.declaration == constructor.declaration)
            .is_some_and(|index| provenance.completed_bodies[index]);
        for initializer in &constructor.literal_defaults {
            validate_source_constructor_literal_default_cache(
                store,
                initializer,
                defaults_complete,
            )?;
        }
    }
    for (property, type_) in &plan.properties {
        if !exact_property_type_links(store, property, *type_)
            || store.symbol(property.symbol).is_none_or(|symbol| {
                symbol.check_flags()
                    != if property.readonly {
                        CheckFlags::READONLY
                    } else {
                        CheckFlags::NONE
                    }
            })
            || resolved_property_value_type(store, property, *type_)?.is_none_or(|expected| {
                store.value_symbol_links(property.symbol)
                    != Some(&ValueSymbolLinks {
                        resolved_type: Some(expected),
                        ..ValueSymbolLinks::default()
                    })
            })
        {
            return Err(reject());
        }
    }
    for property in &plan.annotated_properties {
        let type_ = prepared
            .annotation_types
            .iter()
            .find_map(|(node, type_)| (*node == property.type_node).then_some(*type_))
            .ok_or_else(reject)?;
        if store.type_node_links(property.type_node)
            != Some(&TypeNodeLinks {
                resolved_type: Some(type_),
                ..TypeNodeLinks::default()
            })
            || !exact_property_value_links(store, property, type_)
            || store.symbol(property.symbol).is_none_or(|symbol| {
                symbol.check_flags()
                    != if property.readonly {
                        CheckFlags::READONLY
                    } else {
                        CheckFlags::NONE
                    }
            })
        {
            return Err(reject());
        }
    }
    for (property, function) in &plan.function_properties {
        let type_ = store
            .type_node_links(function.node)
            .and_then(|links| links.resolved_type)
            .ok_or_else(reject)?;
        if !matches!(
            validate_stored_callable_set(store, type_),
            StoredCallableSetValidation::Valid { .. }
        ) || store.type_payload(type_).and_then(TypeRecord::symbol) != Some(function.symbol)
            || store.value_symbol_links(property.symbol)
                != Some(&ValueSymbolLinks {
                    resolved_type: Some(type_),
                    ..ValueSymbolLinks::default()
                })
        {
            return Err(reject());
        }
    }
    for (index, property) in plan.initialized_properties.iter().enumerate() {
        let type_ = provenance.property_types[index];
        let completed = plan
            .bodies
            .iter()
            .position(|body| body.declaration == property.declaration)
            .is_some_and(|body| provenance.completed_bodies[body]);
        let links = store
            .value_symbol_links(property.symbol)
            .cloned()
            .unwrap_or_default();
        if type_.is_some() != completed
            || links
                != (ValueSymbolLinks {
                    resolved_type: type_,
                    ..ValueSymbolLinks::default()
                })
            || store.symbol(property.symbol).is_none_or(|symbol| {
                symbol.check_flags()
                    != if property.readonly {
                        CheckFlags::READONLY
                    } else {
                        CheckFlags::NONE
                    }
            })
        {
            return Err(reject());
        }
        if let Some(type_) = type_
            && (store.type_payload(type_).is_none()
                || property
                    .initializer_node
                    .and_then(|node| store.type_node_links(node))
                    .and_then(|links| links.resolved_type)
                    .is_none()
                || property.initializer_node != Some(property.type_node)
                    && store
                        .type_node_links(property.type_node)
                        .and_then(|links| links.resolved_type)
                        != Some(type_))
        {
            return Err(reject());
        }
        if let Some(type_) = type_
            && store.source_node_kind(property.type_node)
                == Some(SyntaxKind::ObjectLiteralExpression)
        {
            let initializer = validate_private_object_property_type(
                store,
                property,
                type_,
                plan.type_query_context
                    .as_ref()
                    .map(|context| &context.global_types),
            )?;
            validate_property_cache_state_with_types(
                store,
                property,
                type_,
                Some(initializer),
                Ok(Some(type_)),
            )?;
        }
    }
    for (index, method) in plan.methods.iter().enumerate() {
        let (type_, signature) = prepared.methods[index];
        let signatures = source_class_method_signatures(prepared, method.method.symbol);
        let signature_count = signatures.len();
        let parameters = method
            .method
            .parameters
            .iter()
            .map(|parameter| parameter.symbol)
            .collect::<Vec<_>>();
        let returned = store
            .signature(signature)
            .and_then(super::signatures::Signature::resolved_return_type);
        if store.value_symbol_links(method.method.symbol)
            != Some(&ValueSymbolLinks {
                resolved_type: Some(type_),
                ..ValueSymbolLinks::default()
            })
            || store.signature_links(method.method.declaration)
                != Some(&SignatureLinks {
                    resolved_signature: ResolvedSignatureState::Resolved(signature),
                    ..SignatureLinks::default()
                })
            || !source_class_signature_valid(
                store,
                signature,
                Some(method.method.declaration),
                SignatureFlags::NONE,
                &parameters,
                returned,
                class_method_minimum(&method.method)?,
            )
            || !source_class_object_valid(
                store,
                type_,
                method.method.symbol,
                &StructuredTypeData {
                    signatures: Some(signatures),
                    call_signature_count: signature_count,
                    ..StructuredTypeData::default()
                },
            )
        {
            return Err(reject());
        }
        for parameter in &method.method.parameters {
            let annotation_type = parameter.type_.resolved(store)?;
            let parameter_type = class_method_parameter_type(store, *parameter)?;
            if store.value_symbol_links(parameter.symbol)
                != Some(&ValueSymbolLinks {
                    resolved_type: Some(parameter_type),
                    ..ValueSymbolLinks::default()
                })
                || parameter.type_node.is_some_and(|node| {
                    store.type_node_links(node)
                        != Some(&TypeNodeLinks {
                            resolved_type: Some(annotation_type),
                            ..TypeNodeLinks::default()
                        })
                })
            {
                return Err(reject());
            }
            if parameter
                .type_node
                .is_some_and(|node| store.source_node_kind(node) == Some(SyntaxKind::ArrayType))
                && plan.array_targets.is_none_or(|targets| {
                    store
                        .canonical_array_reference_with_targets(targets, annotation_type)
                        .ok()
                        .flatten()
                        .is_none_or(|reference| {
                            reference.readonly
                                || reference.array_literal
                                || reference.base_type != annotation_type
                        })
                })
            {
                return Err(reject());
            }
        }
        if let Some(annotation) = method.method.return_type_node
            && store
                .type_node_links(annotation)
                .and_then(|links| links.resolved_type)
                != source_class_method_return_type(store, method)?
        {
            return Err(reject());
        }
    }
    if plan.bodies.iter().any(|body| {
        body.kind == ClassBodyKind::StaticBlock
            && store
                .signature_links(body.declaration)
                .is_some_and(|links| links != &SignatureLinks::default())
    }) {
        return Err(reject());
    }
    Ok(())
}

/// Resolves retained tuple and union parameters in the caller's query session before publication.
pub(super) fn prepare_source_class_members_with_type_queries(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
    plan: &SourceClassPlan,
) -> Result<PreparedSourceClass, ClassError> {
    if !source_class_plan_is_current(store, host, plan)? {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    if let Some(base) = &plan.header.base
        && let Some(value) = &base.constructor_value
    {
        prepare_declared_constructor_value(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
            value,
        )
        .map_err(|error| constructor_heritage_error(base.expression, base.symbol, error))?;
        let constructor = CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_declared_interface_for_source_check(value.owner_symbol())?;
        if store
            .value_symbol_links(base.symbol)
            .and_then(|links| links.resolved_type)
            != Some(constructor)
        {
            return Err(invariant(ClassInvariant::InvalidHeritageCache(base.symbol)));
        }
        // A constructor's result, not its variable symbol, owns inherited instance members.
        let instance = value
            .construct_declarations()
            .next()
            .and_then(|node| store.signature_links(node))
            .and_then(|links| links.resolved_signature.signature())
            .and_then(|signature| store.signature(signature))
            .and_then(super::signatures::Signature::resolved_return_type)
            .ok_or_else(|| invariant(ClassInvariant::InvalidHeritageCache(base.symbol)))?;
        let instance_symbol = store
            .type_payload(instance)
            .and_then(TypeRecord::symbol)
            .ok_or_else(|| unsupported(ClassUnsupported::Heritage(base.expression)))?;
        if instance_symbol == plan.symbol() {
            return Err(unsupported(ClassUnsupported::Heritage(base.expression)));
        }
        let resolved = CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_declared_interface_for_source_check(instance_symbol)?;
        if resolved != instance {
            return Err(invariant(ClassInvariant::InvalidHeritageCache(base.symbol)));
        }
        declared_class_base_members(store, host, base)?;
    }
    for annotation in plan.queried_parameter_annotations() {
        CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_type_from_type_node(annotation)?;
    }
    prepare_source_class_members(store, host, plan)
}

/// Publishes a header with real signatures. Inferred method returns stay absent.
#[allow(clippy::too_many_arguments)]
pub(super) fn prepare_source_class_constructor_header(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    globals: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    session: &mut super::instantiate::InstantiationSession,
    diagnostics: &mut super::CanonicalCheckerDiagnostics,
    plan: &SourceClassPlan,
) -> Result<ClassMembers, ClassError> {
    let scope = begin_source_class_annotations(store, host, globals, plan)?;
    let result = (|| {
        for &annotation in plan.annotation_nodes() {
            CanonicalTypeQuery::new_with_global_types_and_session(
                store,
                host,
                globals,
                options,
                session,
                diagnostics,
            )?
            .get_type_from_source_class_annotation(annotation, plan.symbol())?;
        }
        prepare_source_class_members_with_type_queries(
            store,
            host,
            globals,
            options,
            session,
            diagnostics,
            plan,
        )?;
        // Constructor projection also replays the source annotations. Keep it
        // inside the owner scope while initialized fields are still pending.
        if plan.has_constructor_overloads() {
            source_class_constructor_overloads(store, host, plan.symbol())?
                .map(|constructors| constructors.members)
        } else {
            source_class_single_constructor(store, host, plan.symbol())?
                .map(|constructor| constructor.members)
        }
        .ok_or_else(|| invariant(ClassInvariant::InvalidConstructSignature(plan.symbol())))
    })();
    if let Some(instance) = scope
        && !store.end_source_class_annotation_scope(instance)
    {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    result
}

/// Publishes a header with real signatures. Inferred method returns stay absent.
pub(super) fn prepare_source_class_members(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &SourceClassPlan,
) -> Result<PreparedSourceClass, ClassError> {
    if !source_class_plan_is_current(store, host, plan)? {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    for method in &plan.methods {
        for parameter in &method.method.parameters {
            class_method_parameter_type(store, *parameter)?;
        }
    }
    let instance = store
        .declared_type_links(plan.symbol())
        .and_then(|links| links.declared_type);
    if let Some(provenance) = store.source_class_provenance_for_symbol(plan.symbol()) {
        validate_source_class_header(store, host, provenance)?;
        return Ok(provenance.prepared.clone());
    }
    let annotation_types = plan
        .annotation_nodes()
        .iter()
        .map(|&node| {
            let type_ = store
                .type_node_links(node)
                .and_then(|links| links.resolved_type)
                .filter(|type_| store.type_payload(*type_).is_some())
                .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyTypeCache(node)))?;
            Ok((node, type_))
        })
        .collect::<Result<Vec<_>, ClassError>>()?;
    let base = source_class_base_members(store, host, plan)?;
    let base_constructor = base
        .as_ref()
        .map(|base| base.identities().value_type)
        .or_else(|| {
            store
                .intrinsic_bootstrap()
                .map(|bootstrap| bootstrap.undefined_type)
        })
        .ok_or_else(|| invariant(ClassInvariant::BootstrapUnavailable(plan.declaration())))?;
    let inherited_values = source_inherited_values(store, base.as_ref())?;
    let inherited_indexes = source_class_inherited_indexes(store, base.as_ref())?;
    let old_value = resolved_class_value_type(store, plan.symbol());
    if old_value.is_some_and(|value| has_static_member_publication(store, value)) {
        // Reuse legacy identities, but require source-body receipts for this path.
        let legacy = plan_nongeneric_class_member_query(store, host, plan.symbol())?;
        preflight_nongeneric_class_member_query(store, host, &legacy)?;
        let members = execute_nongeneric_class_member_query(store, host, &legacy)?;
        let mut methods = Vec::new();
        let mut returns = Vec::new();
        for method in &plan.methods {
            let type_ = store
                .value_symbol_links(method.method.symbol)
                .and_then(|links| links.resolved_type)
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidPropertyValueCache(
                        method.method.symbol,
                    ))
                })?;
            let signature = store
                .signature_links(method.method.declaration)
                .and_then(|links| links.resolved_signature.signature())
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidPropertyValueCache(
                        method.method.symbol,
                    ))
                })?;
            methods.push((type_, signature));
            returns.push(source_class_method_return_type(store, method)?);
        }
        let prepared = PreparedSourceClass {
            plan: plan.clone(),
            instance_type: members.shells.instance_type,
            value_type: members.shells.value_type,
            construct_signature: members.default_construct_signature,
            constructor_overloads: Vec::new(),
            annotation_types,
            methods,
        };
        let constructor = store
            .signature(prepared.construct_signature)
            .ok_or_else(|| invariant(ClassInvariant::InvalidConstructSignature(plan.symbol())))?;
        let provenance = SourceClassProvenance {
            prepared: prepared.clone(),
            this_type: exact_class_instance_identity(store, plan.symbol(), prepared.instance_type)
                .and_then(|instance| instance.this_type)
                .ok_or_else(|| invariant(ClassInvariant::InvalidInstanceCache(plan.symbol())))?,
            constructor_parameters: constructor.parameters().to_vec(),
            constructor_declaration: constructor.declaration(),
            constructor_minimum: constructor.min_argument_count(),
            members,
            base_members: base,
            inherited_values,
            method_returns: returns,
            property_types: vec![None; plan.initialized_properties.len()],
            completed_bodies: vec![false; plan.bodies.len()],
            complete: false,
        };
        validate_source_class_stored_layout(store, &provenance)?;
        prepare_source_constructor_call_types(store, host, plan, provenance.base_members.as_ref())?;
        if !store.try_reserve_source_class_provenance(1)
            || !store.publish_source_class_provenance(prepared.instance_type, provenance)
        {
            return Err(invariant(ClassInvariant::Publication(plan.declaration())));
        }
        for (index, method) in plan.methods.iter().enumerate() {
            if method.method.return_type_node.is_none() {
                assert!(store.set_signature_resolved_return_type(prepared.methods[index].1, None));
            }
        }
        validate_source_class_stored_header(
            store,
            store
                .source_class_provenance(prepared.instance_type)
                .expect("source class provenance was registered"),
        )?;
        return Ok(prepared);
    }
    if store
        .value_symbol_links(plan.symbol())
        .is_some_and(|links| {
            links != &ValueSymbolLinks::default()
                && old_value.is_none_or(|type_| !exact_static_shell(store, plan.symbol(), type_))
        })
    {
        return Err(invariant(ClassInvariant::InvalidValueCache(plan.symbol())));
    }
    if let Some(instance) = instance {
        let data = exact_class_instance_identity(store, plan.symbol(), instance)
            .ok_or_else(|| invariant(ClassInvariant::InvalidInstanceCache(plan.symbol())))?;
        if store.type_payload(instance).is_none_or(|record| {
            record.object_flags() != (ObjectFlags::CLASS | ObjectFlags::REFERENCE)
        }) || data
            .resolved_base_constructor_type
            .is_some_and(|cached| cached != base_constructor)
            || data.declared_members_resolved
            || data.base_types_resolved
            || data.reference.object.structured != StructuredTypeData::default()
            || data.declared_members.is_some()
            || data.declared_call_signatures.is_some()
            || data.declared_construct_signatures.is_some()
            || data.declared_index_infos.is_some()
            || data.resolved_base_types.is_some()
            || store.direct_class_heritage_provenance(instance).is_some()
        {
            return Err(invariant(ClassInvariant::InvalidInstanceCache(
                plan.symbol(),
            )));
        }
    }
    for method in &plan.methods {
        if store
            .value_symbol_links(method.method.symbol)
            .is_some_and(|links| links != &ValueSymbolLinks::default())
            || store
                .signature_links(method.method.declaration)
                .is_some_and(|links| links != &SignatureLinks::default())
        {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(
                method.method.symbol,
            )));
        }
    }
    if plan
        .constructor
        .iter()
        .chain(&plan.constructor_overloads)
        .any(|constructor| {
            store
                .signature_links(constructor.declaration)
                .is_some_and(|links| links != &SignatureLinks::default())
        })
    {
        return Err(invariant(ClassInvariant::InvalidConstructSignature(
            plan.symbol(),
        )));
    }
    if plan.bodies.iter().any(|body| {
        body.kind == ClassBodyKind::StaticBlock
            && store
                .signature_links(body.declaration)
                .is_some_and(|links| links != &SignatureLinks::default())
    }) {
        return Err(invariant(ClassInvariant::InvalidConstructSignature(
            plan.symbol(),
        )));
    }
    let (instance_entries, instance_count) =
        source_class_entries(store, plan, ClassPropertySide::Instance, base.as_ref())?;
    let (mut static_entries, static_count) =
        source_class_entries(store, plan, ClassPropertySide::Static, base.as_ref())?;
    let prototype = store
        .symbol_table(plan.header.static_members)
        .and_then(|table| table.get_source(PROTOTYPE_NAME))
        .ok_or_else(|| invariant(ClassInvariant::InvalidPrototype(plan.symbol())))?;
    let instance_properties = instance_entries
        .iter()
        .map(|(_, symbol)| *symbol)
        .collect::<Vec<_>>();
    let static_properties = static_entries
        .iter()
        .map(|(_, symbol)| *symbol)
        .collect::<Vec<_>>();
    static_entries.push((
        store
            .symbol(prototype)
            .expect("the prototype was authenticated")
            .name()
            .to_owned(),
        prototype,
    ));
    let prepared_instance = if instance_entries.is_empty() {
        None
    } else {
        Some(
            PreparedSymbolTable::new(instance_entries.len())
                .ok_or_else(|| invariant(ClassInvariant::Capacity(plan.declaration())))?,
        )
    };
    let prepared_static = if base.is_some() {
        Some(
            PreparedSymbolTable::new(static_entries.len())
                .ok_or_else(|| invariant(ClassInvariant::Capacity(plan.declaration())))?,
        )
    } else {
        None
    };
    let (constructor_parameters, constructor_declaration, constructor_minimum) =
        if let Some(constructor) = &plan.constructor {
            (
                constructor
                    .parameters
                    .iter()
                    .map(|parameter| parameter.symbol)
                    .collect::<Vec<_>>(),
                Some(constructor.declaration),
                source_class_minimum(&constructor.parameters)?,
            )
        } else if let Some(base) = &base {
            let signature = store
                .signature(base.default_construct_signature())
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidConstructSignature(
                        base.identities().symbol,
                    ))
                })?;
            (
                signature.parameters().to_vec(),
                signature.declaration(),
                signature.min_argument_count(),
            )
        } else {
            (Vec::new(), None, 0)
        };
    let mut methods = Vec::new();
    methods
        .try_reserve_exact(plan.methods.len())
        .map_err(|_| invariant(ClassInvariant::Capacity(plan.declaration())))?;
    let method_returns = plan
        .methods
        .iter()
        .map(|method| source_class_method_return_type(store, method))
        .collect::<Result<Vec<_>, ClassError>>()?;
    let completed_bodies = vec![false; plan.bodies.len()];
    let retained_plan = plan.clone();
    let mut numbers = Vec::new();
    let mut strings = Vec::new();
    for (property, type_) in &plan.properties {
        validate_property_cache_state(store, property, *type_)?;
        numbers.extend(property_initializer_number(property));
        strings.extend(property.initializer_string.clone());
    }
    let count = plan.properties.len()
        + plan.annotated_properties.len()
        + plan.function_properties.len()
        + plan.initialized_properties.len()
        + plan.methods.len()
        + constructor_parameters.len()
        + plan
            .constructor_overloads
            .iter()
            .map(|constructor| constructor.parameters.len())
            .sum::<usize>()
        + 4;
    if !store.try_reserve_types(count * 3)
        || !store.try_reserve_signatures(
            plan.methods.len()
                + plan.constructor_overloads.len()
                + plan.inherited_construct_count()
                + 1,
        )
        || !store.try_reserve_checker_symbol_allocations(0, 2)
        || !store.try_reserve_type_node_links(count * 4)
        || !store.try_reserve_value_symbol_links(count * 2)
        || !store.try_reserve_symbol_node_links(4)
        || !store
            .try_reserve_signature_links(plan.methods.len() + plan.constructor_overloads.len() + 1)
        || !store.try_reserve_source_class_provenance(1)
        || !store.try_reserve_direct_class_heritage_provenance(usize::from(base.is_some()))
    {
        return Err(invariant(ClassInvariant::Capacity(plan.declaration())));
    }
    store
        .prepare_regular_literal_types(&strings, &numbers, &[])
        .map_err(|_| invariant(ClassInvariant::InvalidPropertyTypeCache(plan.declaration())))?;
    prepare_source_constructor_call_types(store, host, plan, base.as_ref())?;
    let base_constructor = base
        .as_ref()
        .map(|base| base.identities().value_type)
        .or_else(|| {
            store
                .intrinsic_bootstrap()
                .map(|bootstrap| bootstrap.undefined_type)
        })
        .ok_or_else(|| invariant(ClassInvariant::BootstrapUnavailable(plan.declaration())))?;
    let instance_type = store.get_declared_type_of_symbol(host, plan.symbol())?;
    let this_type = exact_class_instance_identity(store, plan.symbol(), instance_type)
        .and_then(|instance| instance.this_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidInstanceCache(plan.symbol())))?;
    let value_type = old_value.unwrap_or_else(|| {
        store
            .alloc_plain_object_type(ObjectFlags::ANONYMOUS, Some(plan.symbol()))
            .expect("source class value capacity was reserved")
    });
    for (property, _) in &plan.function_properties {
        let options = CanonicalTypeQueryOptions {
            strict_builtin_iterator_return: store
                .claimed_strict_builtin_iterator_return()
                .unwrap_or_default(),
            strict_function_types: store.claimed_strict_function_types(),
            no_implicit_any: true,
        };
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let type_ = CanonicalTypeQuery::new(store, host, options, &mut diagnostics)?
            .get_type_from_type_node(property.type_node)?;
        if !diagnostics.is_empty() {
            return Err(unsupported(ClassUnsupported::PropertyType {
                node: property.type_node,
                kind: SyntaxKind::FunctionType,
            }));
        }
        publish_class_property(store, property, type_);
    }
    let instance_members = prepared_instance.map(|prepared| {
        let table = store.alloc_prepared_symbol_table(prepared);
        for (name, symbol) in instance_entries {
            assert_eq!(store.insert_symbol(table, name, symbol), Some(None));
        }
        table
    });
    let static_members = prepared_static.map_or(plan.header.static_members, |prepared| {
        let table = store.alloc_prepared_symbol_table(prepared);
        for (name, symbol) in static_entries {
            assert_eq!(store.insert_symbol(table, name, symbol), Some(None));
        }
        table
    });
    let construct_signature = store
        .alloc_signature(
            source_constructor_flags(store, plan, base.as_ref())?,
            constructor_declaration,
            Vec::new(),
            None,
            constructor_parameters.clone(),
            Some(instance_type),
            None,
            constructor_minimum,
        )
        .expect("source constructor signature capacity was reserved");
    let mut constructor_overloads = Vec::with_capacity(plan.constructor_overloads.len());
    for constructor in &plan.constructor_overloads {
        let signature = store
            .alloc_signature(
                SignatureFlags::CONSTRUCT
                    | if plan.header.abstract_class {
                        SignatureFlags::ABSTRACT
                    } else {
                        SignatureFlags::NONE
                    },
                Some(constructor.declaration),
                Vec::new(),
                None,
                constructor
                    .parameters
                    .iter()
                    .map(|parameter| parameter.symbol)
                    .collect(),
                Some(instance_type),
                None,
                source_class_minimum(&constructor.parameters)?,
            )
            .expect("constructor overload signature capacity was reserved");
        constructor_overloads.push(signature);
    }
    if plan.inherited_construct_count() != 0 {
        let Some(SourceClassBaseMembers::Constructor(base)) = &base else {
            return Err(invariant(ClassInvariant::InvalidHeritageCache(
                plan.symbol(),
            )));
        };
        constructor_overloads.push(construct_signature);
        for callable in base.signatures.iter().skip(1) {
            let original = store.signature(callable.signature).ok_or_else(|| {
                invariant(ClassInvariant::InvalidConstructSignature(plan.symbol()))
            })?;
            let flags = (original.flags() & !SignatureFlags::ABSTRACT)
                | if plan.header.abstract_class {
                    SignatureFlags::ABSTRACT
                } else {
                    SignatureFlags::NONE
                };
            let declaration = original.declaration();
            let parameters = original.parameters().to_vec();
            let minimum = original.min_argument_count();
            let signature = store
                .alloc_signature(
                    flags,
                    declaration,
                    Vec::new(),
                    None,
                    parameters,
                    Some(instance_type),
                    None,
                    minimum,
                )
                .expect("inherited constructor signature capacity was reserved");
            constructor_overloads.push(signature);
        }
    }
    for (constructor, signature) in plan
        .constructor
        .iter()
        .map(|constructor| (constructor, construct_signature))
        .chain(
            plan.constructor_overloads
                .iter()
                .zip(constructor_overloads.iter().copied()),
        )
    {
        assert!(store.set_signature_links(
            constructor.declaration,
            SignatureLinks {
                resolved_signature: ResolvedSignatureState::Resolved(signature),
                ..SignatureLinks::default()
            }
        ));
        for &parameter in &constructor.parameters {
            let annotation_type = parameter.type_.materialize(store, host)?;
            let type_ =
                prepare_constructor_parameter_type(store, parameter.with_type(annotation_type))?;
            assert!(store.set_type_node_links(
                parameter.type_node,
                TypeNodeLinks {
                    resolved_type: Some(annotation_type),
                    ..TypeNodeLinks::default()
                }
            ));
            assert!(store.set_value_symbol_links(
                parameter.symbol,
                ValueSymbolLinks {
                    resolved_type: Some(type_),
                    ..ValueSymbolLinks::default()
                }
            ));
        }
    }
    for (property, type_) in &plan.properties {
        if plan.sources.iter().any(|source| {
            source.symbol == property.symbol
                && source.origin
                    == (ClassMemberOrigin::JavaScriptAssignment {
                        assignment: property.declaration,
                    })
        }) {
            publish_source_assignment_property(store, property, *type_);
        } else {
            publish_class_property(store, property, *type_);
        }
    }
    for property in &plan.annotated_properties {
        let type_ = store
            .type_node_links(property.type_node)
            .and_then(|links| links.resolved_type)
            .ok_or_else(|| {
                invariant(ClassInvariant::InvalidPropertyTypeCache(property.type_node))
            })?;
        if store
            .value_symbol_links(property.symbol)
            .is_some_and(|links| {
                links != &ValueSymbolLinks::default()
                    && links
                        != &ValueSymbolLinks {
                            resolved_type: Some(type_),
                            ..ValueSymbolLinks::default()
                        }
            })
        {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(
                property.symbol,
            )));
        }
        assert!(store.set_source_property_readonly(property.symbol, property.readonly));
        assert!(store.set_value_symbol_links(
            property.symbol,
            ValueSymbolLinks {
                resolved_type: Some(type_),
                ..ValueSymbolLinks::default()
            }
        ));
    }
    for property in &plan.initialized_properties {
        if store
            .value_symbol_links(property.symbol)
            .is_some_and(|links| links != &ValueSymbolLinks::default())
        {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(
                property.symbol,
            )));
        }
        assert!(store.set_source_property_readonly(property.symbol, property.readonly));
    }
    let mut method_types = HashMap::new();
    for method in &plan.methods {
        let type_ = *method_types.entry(method.method.symbol).or_insert_with(|| {
            store
                .alloc_plain_object_type(ObjectFlags::ANONYMOUS, Some(method.method.symbol))
                .expect("source method value capacity was reserved")
        });
        let parameters = method
            .method
            .parameters
            .iter()
            .map(|parameter| parameter.symbol)
            .collect::<Vec<_>>();
        let signature = store
            .alloc_signature(
                SignatureFlags::NONE,
                Some(method.method.declaration),
                Vec::new(),
                None,
                parameters,
                source_class_method_return_type(store, method)?,
                None,
                class_method_minimum(&method.method).expect("method arity was bounded"),
            )
            .expect("source method signature capacity was reserved");
        for parameter in &method.method.parameters {
            let annotation_type = parameter.type_.resolved(store)?;
            let parameter_type = class_method_parameter_type(store, *parameter)?;
            if let Some(type_node) = parameter.type_node {
                assert!(store.set_type_node_links(
                    type_node,
                    TypeNodeLinks {
                        resolved_type: Some(annotation_type),
                        ..TypeNodeLinks::default()
                    }
                ));
            }
            assert!(store.set_value_symbol_links(
                parameter.symbol,
                ValueSymbolLinks {
                    resolved_type: Some(parameter_type),
                    ..ValueSymbolLinks::default()
                }
            ));
        }
        if let (Some(annotation), Some(type_)) = (
            method.method.return_type_node,
            source_class_method_return_type(store, method)?,
        ) {
            assert!(store.set_type_node_links(
                annotation,
                TypeNodeLinks {
                    resolved_type: Some(type_),
                    ..TypeNodeLinks::default()
                }
            ));
        }
        assert!(store.set_signature_links(
            method.method.declaration,
            SignatureLinks {
                resolved_signature: ResolvedSignatureState::Resolved(signature),
                ..SignatureLinks::default()
            }
        ));
        assert!(store.set_value_symbol_links(
            method.method.symbol,
            ValueSymbolLinks {
                resolved_type: Some(type_),
                ..ValueSymbolLinks::default()
            }
        ));
        methods.push((type_, signature));
    }
    for (symbol, type_) in method_types {
        let signatures = plan
            .methods
            .iter()
            .zip(&methods)
            .filter(|(method, _)| {
                method.method.symbol == symbol
                    && (!method.method.overload || method.method.body.is_none())
            })
            .map(|(_, (_, signature))| *signature)
            .collect::<Vec<_>>();
        assert!(store.set_structured_type_members(type_, None, None, Some(signatures), None, None));
    }
    let members = ClassMembers {
        shells: ClassShells {
            declaration: plan.declaration(),
            symbol: plan.symbol(),
            instance_type,
            value_type,
        },
        base: base.as_ref().map(SourceClassBaseMembers::identities),
        instance_members,
        static_members,
        instance_properties: instance_properties.clone(),
        declared_instance_property_count: instance_count,
        static_properties: static_properties.clone(),
        declared_static_property_count: static_count,
        prototype,
        default_construct_signature: constructor_overloads
            .first()
            .copied()
            .unwrap_or(construct_signature),
    };
    let prepared = PreparedSourceClass {
        plan: retained_plan,
        instance_type,
        value_type,
        construct_signature,
        constructor_overloads: constructor_overloads.clone(),
        annotation_types,
        methods,
    };
    let provenance = SourceClassProvenance {
        prepared: prepared.clone(),
        members,
        this_type,
        constructor_parameters,
        constructor_declaration,
        constructor_minimum,
        base_members: base.clone(),
        inherited_values,
        method_returns,
        property_types: vec![None; plan.initialized_properties.len()],
        completed_bodies,
        complete: false,
    };
    assert!(store.publish_source_class_provenance(instance_type, provenance));
    assert!(store.set_value_symbol_links(
        plan.symbol(),
        ValueSymbolLinks {
            resolved_type: Some(value_type),
            ..ValueSymbolLinks::default()
        }
    ));
    assert!(store.set_interface_declared_members(
        instance_type,
        true,
        plan.header.instance_members,
        None,
        None,
        None
    ));
    assert!(
        store.set_interface_base_resolution(
            instance_type,
            true,
            Some(base_constructor),
            base.as_ref()
                .map(|base| vec![base.identities().instance_type])
        )
    );
    assert!(store.set_structured_type_members(
        instance_type,
        instance_members,
        (!instance_properties.is_empty()).then(|| instance_properties.clone()),
        None,
        None,
        inherited_indexes
    ));
    let mut all_static_properties = static_properties.clone();
    all_static_properties.push(prototype);
    assert!(store.set_structured_type_members(
        value_type,
        Some(static_members),
        Some(all_static_properties),
        None,
        Some(if constructor_overloads.is_empty() {
            vec![construct_signature]
        } else {
            constructor_overloads
        }),
        None
    ));
    if let (Some(base), Some(edge)) = (&base, &plan.header.base) {
        assert!(store.publish_direct_class_heritage_provenance(
            instance_type,
            DirectClassHeritageProvenance {
                owner_symbol: plan.symbol(),
                owner_value_type: value_type,
                base_symbol: base.identities().symbol,
                base_instance_type: base.identities().instance_type,
                base_value_type: base.identities().value_type,
            }
        ));
        assert!(store.set_symbol_node_links(
            edge.expression,
            SymbolNodeLinks {
                resolved_symbol: Some(base.identities().symbol)
            }
        ));
        assert!(store.set_type_node_links(
            edge.expression,
            TypeNodeLinks {
                resolved_type: Some(base.identities().value_type),
                ..TypeNodeLinks::default()
            }
        ));
        assert!(store.set_type_node_links(
            edge.node,
            TypeNodeLinks {
                resolved_type: Some(base.identities().instance_type),
                ..TypeNodeLinks::default()
            }
        ));
    }
    validate_source_class_stored_header(
        store,
        store
            .source_class_provenance(instance_type)
            .expect("source class provenance was registered"),
    )?;
    Ok(prepared)
}

fn source_class_body_token(
    prepared: &PreparedSourceClass,
    body: &ClassBodyPlan,
) -> Result<ClassBodyAccessToken, ClassError> {
    if !prepared.plan.bodies.contains(body) {
        return Err(invariant(ClassInvariant::InvalidPlan(body.declaration)));
    }
    let signature = match body.kind {
        ClassBodyKind::Constructor => Some(prepared.construct_signature),
        ClassBodyKind::StaticBlock | ClassBodyKind::PropertyInitializer { .. } => None,
        ClassBodyKind::Method { symbol, .. } => {
            let index = prepared
                .plan
                .methods
                .iter()
                .position(|method| {
                    method.method.symbol == symbol && method.method.declaration == body.declaration
                })
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidPropertySymbol(body.declaration))
                })?;
            Some(prepared.methods[index].1)
        }
    };
    Ok(ClassBodyAccessToken {
        class_symbol: prepared.plan.symbol(),
        class_declaration: prepared.plan.declaration(),
        declaration: body.declaration,
        body: body.body,
        instance_type: prepared.instance_type,
        value_type: prepared.value_type,
        signature,
    })
}

impl PreparedSourceClass {
    pub(super) fn body_access(
        &self,
        store: &CanonicalTypeMapperStore,
        host: &DeclaredTypeHost<'_>,
        body: &ClassBodyPlan,
    ) -> Result<ClassBodyAccessToken, ClassError> {
        let provenance = store
            .source_class_provenance(self.instance_type)
            .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(self.plan.declaration())))?;
        if provenance.prepared != *self {
            return Err(invariant(ClassInvariant::InvalidPlan(
                self.plan.declaration(),
            )));
        }
        validate_source_class_header(store, host, provenance)?;
        source_class_body_token(self, body)
    }
}

fn source_class_access<'a>(
    store: &'a CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    access: &ClassBodyAccessToken,
) -> Result<(&'a SourceClassProvenance, usize), ClassError> {
    let provenance = store
        .source_class_provenance(access.instance_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(access.class_declaration)))?;
    validate_source_class_header(store, host, provenance)?;
    let index = provenance
        .prepared
        .plan
        .bodies
        .iter()
        .position(|body| body.declaration == access.declaration && body.body == access.body)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(access.declaration)))?;
    if source_class_body_token(
        &provenance.prepared,
        &provenance.prepared.plan.bodies[index],
    )? != *access
    {
        return Err(invariant(ClassInvariant::InvalidPlan(access.declaration)));
    }
    Ok((provenance, index))
}

pub(super) fn class_body_identities(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    access: &ClassBodyAccessToken,
) -> Result<ClassBodyIdentities, ClassError> {
    let (provenance, _) = source_class_access(store, host, access)?;
    Ok(ClassBodyIdentities {
        class_declaration: access.class_declaration,
        class_symbol: access.class_symbol,
        body_declaration: access.declaration,
        instance_type: access.instance_type,
        this_type: provenance.this_type,
        value_type: access.value_type,
        base: provenance.members.base,
    })
}

fn class_instance_super_origin(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    class_symbol: SemanticSymbolId,
    access: Option<&ClassBodyAccessToken>,
) -> Result<ClassInstanceSuperOrigin, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidHeritageCache(class_symbol));
    let (instance_type, this_type, base) = if let Some(access) = access {
        let identities = class_body_identities(store, host, access)?;
        if identities.class_symbol != class_symbol {
            return Err(invalid());
        }
        (
            identities.instance_type,
            identities.this_type,
            identities.base.ok_or_else(invalid)?,
        )
    } else {
        let instance_type = store
            .declared_type_links(class_symbol)
            .and_then(|links| links.declared_type)
            .ok_or_else(invalid)?;
        if validate_class_heritage_members(store, instance_type)
            != ClassHeritageMembersValidation::Valid
        {
            return Err(invalid());
        }
        let class = exact_class_instance_identity(store, class_symbol, instance_type)
            .ok_or_else(invalid)?;
        let base = store
            .direct_class_heritage_provenance(instance_type)
            .ok_or_else(invalid)?;
        (
            instance_type,
            class.this_type.ok_or_else(invalid)?,
            ClassBaseIdentities {
                symbol: base.base_symbol,
                instance_type: base.base_instance_type,
                value_type: base.base_value_type,
            },
        )
    };
    let declaration = store
        .symbol(class_symbol)
        .and_then(Symbol::value_declaration)
        .ok_or_else(invalid)?;
    if let Some(edge) = store.direct_class_heritage_provenance(instance_type)
        && source_constructor_heritage_is_exact(store, instance_type, edge)
    {
        if !host.symbol_matches(store, declaration, class_symbol) {
            return Err(invalid());
        }
        return Ok(ClassInstanceSuperOrigin {
            class_symbol,
            instance_type,
            this_type,
            base_symbol: store
                .type_payload(base.instance_type())
                .and_then(TypeRecord::symbol)
                .ok_or_else(invalid)?,
            base_instance: base.instance_type(),
            base_this: None,
        });
    }
    if !host.symbol_matches(store, declaration, class_symbol)
        || validate_class_heritage_members(store, base.instance_type())
            != ClassHeritageMembersValidation::Valid
    {
        return Err(invalid());
    }
    let derived =
        exact_class_instance_identity(store, class_symbol, instance_type).ok_or_else(invalid)?;
    let base_type = exact_class_instance_identity(store, base.symbol(), base.instance_type())
        .ok_or_else(invalid)?;
    if derived.reference.resolved_type_arguments.as_deref() != Some(&[])
        || base_type.reference.resolved_type_arguments.as_deref() != Some(&[])
    {
        return Err(unsupported(ClassUnsupported::Generic(declaration)));
    }
    let base_this = base_type.this_type.ok_or_else(invalid)?;
    if instance_type == base.instance_type() || this_type == base_this {
        return Err(invalid());
    }
    Ok(ClassInstanceSuperOrigin {
        class_symbol,
        instance_type,
        this_type,
        base_symbol: base.symbol(),
        base_instance: base.instance_type(),
        base_this: Some(base_this),
    })
}

fn class_super_this_identity_is_valid(
    store: &CanonicalTypeMapperStore,
    symbol: SemanticSymbolId,
    instance: TypeId,
    this_type: TypeId,
) -> bool {
    let Some(record) = store.type_payload(instance) else {
        return false;
    };
    let TypeData::Interface(class) = record.data() else {
        return false;
    };
    let Some(this) = store.type_payload(this_type) else {
        return false;
    };
    record.flags() == TypeFlags::OBJECT
        && record
            .object_flags()
            .contains(ObjectFlags::CLASS | ObjectFlags::REFERENCE)
        && record.symbol() == Some(symbol)
        && record.alias().is_none()
        && class.this_type == Some(this_type)
        && class.reference.object.target == Some(instance)
        && store
            .declared_type_links(symbol)
            .and_then(|links| links.declared_type)
            == Some(instance)
        && this.flags() == TypeFlags::TYPE_PARAMETER
        && this.object_flags() == ObjectFlags::NONE
        && this.symbol() == Some(symbol)
        && this.alias().is_none()
        && matches!(this.data(), TypeData::TypeParameter(data)
        if data == &TypeParameterData {
            constraint: Some(instance),
            is_this_type: true,
            ..TypeParameterData::default()
        })
}

// This check must not recurse through complete class validation: a base cache
// can contain a view whose derived class is still checking its body.
fn class_instance_super_view_shell_is_valid(
    store: &CanonicalTypeMapperStore,
    view: ClassInstanceSuperView,
) -> bool {
    let origin = view.origin;
    if origin.base_this.is_none() {
        return view.reference == origin.base_instance
            && view.mapper.is_none()
            && class_super_this_identity_is_valid(
                store,
                origin.class_symbol,
                origin.instance_type,
                origin.this_type,
            )
            && store
                .direct_class_heritage_provenance(origin.instance_type)
                .is_some_and(|edge| {
                    edge.base_instance_type == origin.base_instance
                        && source_constructor_heritage_is_exact(store, origin.instance_type, edge)
                })
            && store
                .type_payload(origin.base_instance)
                .and_then(TypeRecord::symbol)
                == Some(origin.base_symbol);
    }
    let Some(record) = store.type_payload(view.reference) else {
        return false;
    };
    let TypeData::TypeReference(reference) = record.data() else {
        return false;
    };
    let Some(base) = store.type_payload(origin.base_instance) else {
        return false;
    };
    let expected_key = type_list_key(&[origin.this_type]);
    let cache_matches = matches!(base.data(), TypeData::Interface(base)
        if matches!(&base.reference.object.instantiations, TypeCacheState::Allocated(cache)
            if cache.get(&expected_key) == Some(&view.reference)));
    store.class_instance_super_view(view.reference) == Some(view)
        && store.class_instance_super_view_for_instance(origin.instance_type) == Some(view)
        && origin.instance_type != origin.base_instance
        && class_super_this_identity_is_valid(
            store,
            origin.class_symbol,
            origin.instance_type,
            origin.this_type,
        )
        && class_super_this_identity_is_valid(
            store,
            origin.base_symbol,
            origin.base_instance,
            origin
                .base_this
                .expect("the mapped base has its real this type"),
        )
        && store
            .direct_class_heritage_provenance(origin.instance_type)
            .is_some_and(|base| {
                base.owner_symbol == origin.class_symbol
                    && base.base_symbol == origin.base_symbol
                    && base.base_instance_type == origin.base_instance
            })
        && cache_matches
        && record.flags() == TypeFlags::OBJECT
        && record.object_flags() == ObjectFlags::REFERENCE
        && record.symbol() == Some(origin.base_symbol)
        && record.alias().is_none()
        && reference.object.target == Some(origin.base_instance)
        && reference.object.mapper.is_none()
        && reference.object.instantiations == TypeCacheState::Unallocated
        && reference.object.structured == StructuredTypeData::default()
        && reference.node.is_none()
        && reference.resolved_type_arguments.as_deref() == Some(&[origin.this_type])
        && store.type_mapper_has_exact_endpoints(
            match view.mapper {
                Some(mapper) => mapper,
                None => return false,
            },
            &[origin
                .base_this
                .expect("the mapped base has its real this type")],
            &[origin.this_type],
        ) == Some(true)
}

pub(super) fn validate_class_instance_super_view(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    class_symbol: SemanticSymbolId,
    access: Option<&ClassBodyAccessToken>,
    reference: TypeId,
) -> Result<ClassInstanceSuperView, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidHeritageCache(class_symbol));
    let origin = class_instance_super_origin(store, host, class_symbol, access)?;
    if origin.base_this.is_none() {
        let view = ClassInstanceSuperView {
            origin,
            reference,
            mapper: None,
        };
        return if class_instance_super_view_shell_is_valid(store, view) {
            Ok(view)
        } else {
            Err(invalid())
        };
    }
    let view = store
        .class_instance_super_view(reference)
        .ok_or_else(invalid)?;
    if view.origin != origin || !class_instance_super_view_shell_is_valid(store, view) {
        return Err(invalid());
    }
    Ok(view)
}

pub(super) fn prepare_class_instance_super_view(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    class_symbol: SemanticSymbolId,
    access: Option<&ClassBodyAccessToken>,
) -> Result<ClassInstanceSuperView, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidHeritageCache(class_symbol));
    let origin = class_instance_super_origin(store, host, class_symbol, access)?;
    if origin.base_this.is_none() {
        return validate_class_instance_super_view(
            store,
            host,
            class_symbol,
            access,
            origin.base_instance,
        );
    }
    if let Some(view) = store.class_instance_super_view_for_instance(origin.instance_type) {
        return validate_class_instance_super_view(
            store,
            host,
            class_symbol,
            access,
            view.reference,
        );
    }
    let key = type_list_key(&[origin.this_type]);
    let base = store
        .type_payload(origin.base_instance)
        .ok_or_else(invalid)?;
    let TypeData::Interface(base) = base.data() else {
        return Err(invalid());
    };
    let TypeCacheState::Allocated(cache) = &base.reference.object.instantiations else {
        return Err(invalid());
    };
    if cache.contains_key(&key) {
        return Err(invalid());
    }
    if !store.try_reserve_types(1)
        || !store.try_reserve_mappers(1)
        || !store.try_reserve_object_instantiations(origin.base_instance, 1)
        || !store.try_reserve_class_instance_super_views()
    {
        return Err(invariant(ClassInvariant::Capacity(
            store
                .symbol(class_symbol)
                .and_then(Symbol::value_declaration)
                .ok_or_else(invalid)?,
        )));
    }
    let mapper = store
        .new_type_mapper(
            vec![origin.base_this.ok_or_else(invalid)?],
            vec![origin.this_type],
        )
        .ok_or_else(invalid)?;
    let reference = store
        .alloc_type_reference(ObjectFlags::NONE, Some(origin.base_symbol))
        .ok_or_else(invalid)?;
    assert!(store.set_object_target_and_mapper(reference, Some(origin.base_instance), None));
    assert!(store.set_type_reference_resolution(reference, None, Some(vec![origin.this_type])));
    let view = ClassInstanceSuperView {
        origin,
        reference,
        mapper: Some(mapper),
    };
    assert!(store.publish_class_instance_super_view(view));
    assert_eq!(
        store.insert_object_instantiation(origin.base_instance, key, reference),
        Some(reference),
    );
    debug_assert!(class_instance_super_view_shell_is_valid(store, view));
    Ok(view)
}

fn validate_stored_class_instance_super_view(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    view: ClassInstanceSuperView,
) -> Result<(), ClassError> {
    let invalid = || {
        invariant(ClassInvariant::InvalidHeritageCache(
            view.origin.class_symbol,
        ))
    };
    if !class_instance_super_view_shell_is_valid(store, view) {
        return Err(invalid());
    }
    if let Some(provenance) = store.source_class_provenance(view.origin.instance_type) {
        validate_source_class_header(store, host, provenance)?;
        if provenance.symbol() != view.origin.class_symbol {
            return Err(invalid());
        }
    } else if validate_class_heritage_members(store, view.origin.instance_type)
        != ClassHeritageMembersValidation::Valid
    {
        return Err(invalid());
    }
    if view.origin.base_this.is_some()
        && validate_class_heritage_members(store, view.origin.base_instance)
            != ClassHeritageMembersValidation::Valid
    {
        return Err(invalid());
    }
    Ok(())
}

fn class_instance_super_view_graph_is_valid(
    store: &CanonicalTypeMapperStore,
    view: ClassInstanceSuperView,
) -> bool {
    class_instance_super_view_shell_is_valid(store, view)
        && match store.source_class_provenance(view.origin.instance_type) {
            Some(provenance) => {
                provenance.symbol() == view.origin.class_symbol
                    && validate_source_class_stored_header(store, provenance).is_ok()
            }
            None => {
                validate_class_heritage_members(store, view.origin.instance_type)
                    == ClassHeritageMembersValidation::Valid
            }
        }
        && (view.origin.base_this.is_none()
            || validate_class_heritage_members(store, view.origin.base_instance)
                == ClassHeritageMembersValidation::Valid)
}

pub(super) fn class_instance_super_display_symbol(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    type_: TypeId,
) -> Result<Option<SemanticSymbolId>, ClassError> {
    let Some(view) = store.class_instance_super_view(type_) else {
        return Ok(None);
    };
    validate_stored_class_instance_super_view(store, host, view)?;
    Ok(Some(view.origin.base_symbol))
}

pub(super) fn class_instance_super_display_callable(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    type_: TypeId,
) -> Result<Option<ValidatedSingleCallable>, ClassError> {
    let Some(cached) = store.class_instance_super_member_for_type(type_) else {
        return Ok(None);
    };
    let view = store
        .class_instance_super_view(cached.view)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(cached.member)))?;
    let cached = validated_class_instance_super_member(store, host, view, cached.member)?;
    Ok(cached.callable)
}

pub(super) fn stored_class_instance_super_callable(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
) -> Option<Result<ValidatedSingleCallable, ()>> {
    let cached = store.class_instance_super_member_for_type(type_)?;
    Some((|| {
        let view = store.class_instance_super_view(cached.view).ok_or(())?;
        let member = store.symbol(cached.member).ok_or(())?;
        let structured = store
            .type_payload(view.lookup_type())
            .and_then(|record| record.data().structured())
            .ok_or(())?;
        let declaring = store
            .declared_type_links(cached.source.declaring_class)
            .and_then(|links| links.declared_type)
            .ok_or(())?;
        if !class_instance_super_view_graph_is_valid(store, view)
            || cached.source.symbol != cached.member
            || cached.source.origin != ClassMemberOrigin::Method
            || cached.source.side != ClassPropertySide::Instance
            || member.parent() != Some(cached.source.declaring_class)
            || member.value_declaration() != Some(cached.source.declaration)
            || structured
                .members
                .and_then(|table| store.symbol_table(table))
                .and_then(|table| table.get(member.name()))
                != Some(cached.member)
            || structured
                .properties
                .as_deref()
                .is_none_or(|members| !members.contains(&cached.member))
            || !class_super_this_identity_is_valid(
                store,
                cached.source.declaring_class,
                declaring,
                cached.declaring_this,
            )
        {
            return Err(());
        }
        let StoredCallableSetValidation::Valid { projection, .. } =
            validate_stored_callable_set(store, cached.source_type)
        else {
            return Err(());
        };
        let [source] = projection.call_signatures.as_ref() else {
            return Err(());
        };
        if !projection.construct_signatures.is_empty() {
            return Err(());
        }
        let template = ClassSuperMemberTemplate {
            source: cached.source.clone(),
            declaring_this: cached.declaring_this,
            type_: cached.source_type,
            callable: Some(source.clone()),
        };
        if !class_super_member_cache_is_valid(store, view, &template, cached) {
            return Err(());
        }
        cached.callable.clone().ok_or(())
    })())
}

struct ClassSuperMemberTemplate {
    source: ClassMemberSource,
    declaring_this: TypeId,
    type_: TypeId,
    callable: Option<ValidatedSingleCallable>,
}

fn class_super_member_template(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    view: ClassInstanceSuperView,
    member: SemanticSymbolId,
) -> Result<ClassSuperMemberTemplate, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidPropertyValueCache(member));
    validate_stored_class_instance_super_view(store, host, view)?;
    let source = class_member_source(store, host, member)?;
    let property = store.symbol(member).ok_or_else(invalid)?;
    let structured = store
        .type_payload(view.lookup_type())
        .and_then(|record| record.data().structured())
        .ok_or_else(invalid)?;
    if source.side != ClassPropertySide::Instance
        || structured
            .members
            .and_then(|table| store.symbol_table(table))
            .and_then(|table| table.get(property.name()))
            != Some(member)
        || structured
            .properties
            .as_deref()
            .is_none_or(|properties| !properties.contains(&member))
    {
        return Err(invalid());
    }
    let declaring_instance = store
        .declared_type_links(source.declaring_class)
        .and_then(|links| links.declared_type)
        .ok_or_else(invalid)?;
    let declaring =
        exact_class_instance_identity(store, source.declaring_class, declaring_instance)
            .ok_or_else(invalid)?;
    if declaring.reference.resolved_type_arguments.as_deref() != Some(&[]) {
        return Err(unsupported(ClassUnsupported::Generic(source.declaration)));
    }
    let declaring_this = declaring.this_type.ok_or_else(invalid)?;
    let type_ = store
        .value_symbol_links(member)
        .and_then(|links| links.resolved_type)
        .ok_or_else(invalid)?;
    let callable = if source.origin == ClassMemberOrigin::Method {
        let signature = store
            .signature_links(source.declaration)
            .and_then(|links| links.resolved_signature.signature())
            .ok_or_else(invalid)?;
        let callable = if store.source_class_provenance(declaring_instance).is_some() {
            source_class_callable_projection(store, type_, signature, member)?
        } else {
            let StoredCallableSetValidation::Valid { projection, .. } =
                validate_stored_callable_set(store, type_)
            else {
                return Err(invalid());
            };
            let [callable] = projection.call_signatures.as_ref() else {
                return Err(invalid());
            };
            if !projection.construct_signatures.is_empty() || callable.signature != signature {
                return Err(invalid());
            }
            callable.clone()
        };
        if callable.return_type.is_none() {
            return Err(unsupported(ClassUnsupported::Member {
                node: source.declaration,
                kind: SyntaxKind::MethodDeclaration,
            }));
        }
        Some(callable)
    } else {
        None
    };
    Ok(ClassSuperMemberTemplate {
        source,
        declaring_this,
        type_,
        callable,
    })
}

fn class_super_parameter_is_valid(
    store: &CanonicalTypeMapperStore,
    source: SemanticSymbolId,
    actual: SemanticSymbolId,
    type_: TypeId,
    mapper: TypeMapperId,
) -> bool {
    let Some(source_record) = store.symbol(source) else {
        return false;
    };
    let Some(source_links) = store.value_symbol_links(source) else {
        return false;
    };
    if source == actual {
        return source_links.resolved_type == Some(type_);
    }
    let Some(record) = store.symbol(actual) else {
        return false;
    };
    record.flags() == source_record.flags() | SymbolFlags::TRANSIENT
        && record.check_flags()
            == CheckFlags::INSTANTIATED
                | (source_record.check_flags()
                    & (CheckFlags::READONLY
                        | CheckFlags::LATE
                        | CheckFlags::OPTIONAL_PARAMETER
                        | CheckFlags::REST_PARAMETER))
        && record.name() == source_record.name()
        && record.declarations() == source_record.declarations()
        && record.value_declaration() == source_record.value_declaration()
        && record.parent() == source_record.parent()
        && record.members().is_none()
        && record.exports().is_none()
        && record.export_symbol().is_none()
        && store.get_merged_symbol(actual) == Some(actual)
        && store.value_symbol_links(actual)
            == Some(&ValueSymbolLinks {
                resolved_type: Some(type_),
                target: Some(source),
                mapper: Some(mapper),
                name_type: source_links.name_type,
                ..ValueSymbolLinks::default()
            })
}

// Anonymous object returns can be outside the instantiator's admitted domain.
// Keep their identity only after proving that no mapped this occurs in them.
fn class_super_member_type_is_unchanged(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
    this_type: TypeId,
    array_targets: Option<CanonicalArrayTargets>,
) -> bool {
    if !store.type_payload(type_).is_some_and(|record| {
        matches!(
            record.data(),
            TypeData::Object(_)
                | TypeData::Interface(_)
                | TypeData::TypeReference(_)
                | TypeData::Union(_)
        )
    }) {
        return false;
    }
    let mut pending = vec![type_];
    let mut visited = HashSet::new();
    while let Some(type_) = pending.pop() {
        if type_ == this_type {
            return false;
        }
        if !visited.insert(type_) {
            continue;
        }
        let valid = match array_targets {
            Some(targets) => store.validate_union_constituent_with_array_targets(targets, type_),
            None => store.validate_union_constituent(type_),
        };
        if valid.is_err() {
            return false;
        }
        let Some(record) = store.type_payload(type_) else {
            return false;
        };
        if let Some(alias) = record.alias() {
            let Some(alias) = store.type_alias(alias) else {
                return false;
            };
            pending.extend(alias.type_arguments().unwrap_or_default());
        }
        match record.data() {
            TypeData::Intrinsic(_) | TypeData::Literal(_) | TypeData::TypeParameter(_) => {}
            TypeData::Interface(interface) => {
                // A named reference substitutes its arguments, not its members.
                pending.extend(
                    interface
                        .reference
                        .resolved_type_arguments
                        .as_deref()
                        .unwrap_or_default(),
                );
            }
            TypeData::TypeReference(reference) => {
                let Some(arguments) = &reference.resolved_type_arguments else {
                    return false;
                };
                pending.extend(arguments);
            }
            TypeData::Union(union) => {
                pending.extend(&union.union.types);
                pending.extend(union.origin);
            }
            TypeData::Object(object) => {
                match validate_stored_callable_set(store, type_) {
                    StoredCallableSetValidation::Valid { edges, .. } => pending.extend(edges),
                    StoredCallableSetValidation::NotCallable => {}
                    StoredCallableSetValidation::Pending { .. }
                    | StoredCallableSetValidation::Malformed { .. } => return false,
                }
                if object.structured.index_infos.is_some() {
                    return false;
                }
                for property in object.structured.properties.as_deref().unwrap_or_default() {
                    let Some(type_) = store
                        .value_symbol_links(*property)
                        .and_then(|links| links.resolved_type)
                    else {
                        return false;
                    };
                    pending.push(type_);
                }
            }
            _ => return false,
        }
    }
    true
}

fn class_super_member_cache_is_valid(
    store: &CanonicalTypeMapperStore,
    view: ClassInstanceSuperView,
    template: &ClassSuperMemberTemplate,
    cached: &ClassInstanceSuperMember,
) -> bool {
    if cached.view != view.reference
        || cached.member != template.source.symbol
        || cached.source != template.source
        || cached.source_type != template.type_
        || cached.declaring_this != template.declaring_this
        || cached.source_callable != template.callable
        || store.type_mapper_has_exact_endpoints(
            cached.mapper,
            &[template.declaring_this],
            &[view.origin.this_type],
        ) != Some(true)
    {
        return false;
    }
    let mapped = |source, actual| {
        source == actual
            && class_super_member_type_is_unchanged(
                store,
                source,
                template.declaring_this,
                cached.array_targets,
            )
            || instantiated_member_type_matches(
                store,
                source,
                actual,
                cached.mapper,
                cached.array_targets,
            ) == Ok(true)
    };
    let Some(source) = &template.callable else {
        return cached.callable.is_none() && mapped(template.type_, cached.type_);
    };
    let Some(callable) = &cached.callable else {
        return false;
    };
    if callable.owner != cached.type_
        || callable.parameters.len() != source.parameters.len()
        || callable.rest_parameter.is_some() != source.rest_parameter.is_some()
        || callable.min_argument_count != source.min_argument_count
        || callable.strict_variance_exempt != source.strict_variance_exempt
        || !source
            .parameters
            .iter()
            .chain(source.rest_parameter.iter())
            .zip(
                callable
                    .parameters
                    .iter()
                    .chain(callable.rest_parameter.iter()),
            )
            .all(|(source, actual)| mapped(*source, *actual))
        || !source
            .return_type
            .zip(callable.return_type)
            .is_some_and(|(source, actual)| mapped(source, actual))
    {
        return false;
    }
    if cached.type_ == template.type_ {
        return callable == source;
    }
    let Some(original) = store.signature(source.signature) else {
        return false;
    };
    let Some(signature) = store.signature(callable.signature) else {
        return false;
    };
    let Some(record) = store.type_payload(cached.type_) else {
        return false;
    };
    let TypeData::Object(object) = record.data() else {
        return false;
    };
    record.flags() == TypeFlags::OBJECT
        && record.object_flags() == ObjectFlags::ANONYMOUS | ObjectFlags::MEMBERS_RESOLVED
        && record.symbol() == Some(cached.member)
        && record.alias().is_none()
        && object
            == &ObjectTypeData {
                target: Some(template.type_),
                mapper: Some(cached.mapper),
                structured: StructuredTypeData {
                    signatures: Some(vec![callable.signature]),
                    call_signature_count: 1,
                    ..StructuredTypeData::default()
                },
                ..ObjectTypeData::default()
            }
        && callable.signature != source.signature
        && signature.target() == Some(source.signature)
        && signature.mapper() == Some(cached.mapper)
        && signature.declaration() == original.declaration()
        && signature.flags() == original.flags() & SignatureFlags::PROPAGATING_FLAGS
        && signature.type_parameters().is_empty()
        && signature.this_parameter().is_none()
        && signature.parameters().len() == original.parameters().len()
        && signature.min_argument_count() == original.min_argument_count()
        && (signature.resolved_min_argument_count() == -1
            || signature.resolved_min_argument_count() == original.min_argument_count())
        && signature.resolved_return_type() == callable.return_type
        && signature.resolved_type_predicate().is_none()
        && signature.isolated_signature_type().is_none()
        && signature.composite().is_none()
        && original
            .parameters()
            .iter()
            .zip(signature.parameters())
            .zip(
                callable
                    .parameters
                    .iter()
                    .chain(callable.rest_parameter.iter()),
            )
            .all(|((source, actual), type_)| {
                class_super_parameter_is_valid(store, *source, *actual, *type_, cached.mapper)
            })
}

pub(super) fn validated_class_instance_super_member(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    view: ClassInstanceSuperView,
    member: SemanticSymbolId,
) -> Result<ClassInstanceSuperMember, ClassError> {
    let template = class_super_member_template(store, host, view, member)?;
    let cached = store
        .class_instance_super_member(view.reference, member)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(member)))?;
    if !class_super_member_cache_is_valid(store, view, &template, cached) {
        return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
    }
    Ok(cached.clone())
}

pub(super) fn prepare_class_instance_super_member_type(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    globals: Option<&CanonicalGlobalTypes>,
    view: ClassInstanceSuperView,
    member: SemanticSymbolId,
) -> Result<TypeId, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidPropertyValueCache(member));
    if view.origin.base_this.is_none() {
        validate_stored_class_instance_super_view(store, host, view)?;
        let source = class_member_source(store, host, member)?;
        let property = store.symbol(member).ok_or_else(invalid)?;
        let members = store
            .type_payload(view.lookup_type())
            .and_then(|record| record.data().structured())
            .ok_or_else(invalid)?;
        if source.side != ClassPropertySide::Instance
            || source.declaring_class != view.origin.base_symbol
            || members
                .members
                .and_then(|table| store.symbol_table(table))
                .and_then(|table| table.get(property.name()))
                != Some(member)
            || members
                .properties
                .as_deref()
                .is_none_or(|properties| !properties.contains(&member))
        {
            return Err(invalid());
        }
        return store
            .value_symbol_links(member)
            .and_then(|links| links.resolved_type)
            .ok_or_else(invalid);
    }
    let template = class_super_member_template(store, host, view, member)?;
    if store
        .class_instance_super_member(view.reference, member)
        .is_some()
    {
        return validated_class_instance_super_member(store, host, view, member)
            .map(|cached| cached.type_);
    }
    let array_targets = globals.map(CanonicalArrayTargets::from_global_types);
    let sources = [template.declaring_this];
    let targets = [view.origin.this_type];
    let mut session = InstantiationSession::new(InstantiationLimits::default());
    let originals = match &template.callable {
        Some(callable) => callable
            .parameters
            .iter()
            .copied()
            .chain(callable.rest_parameter)
            .chain(callable.return_type)
            .collect::<Vec<_>>(),
        None => vec![template.type_],
    };
    let instantiated = originals
        .iter()
        .map(|type_| {
            if class_super_member_type_is_unchanged(
                store,
                *type_,
                template.declaring_this,
                array_targets,
            ) {
                return Ok(*type_);
            }
            instantiate_type_with_vector_and_session(
                store,
                *type_,
                &sources,
                &targets,
                array_targets,
                &mut session,
            )
            .map_err(|error| match error {
                InstantiationError::UnsupportedType(_) => host
                    .node(template.source.declaration)
                    .map_or_else(invalid, |node| {
                        unsupported(ClassUnsupported::Member {
                            node: template.source.declaration,
                            kind: node.kind,
                        })
                    }),
                _ => invalid(),
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    if !store.try_reserve_class_instance_super_members()
        || !store.try_reserve_mappers(usize::from(
            Some(template.declaring_this) != view.origin.base_this,
        ))
        || !store.try_reserve_types(1)
        || !store.try_reserve_signatures(1)
    {
        return Err(invariant(ClassInvariant::Capacity(
            template.source.declaration,
        )));
    }
    let mapper = if Some(template.declaring_this) == view.origin.base_this {
        view.mapper.ok_or_else(invalid)?
    } else {
        store
            .new_type_mapper(sources.to_vec(), targets.to_vec())
            .ok_or_else(invalid)?
    };
    let (type_, callable) = match &template.callable {
        Some(source) if instantiated == originals => (template.type_, Some(source.clone())),
        Some(source) => {
            let signature = store
                .instantiate_signature(source.signature, mapper)
                .map_err(|_| invalid())?;
            let parameters = store
                .signature(signature)
                .ok_or_else(invalid)?
                .parameters()
                .to_vec();
            let returned = instantiated.last().copied().ok_or_else(invalid)?;
            if parameters.len() + 1 != instantiated.len() {
                return Err(invalid());
            }
            for (parameter, type_) in parameters.iter().zip(&instantiated) {
                let mut links = store
                    .value_symbol_links(*parameter)
                    .cloned()
                    .ok_or_else(invalid)?;
                if links.resolved_type.is_some_and(|cached| cached != *type_) {
                    return Err(invalid());
                }
                if links.resolved_type.is_none() {
                    links.resolved_type = Some(*type_);
                    assert!(store.set_value_symbol_links(*parameter, links));
                }
            }
            assert!(store.set_signature_resolved_return_type(signature, Some(returned)));
            let type_ = store
                .alloc_plain_object_type(ObjectFlags::ANONYMOUS, Some(member))
                .ok_or_else(invalid)?;
            assert!(store.set_object_target_and_mapper(type_, Some(template.type_), Some(mapper)));
            assert!(store.set_structured_type_members(
                type_,
                None,
                None,
                Some(vec![signature]),
                None,
                None,
            ));
            (
                type_,
                Some(ValidatedSingleCallable {
                    owner: type_,
                    signature,
                    parameters: instantiated[..source.parameters.len()].to_vec(),
                    rest_parameter: source
                        .rest_parameter
                        .map(|_| instantiated[source.parameters.len()]),
                    min_argument_count: source.min_argument_count,
                    return_type: Some(returned),
                    strict_variance_exempt: source.strict_variance_exempt,
                }),
            )
        }
        None => (instantiated[0], None),
    };
    let cached = ClassInstanceSuperMember {
        view: view.reference,
        member,
        source: template.source.clone(),
        declaring_this: template.declaring_this,
        mapper,
        source_type: template.type_,
        type_,
        array_targets,
        source_callable: template.callable.clone(),
        callable,
    };
    if !class_super_member_cache_is_valid(store, view, &template, &cached) {
        return Err(invalid());
    }
    assert!(store.publish_class_instance_super_member(cached));
    Ok(type_)
}

pub(super) fn pending_source_class_property_type(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    member: &ClassMemberSource,
) -> Result<Option<ClassPropertyTypeDemand>, ClassError> {
    let Some(provenance) = store.source_class_provenance_for_symbol(member.declaring_class) else {
        return Ok(None);
    };
    validate_source_class_header(store, host, provenance)?;
    let plan = &provenance.prepared.plan;
    let Some(index) = plan
        .initialized_properties
        .iter()
        .position(|property| property.symbol == member.symbol)
    else {
        return Ok(None);
    };
    if provenance.property_types[index].is_some() {
        return Ok(None);
    }
    let property = &plan.initialized_properties[index];
    let body = plan
        .bodies
        .iter()
        .find(|body| {
            body.declaration == property.declaration
                && Some(body.body) == property.initializer_node
                && matches!(body.kind, ClassBodyKind::PropertyInitializer { symbol, .. }
                    if symbol == member.symbol)
        })
        .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(property.declaration)))?;
    if plan
        .sources
        .iter()
        .find(|source| source.symbol == member.symbol)
        != Some(member)
    {
        return Err(invariant(ClassInvariant::InvalidPropertySymbol(
            member.declaration,
        )));
    }
    Ok(Some(ClassPropertyTypeDemand {
        class_symbol: plan.symbol(),
        symbol: member.symbol,
        declaration: body.declaration,
        body: body.body,
    }))
}

/// Reuses a checked field only after its class's source bodies have completed.
fn completed_source_class_property_type(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
    symbol: SemanticSymbolId,
    declaration: NodeRef,
    initializer: NodeRef,
) -> Result<Option<TypeId>, ClassError> {
    let Some(provenance) = store.source_class_provenance_for_symbol(owner) else {
        return Ok(None);
    };
    validate_source_class_header(store, host, provenance)?;
    let plan = &provenance.prepared.plan;
    let Some(index) = plan
        .initialized_properties
        .iter()
        .position(|property| property.symbol == symbol)
    else {
        return Ok(None);
    };
    let property = &plan.initialized_properties[index];
    if property.declaration != declaration || property.initializer_node != Some(initializer) {
        return Err(invariant(ClassInvariant::InvalidPropertySymbol(
            declaration,
        )));
    }
    let body = plan
        .bodies
        .iter()
        .position(|body| {
            body.declaration == declaration
                && body.body == initializer
                && body.kind
                    == (ClassBodyKind::PropertyInitializer {
                        symbol,
                        side: property.side,
                    })
        })
        .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(declaration)))?;
    if !provenance.complete {
        return Ok(None);
    }
    if !provenance.completed_bodies[body] {
        return Err(invariant(ClassInvariant::InvalidPlan(declaration)));
    }
    provenance.property_types[index]
        .map(Some)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))
}

pub(super) fn complete_source_class_body(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    prepared: &PreparedSourceClass,
    body: &ClassBodyPlan,
    checked: &super::source::CheckedClassBody,
) -> Result<(), ClassError> {
    let token = prepared.body_access(store, host, body)?;
    if checked.declaration() != body.declaration
        || checked.body() != body.body
        || checked.access_token() != &token
    {
        return Err(invariant(ClassInvariant::InvalidPlan(body.declaration)));
    }
    let (provenance, body_index) = source_class_access(store, host, &token)?;
    let inferred = match body.kind {
        ClassBodyKind::Method { symbol, .. } if body.return_annotation.is_none() => {
            let index = prepared
                .plan
                .methods
                .iter()
                .position(|method| {
                    method.method.symbol == symbol && method.method.declaration == body.declaration
                })
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidPropertySymbol(body.declaration))
                })?;
            let returned = checked
                .inferred_return_type()
                .filter(|type_| store.type_payload(*type_).is_some())
                .ok_or_else(|| {
                    invariant(ClassInvariant::InvalidPropertyTypeCache(body.declaration))
                })?;
            if provenance.completed_bodies[body_index]
                && provenance.method_returns[index] != Some(returned)
            {
                return Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
                    body.declaration,
                )));
            }
            Some((index, returned))
        }
        _ => None,
    };
    let property = if let ClassBodyKind::PropertyInitializer { symbol, .. } = body.kind {
        let index = prepared
            .plan
            .initialized_properties
            .iter()
            .position(|property| property.symbol == symbol)
            .ok_or_else(|| invariant(ClassInvariant::InvalidPropertySymbol(body.declaration)))?;
        let type_ = checked
            .property_type()
            .filter(|type_| store.type_payload(*type_).is_some())
            .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyTypeCache(body.declaration)))?;
        if checked.inferred_return_type().is_some()
            || store
                .type_node_links(body.body)
                .and_then(|links| links.resolved_type)
                .is_none()
            || body.return_annotation.is_some_and(|annotation| {
                store
                    .type_node_links(annotation)
                    .and_then(|links| links.resolved_type)
                    != Some(type_)
            })
            || provenance.completed_bodies[body_index]
                && provenance.property_types[index] != Some(type_)
        {
            return Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
                body.declaration,
            )));
        }
        let property = &prepared.plan.initialized_properties[index];
        if store.source_node_kind(property.type_node) == Some(SyntaxKind::ObjectLiteralExpression) {
            validate_private_object_property_type(
                store,
                property,
                type_,
                prepared
                    .plan
                    .type_query_context
                    .as_ref()
                    .map(|context| &context.global_types),
            )?;
        }
        Some((index, symbol, type_))
    } else {
        if checked.property_type().is_some() {
            return Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
                body.declaration,
            )));
        }
        None
    };
    if provenance.completed_bodies[body_index] {
        return Ok(());
    }
    if let Some((index, returned)) = inferred
        && !store.set_signature_resolved_return_type(prepared.methods[index].1, Some(returned))
    {
        return Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
            body.declaration,
        )));
    }
    if let Some((_, symbol, type_)) = property
        && (!store.try_reserve_value_symbol_links(1)
            || !store.set_value_symbol_links(
                symbol,
                ValueSymbolLinks {
                    resolved_type: Some(type_),
                    ..ValueSymbolLinks::default()
                },
            ))
    {
        return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
    }
    let provenance = store
        .source_class_provenance_mut(prepared.instance_type)
        .expect("the prepared class record was authenticated");
    if let Some((index, returned)) = inferred {
        provenance.method_returns[index] = Some(returned);
    }
    if let Some((index, _, type_)) = property {
        provenance.property_types[index] = Some(type_);
    }
    provenance.completed_bodies[body_index] = true;
    Ok(())
}

pub(super) fn finish_source_class_members(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &SourceClassPlan,
    prepared: &PreparedSourceClass,
) -> Result<ClassMembers, ClassError> {
    if prepared.plan != *plan {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    let provenance = store
        .source_class_provenance(prepared.instance_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPlan(plan.declaration())))?;
    if provenance.prepared != *prepared {
        return Err(invariant(ClassInvariant::InvalidPlan(plan.declaration())));
    }
    validate_source_class_header(store, host, provenance)?;
    if !provenance.completed_bodies.iter().all(|complete| *complete)
        || provenance.method_returns.iter().any(Option::is_none)
        || provenance.property_types.iter().any(Option::is_none)
    {
        return Err(unsupported(ClassUnsupported::Member {
            node: plan.declaration(),
            kind: SyntaxKind::ClassDeclaration,
        }));
    }
    let members = provenance.members.clone();
    if !provenance.complete {
        store
            .source_class_provenance_mut(prepared.instance_type)
            .expect("the prepared class record was authenticated")
            .complete = true;
    }
    Ok(members)
}

/// Reuses checked source members without asking the legacy planner to rebuild them.
pub(super) fn completed_source_class_members(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
) -> Result<Option<ClassMembers>, ClassError> {
    let Some(provenance) = store.source_class_provenance_for_symbol(symbol) else {
        return Ok(None);
    };
    validate_source_class_header(store, host, provenance)?;
    Ok(provenance.complete.then(|| provenance.members.clone()))
}

fn completed_source_class_method_type(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
    context: &ClassTypeQueryContext,
) -> Result<Option<TypeId>, ClassError> {
    let Some(provenance) = store
        .symbol(symbol)
        .and_then(Symbol::parent)
        .and_then(|owner| store.source_class_provenance_for_symbol(owner))
    else {
        return Ok(None);
    };
    if !provenance.prepared.plan.methods.iter().any(|method| {
        method.method.symbol == symbol
            && (method.method.overload
                || matches!(
                    method.return_type,
                    Some(ClassBodyParameterType::Annotation(_))
                ))
    }) {
        return Ok(None);
    }
    validate_source_class_header(store, host, provenance)?;
    if !provenance.complete {
        return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
    }
    for (method, &(_, signature)) in provenance
        .prepared
        .plan
        .methods
        .iter()
        .zip(&provenance.prepared.methods)
        .filter(|(method, _)| method.method.symbol == symbol)
    {
        completed_source_class_method_signature_return_type(
            store,
            host,
            method.method.declaration,
            signature,
            Some(CanonicalArrayTargets::from_global_types(
                &context.global_types,
            )),
            context.options,
        )?;
    }
    store
        .value_symbol_links(symbol)
        .and_then(|links| links.resolved_type)
        .map(Some)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))
}

/// Reads a completed method's retained return after source and signature validation.
pub(super) fn completed_source_class_method_signature_return_type(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    declaration: NodeRef,
    signature: SignatureId,
    array_targets: Option<CanonicalArrayTargets>,
    options: CanonicalTypeQueryOptions,
) -> Result<TypeId, ClassError> {
    let invalid = || invariant(ClassInvariant::InvalidPropertyTypeCache(declaration));
    let record = preflight_node(store, host, declaration)?;
    if record.kind != SyntaxKind::MethodDeclaration
        || !matches!(record.data, NodeData::MethodDeclaration(_))
    {
        return Err(invalid());
    }
    let class = record
        .parent
        .map(|node| NodeRef::new(declaration.arena, declaration.file, node))
        .ok_or_else(invalid)?;
    let class_record = preflight_node(store, host, class)?;
    if class_record.kind != SyntaxKind::ClassDeclaration
        || !matches!(class_record.data, NodeData::ClassDeclaration(_))
    {
        return Err(invalid());
    }
    let method_symbol = bound_symbol(store, host, declaration).ok_or_else(invalid)?;
    let class_symbol = bound_symbol(store, host, class).ok_or_else(invalid)?;
    let provenance = store
        .source_class_provenance_for_symbol(class_symbol)
        .ok_or_else(invalid)?;
    validate_source_class_header(store, host, provenance)?;
    let prepared = &provenance.prepared;
    let plan = &prepared.plan;
    if plan.symbol() != class_symbol
        || plan.declaration() != class
        || !provenance.complete
        || plan
            .type_query_context
            .as_ref()
            .is_some_and(|context| context.options != options)
    {
        return Err(invalid());
    }
    let index = plan
        .methods
        .iter()
        .position(|method| {
            method.method.declaration == declaration && method.method.symbol == method_symbol
        })
        .ok_or_else(invalid)?;
    if prepared.methods[index].1 != signature {
        return Err(invalid());
    }
    let return_type = provenance.method_returns[index].ok_or_else(invalid)?;
    let signature_record = store.signature(signature).ok_or_else(invalid)?;
    let edges = std::iter::once(Some(return_type)).chain(signature_record.parameters().iter().map(
        |parameter| {
            store
                .value_symbol_links(*parameter)
                .and_then(|links| links.resolved_type)
        },
    ));
    for edge in edges {
        // The retained plan proves identity, but only this caller grants array access.
        store
            .validate_cached_array_capability_with_pending_functions(
                array_targets,
                edge.ok_or_else(invalid)?,
                &[],
            )
            .map_err(|_| invalid())?;
    }
    Ok(return_type)
}

/// Checks each overload against its checked implementation, in binder order.
#[allow(clippy::too_many_arguments)]
pub(super) fn check_source_class_method_overloads(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    session: &mut InstantiationSession,
    prepared: &PreparedSourceClass,
) -> Result<Vec<(NodeRef, CanonicalCheckerDiagnostic)>, SourceCheckError> {
    let mut groups = Vec::new();
    let mut diagnostics = Vec::new();
    for (method, &(type_, _)) in prepared.plan.methods.iter().zip(&prepared.methods) {
        if method.method.overload && method.method.body.is_some() {
            let overloads = source_class_method_overloads(store, type_)
                .map_err(|_| SourceCheckError::Class(method.method.declaration))?
                .ok_or(SourceCheckError::Class(method.method.declaration))?;
            groups.push((method.method.declaration, overloads));
        }
    }
    for (implementation, overloads) in groups {
        for overload in &overloads.signatures {
            let compatible = store.is_implementation_compatible_with_overload(
                &overloads.implementation,
                overload,
                global_types,
                options.strict_function_types,
                session,
            )?;
            if compatible {
                continue;
            }
            let declaration = store
                .signature(overload.signature)
                .and_then(super::signatures::Signature::declaration)
                .filter(|declaration| host.node(*declaration).is_some())
                .ok_or(SourceCheckError::Class(implementation))?;
            diagnostics.push((
                implementation,
                CanonicalCheckerDiagnostic {
                    node: Some(declaration),
                    range_override: None,
                    diagnostic: Diagnostic::new(
                        message_by_code(2394).ok_or(SourceCheckError::MissingDiagnostic(2394))?,
                    ),
                    related_information: vec![CanonicalCheckerRelatedInformation {
                        node: Some(implementation),
                        diagnostic: Diagnostic::new(
                            message_by_code(2750)
                                .ok_or(SourceCheckError::MissingDiagnostic(2750))?,
                        ),
                    }],
                },
            ));
            break;
        }
    }
    Ok(diagnostics)
}

/// Checks local members against declared or inherited class index signatures.
#[allow(clippy::too_many_lines)] // Keep property ownership, applicability, and the diagnostic together.
pub(super) fn check_class_index_constraints(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    members: &ClassMembers,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<(), SourceCheckError> {
    let invalid = || SourceCheckError::Class(members.shells.declaration);
    let indexes = store
        .type_payload(members.shells.instance_type)
        .and_then(|record| record.data().structured())
        .ok_or_else(invalid)?
        .index_infos
        .clone()
        .unwrap_or_default();
    if indexes.is_empty() {
        return Ok(());
    }
    if validate_class_heritage_members(store, members.shells.instance_type)
        != ClassHeritageMembersValidation::Valid
    {
        return Err(invalid());
    }
    let bootstrap = store.intrinsic_bootstrap().ok_or_else(invalid)?;
    let number = bootstrap.number_type;
    let undefined = bootstrap.undefined_type;
    let mut format_flags = CanonicalTypeFormatFlags::TYPE_TO_STRING_DEFAULT;
    if options.no_error_truncation {
        format_flags |= CanonicalTypeFormatFlags::NO_TRUNCATION;
    }

    for &property in members.instance_properties() {
        let record = store.symbol(property).ok_or_else(invalid)?;
        // Private identifiers and symbol keys do not match the supported string indexes.
        if record.name().is_private_identifier() || record.name().is_late_bound() {
            continue;
        }
        let name = record.name().as_utf8().ok_or_else(invalid)?.to_owned();
        let declaration = record.value_declaration().ok_or_else(invalid)?;
        let optional = record.flags().contains(SymbolFlags::OPTIONAL);
        let local_property = store.get_parent_of_symbol(property) == Some(members.shells.symbol);
        let property_record = host.node(declaration).ok_or_else(invalid)?;
        let name_node = match &property_record.data {
            NodeData::PropertyDeclaration(data) => data.name,
            NodeData::MethodDeclaration(data) => data.name,
            NodeData::GetAccessorDeclaration(data) => data.name,
            NodeData::SetAccessorDeclaration(data) => data.name,
            NodeData::ParameterDeclaration(data) => data.name,
            _ => return Err(invalid()),
        };
        let name_node = NodeRef::new(declaration.arena, declaration.file, name_node);
        let mut property_type = store
            .value_symbol_links(property)
            .and_then(|links| links.resolved_type)
            .ok_or_else(invalid)?;
        if optional
            && options.intrinsic.strict_null_checks
            && !options.intrinsic.exact_optional_property_types
        {
            let mut prepared = store
                .prepare_type_query_types(&[], &[], &[], 1, 0)
                .map_err(|_| invalid())?;
            property_type = store
                .literal_union_type_prepared(&[property_type, undefined], None, &mut prepared)
                .map_err(|_| invalid())?;
        }
        let name_type = store
            .regular_string_literal_type(name.clone())
            .map_err(|_| invalid())?;
        for &index in &indexes {
            let info = store.index_info(index).ok_or_else(invalid)?;
            let (key_type, value_type) = (info.key_type(), info.value_type());
            let index_declaration = info.declaration().ok_or_else(invalid)?;
            let local_index = bound_symbol(store, host, index_declaration)
                .and_then(|symbol| store.get_parent_of_symbol(symbol))
                == Some(members.shells.symbol);
            if !local_property && !local_index {
                continue;
            }
            let applies = if key_type == number && ts_jsnum::from_string(&name).to_string() == name
            {
                true
            } else {
                store.is_type_assignable_to_with_global_types_and_strict_function_types(
                    name_type,
                    key_type,
                    global_types,
                    options.strict_function_types,
                )?
            };
            if !applies
                || store.is_type_assignable_to_with_global_types_and_strict_function_types(
                    property_type,
                    value_type,
                    global_types,
                    options.strict_function_types,
                )?
            {
                continue;
            }
            let mut arguments = vec![name.clone()];
            for type_ in [property_type, key_type, value_type] {
                arguments.push(type_to_string_with_host_global_types_and_flags(
                    store,
                    host,
                    global_types,
                    type_,
                    format_flags,
                )?);
            }
            super::source::merge_retry_diagnostic(
                diagnostics,
                CanonicalCheckerDiagnostic {
                    node: Some(if local_property {
                        name_node
                    } else {
                        index_declaration
                    }),
                    range_override: None,
                    diagnostic: Diagnostic::with_arguments(
                        message_by_code(2411).ok_or(SourceCheckError::MissingDiagnostic(2411))?,
                        arguments,
                    ),
                    related_information: Vec::new(),
                },
            );
        }
    }
    Ok(())
}

/// Checks completed instance members before checking the static member types.
#[allow(clippy::too_many_lines)] // Both diagnostics use the same completed class and base identities.
pub(super) fn check_class_heritage_compatibility(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    diagnostics: &mut CanonicalCheckerDiagnostics,
    declaration: NodeRef,
    members: &ClassMembers,
) -> Result<(), SourceCheckError> {
    let Some(base) = members.base() else {
        return Ok(());
    };
    let source_type = members.shells().instance_type();
    let target_type = base.instance_type();
    let declared_base = store
        .direct_class_heritage_provenance(source_type)
        .is_some_and(|edge| source_constructor_heritage_is_exact(store, source_type, edge));
    for type_ in [source_type, target_type] {
        if !(declared_base && type_ == target_type)
            && validate_class_heritage_members(store, type_)
                != ClassHeritageMembersValidation::Valid
        {
            return Err(SourceCheckError::Class(declaration));
        }
        let Some(TypeData::Interface(instance)) = store.type_payload(type_).map(TypeRecord::data)
        else {
            return Err(SourceCheckError::Class(declaration));
        };
        // Generic heritage needs the derived class's instantiated this argument.
        if instance
            .all_type_parameters
            .as_ref()
            .is_some_and(|parameters| parameters.len() > 1)
        {
            return Ok(());
        }
    }
    let Some(NodeData::ClassDeclaration(class)) = host.node(declaration).map(|record| &record.data)
    else {
        return Err(SourceCheckError::Class(declaration));
    };
    let name = class.name.map_or(declaration, |name| {
        NodeRef::new(declaration.arena, declaration.file, name)
    });
    let mut flags = CanonicalTypeFormatFlags::TYPE_TO_STRING_DEFAULT;
    if options.no_error_truncation {
        flags |= CanonicalTypeFormatFlags::NO_TRUNCATION;
    }
    let target_members = store
        .type_payload(target_type)
        .and_then(|record| record.data().structured())
        .ok_or(SourceCheckError::Class(declaration))?
        .clone();
    let mut issued_member_error = false;
    let mut visibility_error: Option<(usize, String)> = None;
    for &property in members.declared_instance_properties() {
        let own = class_heritage_property(store, property, declaration)?;
        let Some(base_property) = target_members
            .members
            .and_then(|members| store.symbol_table(members))
            .and_then(|table| table.get(own.name.as_ref()))
        else {
            continue;
        };
        if property == base_property {
            continue;
        }
        let mut inherited = class_heritage_property(store, base_property, declaration)?;
        if !declared_base {
            let view = prepare_class_instance_super_view(store, host, members.shells.symbol, None)
                .map_err(|_| SourceCheckError::Class(declaration))?;
            inherited.type_ = prepare_class_instance_super_member_type(
                store,
                host,
                Some(global_types),
                view,
                base_property,
            )
            .map_err(|_| SourceCheckError::Class(declaration))?;
        }
        let names = get_type_names_for_assignability_error_with_host_global_types_and_flags(
            store,
            host,
            global_types,
            source_type,
            target_type,
            flags,
        )?;
        let property_name = own
            .name
            .as_utf8()
            .ok_or(SourceCheckError::Class(declaration))?;
        if !store.is_type_assignable_to_with_global_types_and_strict_function_types(
            own.type_,
            inherited.type_,
            global_types,
            options.strict_function_types,
        )? {
            let own_name = match host.node(own.declaration).map(|record| &record.data) {
                Some(NodeData::MethodDeclaration(member)) => Some(member.name),
                Some(NodeData::PropertyDeclaration(member)) => Some(member.name),
                Some(NodeData::ParameterDeclaration(member)) => Some(member.name),
                Some(NodeData::GetAccessorDeclaration(member)) => Some(member.name),
                Some(NodeData::SetAccessorDeclaration(member)) => Some(member.name),
                _ => None,
            }
            .map_or(own.declaration, |name| {
                NodeRef::new(own.declaration.arena, own.declaration.file, name)
            });
            let detail = class_heritage_type_mismatch(
                store,
                host,
                global_types,
                options,
                own.type_,
                inherited.type_,
                flags,
            )?;
            let mut diagnostic = Diagnostic::with_arguments(
                message_by_code(2416).ok_or(SourceCheckError::MissingDiagnostic(2416))?,
                [property_name.to_owned(), names.source, names.target],
            );
            diagnostic.details = detail.lines().map(|line| format!("  {line}")).collect();
            diagnostics.lookup_or_issue(Some(own_name), diagnostic);
            issued_member_error = true;
            continue;
        }
        let source = class_heritage_diagnostic_type(store, source_type);
        let target = class_heritage_diagnostic_type(store, target_type);
        let mut detail = property_visibility_mismatch_detail(
            store,
            host,
            global_types,
            source,
            target,
            &own,
            &inherited,
            flags,
            1,
        )?;
        if detail.is_none() && own.optional && !inherited.optional {
            detail = Some(format!(
                "  {}",
                Diagnostic::with_arguments(
                    message_by_code(2327).ok_or(SourceCheckError::MissingDiagnostic(2327))?,
                    [property_name.to_owned(), names.source, names.target],
                )
                .render()
                .map_err(|_| SourceCheckError::MissingDiagnostic(2327))?
            ));
        }
        if let Some(detail) = detail {
            let index = target_members
                .properties
                .as_deref()
                .unwrap_or_default()
                .iter()
                .position(|property| *property == base_property)
                .ok_or(SourceCheckError::Class(declaration))?;
            if visibility_error
                .as_ref()
                .is_none_or(|(first, _)| index < *first)
            {
                visibility_error = Some((index, detail));
            }
        }
    }
    if issued_member_error {
        return Ok(());
    }
    if let Some((_, detail)) = visibility_error {
        let names = get_type_names_for_assignability_error_with_host_global_types_and_flags(
            store,
            host,
            global_types,
            source_type,
            target_type,
            flags,
        )?;
        let mut diagnostic = Diagnostic::with_arguments(
            message_by_code(2415).ok_or(SourceCheckError::MissingDiagnostic(2415))?,
            [names.source, names.target],
        );
        diagnostic.details.push(detail);
        diagnostics.lookup_or_issue(Some(name), diagnostic);
        return Ok(());
    }

    // The static base loses its construct signatures in Go. Compare its actual
    // members here, excluding prototype, without comparing constructor parameters.
    let inherited = store
        .type_payload(base.value_type())
        .and_then(|record| record.data().structured())
        .map(|structured| structured.properties.clone().unwrap_or_default())
        .ok_or(SourceCheckError::Class(declaration))?;
    for property in inherited {
        let target = store
            .symbol(property)
            .ok_or(SourceCheckError::Class(declaration))?;
        if target.flags().contains(SymbolFlags::PROTOTYPE)
            || declared_base && target.name().as_utf8() == Some(PROTOTYPE_NAME)
        {
            continue;
        }
        let property_name = target.name().to_owned();
        let source_property = store
            .symbol_table(members.static_members())
            .and_then(|table| table.get(property_name.as_ref()))
            .ok_or(SourceCheckError::Class(declaration))?;
        if source_property == property {
            continue;
        }
        let source = class_heritage_property(store, source_property, declaration)?.type_;
        let target = class_heritage_property(store, property, declaration)?.type_;
        if store.is_type_assignable_to_with_global_types_and_strict_function_types(
            source,
            target,
            global_types,
            options.strict_function_types,
        )? {
            continue;
        }
        let names = get_type_names_for_assignability_error_with_host_global_types_and_flags(
            store,
            host,
            global_types,
            members.shells().value_type(),
            base.value_type(),
            flags,
        )?;
        let property_name = property_name
            .as_utf8()
            .ok_or(SourceCheckError::Class(declaration))?;
        let property_detail = Diagnostic::with_arguments(
            message_by_code(2326).ok_or(SourceCheckError::MissingDiagnostic(2326))?,
            [property_name],
        )
        .render()
        .map_err(|_| SourceCheckError::MissingDiagnostic(2326))?;
        let detail = class_heritage_type_mismatch(
            store,
            host,
            global_types,
            options,
            source,
            target,
            flags,
        )?;
        let mut diagnostic = Diagnostic::with_arguments(
            message_by_code(2417).ok_or(SourceCheckError::MissingDiagnostic(2417))?,
            [names.source, names.target],
        );
        diagnostic.details.push(format!("  {property_detail}"));
        diagnostic
            .details
            .extend(detail.lines().map(|line| format!("    {line}")));
        diagnostics.lookup_or_issue(Some(name), diagnostic);
        break;
    }
    Ok(())
}

/// Checks each implemented interface against the completed class instance.
#[allow(clippy::too_many_arguments, clippy::too_many_lines)] // Keep the source, query session, and diagnostic order together.
pub(super) fn check_class_implementation_compatibility(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    diagnostics: &mut CanonicalCheckerDiagnostics,
    session: &mut InstantiationSession,
    declaration: NodeRef,
    members: &ClassMembers,
) -> Result<(), SourceCheckError> {
    let Some(NodeData::ClassDeclaration(class)) = host.node(declaration).map(|record| &record.data)
    else {
        return Err(SourceCheckError::Class(declaration));
    };
    if class.heritage_clauses.as_ref().is_none_or(|clauses| {
        !clauses.nodes.iter().any(|clause| {
            let clause = NodeRef::new(declaration.arena, declaration.file, *clause);
            matches!(host.node(clause).map(|record| &record.data),
                Some(NodeData::HeritageClause(heritage))
                    if heritage.token == SyntaxKind::ImplementsKeyword)
        })
    }) {
        return Ok(());
    }
    let header = plan_class_declaration_header(store, host, members.shells.symbol, true)
        .map_err(|_| SourceCheckError::Class(declaration))?;
    let source_type = members.shells.instance_type;
    if header.declaration != declaration
        || header.base.as_ref().map(|base| base.symbol) != members.base.map(|base| base.symbol)
        || validate_class_heritage_members(store, source_type)
            != ClassHeritageMembersValidation::Valid
    {
        return Err(SourceCheckError::Class(declaration));
    }
    let name = class.name.map_or(declaration, |name| {
        NodeRef::new(declaration.arena, declaration.file, name)
    });
    let mut flags = CanonicalTypeFormatFlags::TYPE_TO_STRING_DEFAULT;
    if options.no_error_truncation {
        flags |= CanonicalTypeFormatFlags::NO_TRUNCATION;
    }
    for implementation in header.implementations {
        // The existing class-target path admits only empty instance types.
        if store
            .symbol(implementation.symbol)
            .is_some_and(|symbol| symbol.flags() == SymbolFlags::CLASS)
        {
            continue;
        }
        let target_type = CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_declared_type_of_symbol(implementation.symbol)?;
        if store.type_payload(target_type).and_then(TypeRecord::symbol)
            != Some(implementation.symbol)
        {
            return Err(SourceCheckError::Class(implementation.expression));
        }
        if let Some(method) = &implementation.method {
            let method_type = CanonicalTypeQuery::new_with_global_types_and_session(
                store,
                host,
                global_types,
                options,
                session,
                diagnostics,
            )?
            .get_type_of_interface_method(method.symbol)?;
            let symbol = store
                .symbol(method.symbol)
                .ok_or(SourceCheckError::Class(implementation.expression))?;
            let member = store
                .symbol(implementation.symbol)
                .and_then(Symbol::members)
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get(symbol.name()));
            if member != Some(method.symbol)
                || symbol.name().as_utf8() != Some(method.name.as_str())
                || symbol.parent() != Some(implementation.symbol)
                || store.type_payload(method_type).and_then(TypeRecord::symbol)
                    != Some(method.symbol)
            {
                return Err(SourceCheckError::Class(implementation.expression));
            }
            let StoredCallableSetValidation::Valid { projection, .. } =
                validate_stored_callable_set(store, method_type)
            else {
                return Err(SourceCheckError::Class(implementation.expression));
            };
            if projection.call_signatures.is_empty() || !projection.construct_signatures.is_empty()
            {
                return Err(SourceCheckError::Class(implementation.expression));
            }
            for signature in projection
                .call_signatures
                .iter()
                .map(|callable| callable.signature)
            {
                CanonicalTypeQuery::new_with_global_types_and_session(
                    store,
                    host,
                    global_types,
                    options,
                    session,
                    diagnostics,
                )?
                .get_return_type_of_signature(signature)?;
            }
        }
        if store.is_type_assignable_to_with_session(
            source_type,
            target_type,
            Some(global_types),
            Some(options.strict_function_types),
            session,
        )? {
            continue;
        }
        let target_members = store
            .resolved_declared_property_object_with_global_types(host, target_type, global_types)?
            .ok_or(SourceCheckError::Class(implementation.expression))?;
        let source_properties = members
            .instance_properties()
            .iter()
            .map(|&property| class_heritage_property(store, property, declaration))
            .collect::<Result<Vec<_>, _>>()?;
        // Optional-property errors need their effective read types in the message.
        if options.intrinsic.strict_null_checks
            && source_properties
                .iter()
                .chain(target_members.properties())
                .any(|property| property.optional)
        {
            return Err(SourceCheckError::Class(implementation.expression));
        }
        let names = get_type_names_for_assignability_error_with_host_global_types_and_flags(
            store,
            host,
            global_types,
            source_type,
            target_type,
            flags,
        )?;
        let mut issued_member_error = false;
        for &member in &class.members.nodes {
            let member = NodeRef::new(declaration.arena, declaration.file, member);
            let Some(symbol) = bound_symbol(store, host, member) else {
                continue;
            };
            let Some(own) = source_properties
                .iter()
                .find(|property| property.symbol == symbol)
            else {
                continue;
            };
            let Some(target) = target_members
                .properties()
                .iter()
                .find(|target| target.name == own.name)
            else {
                continue;
            };
            if store.is_type_assignable_to_with_session(
                own.type_,
                target.type_,
                Some(global_types),
                Some(options.strict_function_types),
                session,
            )? {
                continue;
            }
            let own_name = match host.node(member).map(|record| &record.data) {
                Some(NodeData::PropertyDeclaration(member)) => member.name,
                Some(NodeData::MethodDeclaration(member)) => member.name,
                Some(NodeData::GetAccessorDeclaration(member)) => member.name,
                Some(NodeData::SetAccessorDeclaration(member)) => member.name,
                _ => return Err(SourceCheckError::Class(member)),
            };
            let own_name = NodeRef::new(member.arena, member.file, own_name);
            let property_name = own
                .name
                .as_utf8()
                .ok_or(SourceCheckError::Class(own.declaration))?;
            let detail = class_heritage_type_mismatch(
                store,
                host,
                global_types,
                options,
                own.type_,
                target.type_,
                flags,
            )?;
            let mut diagnostic = Diagnostic::with_arguments(
                message_by_code(2416).ok_or(SourceCheckError::MissingDiagnostic(2416))?,
                [
                    property_name.to_owned(),
                    names.source.clone(),
                    names.target.clone(),
                ],
            );
            diagnostic.details = detail.lines().map(|line| format!("  {line}")).collect();
            diagnostics.lookup_or_issue(Some(own_name), diagnostic);
            issued_member_error = true;
        }
        if issued_member_error {
            continue;
        }
        let detail_source = class_heritage_diagnostic_type(store, source_type);
        let missing = target_members
            .properties()
            .iter()
            .filter(|target| {
                !target.optional
                    && !source_properties
                        .iter()
                        .any(|source| source.name == target.name)
            })
            .collect::<Vec<_>>();
        let mut diagnostic = CanonicalCheckerDiagnostic {
            node: Some(name),
            range_override: None,
            diagnostic: Diagnostic::with_arguments(
                message_by_code(2420).ok_or(SourceCheckError::MissingDiagnostic(2420))?,
                [names.source, names.target],
            ),
            related_information: Vec::new(),
        };
        if missing.is_empty() {
            diagnostic.diagnostic.details = declared_property_mismatch_details(
                store,
                host,
                global_types,
                detail_source,
                target_type,
                flags,
                options,
            )?;
            if diagnostic.diagnostic.details.is_empty() {
                return Err(SourceCheckError::Class(implementation.expression));
            }
        } else {
            let missing = missing_property_diagnostic(
                store,
                host,
                global_types,
                detail_source,
                target_type,
                name,
                &missing,
                flags,
            )?;
            diagnostic.diagnostic.details = missing
                .diagnostic
                .render()
                .map_err(|_| SourceCheckError::Class(implementation.expression))?
                .lines()
                .map(|line| format!("  {line}"))
                .collect();
            diagnostic.related_information = missing.related_information;
        }
        super::source::merge_retry_diagnostic(diagnostics, diagnostic);
    }
    Ok(())
}

fn class_heritage_property(
    store: &CanonicalTypeMapperStore,
    property: SemanticSymbolId,
    declaration: NodeRef,
) -> Result<ResolvedDeclaredProperty, SourceCheckError> {
    let symbol = store
        .symbol(property)
        .ok_or(SourceCheckError::Class(declaration))?;
    Ok(ResolvedDeclaredProperty {
        symbol: property,
        name: symbol.name().to_owned(),
        type_: store
            .value_symbol_links(property)
            .and_then(|links| links.resolved_type)
            .ok_or(SourceCheckError::Class(declaration))?,
        optional: symbol.flags().contains(SymbolFlags::OPTIONAL),
        declaration: symbol
            .value_declaration()
            .ok_or(SourceCheckError::Class(declaration))?,
    })
}

// Go reduces classes with no declared instance members to their single base
// during relation checks, but keeps the original names in the main message.
fn class_heritage_diagnostic_type(store: &CanonicalTypeMapperStore, mut type_: TypeId) -> TypeId {
    let mut visited = HashSet::new();
    while visited.insert(type_) {
        let Some(base) = store.direct_class_heritage_provenance(type_) else {
            break;
        };
        let has_members = store
            .type_payload(type_)
            .and_then(TypeRecord::symbol)
            .and_then(|symbol| store.symbol(symbol))
            .and_then(Symbol::members)
            .and_then(|members| store.symbol_table(members))
            .is_some_and(|members| !members.is_empty());
        if has_members {
            break;
        }
        type_ = base.base_instance_type;
    }
    type_
}

fn class_heritage_type_mismatch(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    source: TypeId,
    target: TypeId,
    flags: CanonicalTypeFormatFlags,
) -> Result<String, SourceCheckError> {
    let names = get_type_names_for_assignability_error_with_host_global_types_and_flags(
        store,
        host,
        global_types,
        source,
        target,
        flags,
    )?;
    let mut diagnostic = Diagnostic::with_arguments(
        message_by_code(2322).ok_or(SourceCheckError::MissingDiagnostic(2322))?,
        [names.source, names.target],
    );
    diagnostic.details = declared_property_mismatch_details(
        store,
        host,
        global_types,
        source,
        target,
        flags,
        options,
    )?;
    if diagnostic.details.is_empty() {
        diagnostic.details = callable_assignability_details(
            store,
            host,
            global_types,
            source,
            target,
            flags,
            options,
        )?;
    }
    diagnostic
        .render()
        .map_err(|_| SourceCheckError::MissingDiagnostic(2322))
}

pub(super) fn class_member_source(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    member: SemanticSymbolId,
) -> Result<ClassMemberSource, ClassError> {
    let record = store
        .symbol(member)
        .ok_or_else(|| invariant(ClassInvariant::SymbolNotOwned(member)))?;
    let class = store
        .get_parent_of_symbol(member)
        .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(member)))?;
    let instance = store
        .declared_type_links(class)
        .and_then(|links| links.declared_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(class)))?;
    if store.symbol(class).is_some_and(|owner| {
        owner.flags().contains(SymbolFlags::INTERFACE)
            && !owner.flags().contains(SymbolFlags::CLASS)
    }) {
        let declaration = record
            .value_declaration()
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(member)))?;
        let plan = plan_interface(store, host, class)
            .map_err(|error| constructor_base_member_error(declaration, error))?;
        if !interface_state(store, &plan, instance)
            .map_err(|error| constructor_base_member_error(plan.node, error))?
            .is_resolved()
        {
            return Err(invariant(ClassInvariant::InvalidInstanceMembers(class)));
        }
        let property = plan
            .properties
            .iter()
            .find(|property| property.symbol == member)
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(member)))?;
        if plan
            .accessors
            .iter()
            .any(|accessor| accessor.symbol == member)
        {
            return Err(unsupported(ClassUnsupported::Member {
                node: property.declaration,
                kind: SyntaxKind::MethodDeclaration,
            }));
        }
        return Ok(ClassMemberSource {
            symbol: member,
            declaring_class: class,
            declaration: property.declaration,
            origin: if plan.methods.iter().any(|method| method.symbol == member) {
                ClassMemberOrigin::Method
            } else {
                ClassMemberOrigin::DeclaredProperty
            },
            side: if plan
                .call_signatures
                .iter()
                .any(|signature| signature.is_construct())
            {
                ClassPropertySide::Static
            } else {
                ClassPropertySide::Instance
            },
            visibility: ClassConstructorVisibility::Public,
            readonly: record.check_flags().contains(CheckFlags::READONLY),
            abstract_: false,
        });
    }
    if let Some(provenance) = store.source_class_provenance_for_symbol(class) {
        validate_source_class_header(store, host, provenance)?;
        return provenance
            .prepared
            .plan
            .sources
            .iter()
            .find(|source| source.symbol == member)
            .cloned()
            .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(member)));
    }
    if validate_class_heritage_members(store, instance) != ClassHeritageMembersValidation::Valid {
        return Err(invariant(ClassInvariant::InvalidInstanceMembers(class)));
    }
    let declaration = record
        .value_declaration()
        .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(member)))?;
    let node = preflight_node(store, host, declaration)?;
    let (arena, _) = host
        .source(declaration)
        .ok_or_else(|| invariant(ClassInvariant::InvalidDeclaration(declaration)))?;
    let origin = match &node.data {
        NodeData::MethodDeclaration(_) => ClassMemberOrigin::Method,
        NodeData::ParameterDeclaration(_) => ClassMemberOrigin::ParameterProperty {
            parameter: declaration,
        },
        NodeData::PropertyDeclaration(property) => {
            let initializer = property
                .initializer
                .map(|node| NodeRef::new(declaration.arena, declaration.file, node));
            if ts_binder::canonical_has_syntactic_modifier(
                arena,
                declaration.node,
                SyntaxKind::AccessorKeyword,
            ) {
                ClassMemberOrigin::AutoAccessor { initializer }
            } else {
                ClassMemberOrigin::Field { initializer }
            }
        }
        NodeData::GetAccessorDeclaration(_) | NodeData::SetAccessorDeclaration(_) => {
            ClassMemberOrigin::Accessor
        }
        NodeData::BinaryExpression(_) => ClassMemberOrigin::JavaScriptAssignment {
            assignment: declaration,
        },
        _ => {
            return Err(unsupported(ClassUnsupported::Member {
                node: declaration,
                kind: node.kind,
            }));
        }
    };
    let is_static = store
        .symbol(class)
        .and_then(Symbol::exports)
        .and_then(|table| store.symbol_table(table))
        .and_then(|table| table.get(record.name()))
        == Some(member);
    Ok(ClassMemberSource {
        symbol: member,
        declaring_class: class,
        declaration,
        origin,
        side: if is_static {
            ClassPropertySide::Static
        } else {
            ClassPropertySide::Instance
        },
        visibility: if record.name().is_private_identifier() {
            ClassConstructorVisibility::Private
        } else {
            class_member_visibility(store, declaration)
        },
        readonly: record.check_flags().contains(CheckFlags::READONLY),
        abstract_: ts_binder::canonical_has_syntactic_modifier(
            arena,
            declaration.node,
            SyntaxKind::AbstractKeyword,
        ),
    })
}

fn source_class_callable_projection(
    store: &CanonicalTypeMapperStore,
    owner: TypeId,
    signature: SignatureId,
    owner_symbol: SemanticSymbolId,
) -> Result<ValidatedSingleCallable, ClassError> {
    let record = store
        .signature(signature)
        .ok_or_else(|| invariant(ClassInvariant::InvalidValueCache(owner_symbol)))?;
    let parameters = record
        .parameters()
        .iter()
        .map(|symbol| {
            store
                .value_symbol_links(*symbol)
                .and_then(|links| links.resolved_type)
                .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(*symbol)))
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(ValidatedSingleCallable {
        owner,
        signature,
        parameters,
        rest_parameter: None,
        min_argument_count: usize::try_from(record.min_argument_count())
            .map_err(|_| invariant(ClassInvariant::InvalidValueCache(owner_symbol)))?,
        return_type: record.resolved_return_type(),
        strict_variance_exempt: true,
    })
}

/// Reads the separate overload and implementation signatures from the class receipt.
pub(super) fn source_class_method_overloads(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
) -> Result<Option<SourceClassMethodOverloads>, ClassError> {
    let Some(symbol) = store.type_payload(type_).and_then(TypeRecord::symbol) else {
        return Ok(None);
    };
    let Some(provenance) = store
        .symbol(symbol)
        .and_then(Symbol::parent)
        .and_then(|owner| store.source_class_provenance_for_symbol(owner))
    else {
        return Ok(None);
    };
    let methods = provenance
        .prepared
        .plan
        .methods
        .iter()
        .zip(&provenance.prepared.methods)
        .filter(|(method, _)| method.method.symbol == symbol)
        .collect::<Vec<_>>();
    if !methods.iter().any(|(method, _)| method.method.overload) {
        return Ok(None);
    }
    validate_source_class_stored_header(store, provenance)?;
    let mut signatures = Vec::new();
    let mut implementation = None;
    for (method, &(owner, signature)) in methods {
        if owner != type_ || !method.method.overload {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
        }
        let callable = source_class_callable_projection(store, owner, signature, symbol)?;
        if method.method.body.is_some() {
            if implementation.replace(callable).is_some() {
                return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
            }
        } else {
            signatures.push(callable);
        }
    }
    if signatures.is_empty() {
        return Err(invariant(ClassInvariant::InvalidPropertyValueCache(symbol)));
    }
    let implementation = implementation
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))?;
    Ok(Some(SourceClassMethodOverloads {
        signatures,
        implementation,
    }))
}

fn source_constructor_call_parameter(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
) -> Result<(NodeRef, TypeId, bool), ClassError> {
    let record = store
        .symbol(symbol)
        .ok_or_else(|| invariant(ClassInvariant::SymbolNotOwned(symbol)))?;
    let declaration = record
        .value_declaration()
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))?;
    let node = preflight_node(store, host, declaration)?;
    let NodeData::ParameterDeclaration(parameter) = &node.data else {
        return Err(invariant(ClassInvariant::InvalidPropertySymbol(
            declaration,
        )));
    };
    let type_ = store
        .value_symbol_links(symbol)
        .and_then(|links| links.resolved_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(symbol)))?;
    Ok((
        declaration,
        type_,
        parameter.initializer.is_some() || parameter.question_token.is_some(),
    ))
}

/// Reads the call type after the caller validates the complete constructor graph.
/// A default value permits undefined at calls but does not widen the body symbol.
pub(super) fn class_constructor_call_parameter_type(
    store: &CanonicalTypeMapperStore,
    owner: SemanticSymbolId,
    parameter: SemanticSymbolId,
    body_type: TypeId,
) -> Result<Option<TypeId>, ClassError> {
    let declaration = store
        .symbol(parameter)
        .and_then(Symbol::value_declaration)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(parameter)))?;
    let mut owner = owner;
    let mut visited = HashSet::new();
    while visited.insert(owner) {
        let Some(provenance) = store.source_class_provenance_for_symbol(owner) else {
            break;
        };
        if let Some(retained) = provenance
            .prepared
            .plan
            .bodies
            .iter()
            .filter(|body| body.kind == ClassBodyKind::Constructor)
            .flat_map(|body| &body.parameters)
            .find(|candidate| candidate.symbol == parameter && candidate.declaration == declaration)
        {
            return optional_constructor_parameter_type(
                store,
                body_type,
                retained.optional || retained.initializer.is_some(),
                declaration,
            );
        }
        let Some(base) = provenance.base_members.as_ref() else {
            break;
        };
        if let SourceClassBaseMembers::Constructor(base) = base {
            return Ok(base.signatures.iter().find_map(|callable| {
                store
                    .signature(callable.signature)?
                    .parameters()
                    .iter()
                    .position(|symbol| *symbol == parameter)
                    .map(|index| callable.parameters[index])
            }));
        }
        owner = base.identities().symbol;
    }
    let (_, initializer) = stored_constructor_parameter_annotation(store, declaration)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(parameter)))?;
    optional_constructor_parameter_type(
        store,
        body_type,
        initializer.is_some() || stored_constructor_parameter_is_optional(store, declaration),
        declaration,
    )
}

fn prepare_source_constructor_call_types(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &SourceClassPlan,
    base: Option<&SourceClassBaseMembers>,
) -> Result<(), ClassError> {
    for constructor in plan.constructor.iter().chain(&plan.constructor_overloads) {
        for parameter in &constructor.parameters {
            let annotation_type = parameter.type_.materialize(store, host)?;
            prepare_constructor_optional_type(
                store,
                annotation_type,
                parameter.optional || parameter.initializer.is_some(),
                parameter.declaration,
            )?;
        }
    }
    if let Some(SourceClassBaseMembers::Class(base)) = base {
        let parameters = store
            .signature(base.default_construct_signature)
            .ok_or_else(|| {
                invariant(ClassInvariant::InvalidConstructSignature(
                    base.shells.symbol,
                ))
            })?
            .parameters()
            .to_vec();
        for symbol in parameters {
            let (declaration, type_, optional) =
                source_constructor_call_parameter(store, host, symbol)?;
            prepare_constructor_optional_type(store, type_, optional, declaration)?;
        }
    }
    Ok(())
}

pub(super) fn class_body_super_constructor_callable(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    access: &ClassBodyAccessToken,
) -> Result<ClassBodyCallable, ClassError> {
    let (provenance, body_index) = source_class_access(store, host, access)?;
    if provenance.prepared.plan.bodies[body_index].kind != ClassBodyKind::Constructor {
        return Err(unsupported(ClassUnsupported::Member {
            node: access.declaration,
            kind: SyntaxKind::SuperKeyword,
        }));
    }
    let base = provenance
        .base_members
        .as_ref()
        .ok_or_else(|| unsupported(ClassUnsupported::Heritage(access.class_declaration)))?;
    if let SourceClassBaseMembers::Constructor(base) = base {
        let callable = base.signatures[0].clone();
        let declaration = store
            .signature(callable.signature)
            .and_then(super::signatures::Signature::declaration);
        return Ok(ClassBodyCallable {
            kind: SignatureKind::Construct,
            class_symbol: base.identities.symbol,
            declaration,
            callable,
            overloads: None,
            constructor_base: Some((**base).clone()),
            pending_return_body: None,
        });
    }
    let SourceClassBaseMembers::Class(base) = base else {
        unreachable!()
    };
    let mut callable = source_class_callable_projection(
        store,
        base.shells.value_type,
        base.default_construct_signature,
        base.shells.symbol,
    )?;
    callable.parameters = store
        .signature(base.default_construct_signature)
        .ok_or_else(|| {
            invariant(ClassInvariant::InvalidConstructSignature(
                base.shells.symbol,
            ))
        })?
        .parameters()
        .iter()
        .map(|&symbol| {
            let (declaration, type_, optional) =
                source_constructor_call_parameter(store, host, symbol)?;
            optional_constructor_parameter_type(store, type_, optional, declaration)?.ok_or_else(
                || {
                    unsupported(ClassUnsupported::PropertyType {
                        node: declaration,
                        kind: SyntaxKind::Parameter,
                    })
                },
            )
        })
        .collect::<Result<Vec<_>, ClassError>>()?;
    let declaration = store
        .signature(callable.signature)
        .and_then(super::signatures::Signature::declaration);
    if callable.return_type != Some(base.shells.instance_type)
        || declaration.is_some_and(|declaration| {
            class_member_visibility(store, declaration) == ClassConstructorVisibility::Private
        })
    {
        return Err(unsupported(ClassUnsupported::Heritage(
            access.class_declaration,
        )));
    }
    Ok(ClassBodyCallable {
        kind: SignatureKind::Construct,
        class_symbol: base.shells.symbol,
        declaration,
        callable,
        overloads: None,
        constructor_base: None,
        pending_return_body: None,
    })
}

/// A body token proves the target. Only the current caller grants Array access.
pub(super) fn class_body_method_callable_with_query_context(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    access: &ClassBodyAccessToken,
    receiver_type: TypeId,
    member: SemanticSymbolId,
    context: &ClassTypeQueryContext,
) -> Result<ClassBodyCallable, ClassError> {
    let target = class_body_method_callable(store, host, access, receiver_type, member)?;
    let invalid = || invariant(ClassInvariant::InvalidPropertyValueCache(member));
    if let Some(origin) = store.source_class_provenance_for_symbol(target.class_symbol) {
        validate_source_class_header(store, host, origin)?;
        if origin
            .prepared
            .plan
            .type_query_context
            .as_ref()
            .is_some_and(|retained| retained.options != context.options)
        {
            return Err(invalid());
        }
    }
    let targets = Some(CanonicalArrayTargets::from_global_types(
        &context.global_types,
    ));
    let single = target.overloads.is_none().then_some(&target.callable);
    for callable in single
        .into_iter()
        .chain(target.overloads.iter().flat_map(|overloads| {
            overloads
                .signatures
                .iter()
                .chain(std::iter::once(&overloads.implementation))
        }))
    {
        for edge in callable
            .parameters
            .iter()
            .copied()
            .chain(callable.rest_parameter)
            .chain(callable.return_type)
        {
            store
                .validate_cached_array_capability_with_pending_functions(targets, edge, &[])
                .map_err(|_| invalid())?;
        }
    }
    Ok(target)
}

pub(super) fn class_body_method_callable(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    access: &ClassBodyAccessToken,
    receiver_type: TypeId,
    member: SemanticSymbolId,
) -> Result<ClassBodyCallable, ClassError> {
    let (provenance, _) = source_class_access(store, host, access)?;
    if store.class_instance_super_view(receiver_type).is_some() {
        let view = validate_class_instance_super_view(
            store,
            host,
            access.class_symbol,
            Some(access),
            receiver_type,
        )?;
        let member_value = validated_class_instance_super_member(store, host, view, member)?;
        let source = class_member_source(store, host, member)?;
        let callable = member_value.callable.ok_or_else(|| {
            unsupported(ClassUnsupported::Member {
                node: source.declaration,
                kind: SyntaxKind::MethodDeclaration,
            })
        })?;
        return Ok(ClassBodyCallable {
            kind: SignatureKind::Call,
            class_symbol: source.declaring_class,
            declaration: Some(source.declaration),
            callable,
            overloads: None,
            constructor_base: None,
            pending_return_body: None,
        });
    }
    let receiver = if receiver_type == provenance.this_type {
        access.instance_type
    } else {
        receiver_type
    };
    let side = if receiver == access.instance_type
        || provenance
            .members
            .base
            .is_some_and(|base| receiver == base.instance_type)
    {
        ClassPropertySide::Instance
    } else if receiver == access.value_type
        || provenance
            .members
            .base
            .is_some_and(|base| receiver == base.value_type)
    {
        ClassPropertySide::Static
    } else {
        return Err(invariant(ClassInvariant::InvalidPlan(access.declaration)));
    };
    let source = class_member_source(store, host, member)?;
    if source.origin != ClassMemberOrigin::Method || source.side != side {
        return Err(unsupported(ClassUnsupported::Member {
            node: source.declaration,
            kind: SyntaxKind::MethodDeclaration,
        }));
    }
    let record = store
        .symbol(member)
        .ok_or_else(|| invariant(ClassInvariant::SymbolNotOwned(member)))?;
    let members = store
        .type_payload(receiver)
        .and_then(|record| match record.data() {
            TypeData::Interface(data) => data.reference.object.structured.members,
            TypeData::Object(data) => data.structured.members,
            _ => None,
        })
        .and_then(|members| store.symbol_table(members));
    if members.and_then(|members| members.get(record.name())) != Some(member) {
        return Err(invariant(ClassInvariant::InvalidPropertySymbol(
            source.declaration,
        )));
    }
    let owner = store
        .value_symbol_links(member)
        .and_then(|links| links.resolved_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(member)))?;
    if let Some(overloads) = source_class_method_overloads(store, owner)? {
        return Ok(ClassBodyCallable {
            kind: SignatureKind::Call,
            class_symbol: source.declaring_class,
            declaration: Some(source.declaration),
            callable: overloads.signatures[0].clone(),
            overloads: Some(overloads),
            constructor_base: None,
            pending_return_body: None,
        });
    }
    let signature = store
        .signature_links(source.declaration)
        .and_then(|links| links.resolved_signature.signature())
        .ok_or_else(|| invariant(ClassInvariant::InvalidPropertyValueCache(member)))?;
    let class_instance = store
        .declared_type_links(source.declaring_class)
        .and_then(|links| links.declared_type)
        .ok_or_else(|| invariant(ClassInvariant::InvalidOwnerSymbol(source.declaring_class)))?;
    let pending_return_body = if let Some(origin) = store.source_class_provenance(class_instance) {
        let method_index = origin
            .prepared
            .plan
            .methods
            .iter()
            .position(|method| method.method.symbol == member)
            .ok_or_else(|| invariant(ClassInvariant::InvalidPropertySymbol(source.declaration)))?;
        if origin.prepared.methods[method_index] != (owner, signature) {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
        }
        if origin.prepared.plan.methods[method_index]
            .method
            .return_type_node
            .is_none()
            && origin.method_returns[method_index].is_none()
        {
            origin.prepared.plan.methods[method_index].method.body
        } else {
            None
        }
    } else {
        None
    };
    let callable = if store.source_class_provenance(class_instance).is_some() {
        source_class_callable_projection(store, owner, signature, member)?
    } else {
        let StoredCallableSetValidation::Valid { projection, .. } =
            validate_stored_callable_set(store, owner)
        else {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
        };
        let [callable] = projection.call_signatures.as_ref() else {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
        };
        if !projection.construct_signatures.is_empty() || callable.signature != signature {
            return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
        }
        callable.clone()
    };
    if callable.return_type.is_none() != pending_return_body.is_some() {
        return Err(invariant(ClassInvariant::InvalidPropertyValueCache(member)));
    }
    Ok(ClassBodyCallable {
        kind: SignatureKind::Call,
        class_symbol: source.declaring_class,
        declaration: Some(source.declaration),
        callable,
        overloads: None,
        constructor_base: None,
        pending_return_body,
    })
}

/// Reads visibility only after the caller validates the declaration's class graph.
pub(super) fn class_member_visibility(
    store: &CanonicalTypeMapperStore,
    declaration: NodeRef,
) -> ClassConstructorVisibility {
    for index in 0..declaration.node.index() {
        let index = u32::try_from(index).expect("source node indices fit in u32");
        let modifier = NodeRef::new(
            declaration.arena,
            declaration.file,
            ts_ast::NodeId::new(index),
        );
        if store.source_node_parent(modifier) != Some(SourceNodeParent::Parent(declaration)) {
            continue;
        }
        match store.source_node_kind(modifier) {
            Some(SyntaxKind::PrivateKeyword) => return ClassConstructorVisibility::Private,
            Some(SyntaxKind::ProtectedKeyword) => return ClassConstructorVisibility::Protected,
            _ => {}
        }
    }
    ClassConstructorVisibility::Public
}

/// Tests declared class ancestry using the validated source heritage edges.
pub(super) fn validated_class_derives_from(
    store: &CanonicalTypeMapperStore,
    class: TypeId,
    base: TypeId,
) -> Option<bool> {
    if validate_class_heritage_members(store, class) != ClassHeritageMembersValidation::Valid
        || validate_class_heritage_members(store, base) != ClassHeritageMembersValidation::Valid
    {
        return None;
    }
    let mut current = class;
    let mut visited = HashSet::new();
    while visited.insert(current) {
        if current == base {
            return Some(true);
        }
        let Some(heritage) = store.direct_class_heritage_provenance(current) else {
            return Some(false);
        };
        current = heritage.base_instance_type;
    }
    None
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ClassConstructorPlan {
    declaration: NodeRef,
    symbol: SemanticSymbolId,
    visibility: ClassConstructorVisibility,
    parameter: Option<ClassConstructorParameterPlan>,
    annotated_parameter: Option<ClassConstructorAnnotatedParameterPlan>,
    parameter_property: Option<ClassConstructorParameterPropertyPlan>,
    inferred_date_parameter: Option<ClassConstructorDateParameterPropertyPlan>,
    super_call: Option<NodeRef>,
}

impl ClassConstructorPlan {
    const fn signature_parameter(self) -> Option<SemanticSymbolId> {
        if let Some(parameter) = self.annotated_parameter {
            return Some(parameter.symbol);
        }
        match self.parameter {
            Some(parameter) => Some(parameter.symbol),
            None => match self.parameter_property {
                Some(parameter) => Some(parameter.local_symbol),
                None => match self.inferred_date_parameter {
                    Some(parameter) => Some(parameter.local_symbol),
                    None => None,
                },
            },
        }
    }

    const fn minimum_argument_count(self) -> i32 {
        if let Some(parameter) = self.annotated_parameter {
            return if parameter.optional || parameter.initializer.is_some() {
                0
            } else {
                1
            };
        }
        match self.parameter {
            Some(parameter) if parameter.optional || parameter.initializer.is_some() => 0,
            Some(_) => 1,
            None => match self.parameter_property {
                Some(_) => 1,
                None => 0,
            },
        }
    }

    const fn retained_parameter_property(self) -> Option<(NodeRef, SemanticSymbolId)> {
        if let Some(parameter) = self.annotated_parameter
            && let Some(property) = parameter.property
        {
            return Some((parameter.declaration, property.symbol));
        }
        match self.parameter_property {
            Some(parameter) => Some((parameter.declaration, parameter.property_symbol)),
            None => match self.inferred_date_parameter {
                Some(parameter) => Some((parameter.declaration, parameter.property_symbol)),
                None => None,
            },
        }
    }
}

