        let plan = plan_source_class_members(&fixture.store, &host, symbol).unwrap();
        let prepared = prepare_source_class_members(&mut fixture.store, &host, &plan).unwrap();
        let signature = prepared.methods[0].1;
        assert_eq!(
            fixture
                .store
                .signature(signature)
                .unwrap()
                .resolved_return_type(),
            None
        );
