    #[test]
    fn inherited_super_field_diagnostics_reject_forged_owners_and_caches() {
        for poison in 0..3 {
            let mut fixture = fixture(concat!(
                "class Base { field = () => {}; } ",
                "class Derived extends Base { f() { super.field(); } } ",
                "new Derived().f();",
            ));
            let base = class_symbol(&fixture, "Base");
            let derived = class_symbol(&fixture, "Derived");
            let field = fixture
                .store
                .symbol(base)
                .and_then(Symbol::members)
                .and_then(|members| fixture.store.symbol_table(members))
                .and_then(|members| members.get_source("field"))
                .unwrap();
            let diagnostic = {
                let bound = &fixture.files[&fixture.file];
                let host = host(&fixture.parsed.arena, bound);
                plan_super_inaccessible_field_grammar_diagnostics(&fixture.store, &host, base)
                    .unwrap()
                    .diagnostics[0]
                    .node
            };
            match poison {
                0 => assert!(fixture.store.set_symbol_relationships(
                    field,
                    None,
                    None,
                    Some(derived),
                    None,
                )),
                1 => {
                    let wrong = fixture.store.intrinsic_bootstrap().unwrap().string_type;
                    assert!(fixture.store.set_value_symbol_links(
                        field,
                        ValueSymbolLinks {
                            resolved_type: Some(wrong),
                            ..ValueSymbolLinks::default()
                        },
                    ));
                }
                2 => {
                    let wrong = fixture.store.intrinsic_bootstrap().unwrap().number_type;
                    assert!(fixture.store.set_type_node_links(
                        diagnostic,
                        TypeNodeLinks {
                            resolved_type: Some(wrong),
                            ..TypeNodeLinks::default()
                        },
                    ));
                }
                _ => unreachable!("only the declared owner and cache poison cases are visited"),
            }
            let bound = &fixture.files[&fixture.file];
            let host = host(&fixture.parsed.arena, bound);
            let before = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );

            assert!(
                plan_super_inaccessible_field_grammar_diagnostics(&fixture.store, &host, base)
                    .is_none(),
                "poison case {poison}",
            );
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                before,
            );
            for symbol in [base, derived] {
                assert!(fixture.store.declared_type_links(symbol).is_none());
                assert!(fixture.store.value_symbol_links(symbol).is_none());
            }
        }
    }

    #[test]
    fn class_namespace_static_reads_preserve_private_and_lexical_diagnostics() {
        let source = concat!(
            "class Clod { private static x = 10; public static y = 10; } ",
            "namespace Clod { ",
            "var first = Clod.x; ",
            "var second = x; ",
            "var third = Clod.y; ",
            "var fourth = y; ",
            "}",
        );
        let fixture = fixture(source);
        let owner = class_symbol(&fixture, "Clod");
        let bound = &fixture.files[&fixture.file];
        let host = host(&fixture.parsed.arena, bound);
        let before = (
            fixture.store.type_len(),
            fixture.store.signature_len(),
            fixture.store.checker_link_allocated_lengths(),
        );
        let record = fixture.store.symbol(owner).unwrap();
        assert_eq!(
            record.flags(),
            SymbolFlags::CLASS | SymbolFlags::VALUE_MODULE,
        );
        assert_eq!(record.declarations().unwrap().len(), 2);
        assert!(record.members().is_none());

        let grammar = plan_class_grammar_diagnostics(&fixture.store, &host, owner)
            .expect("the merged class namespace must retain its exact access diagnostics");

        assert_eq!(
            grammar
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>(),
            [2341, 2304, 2304],
        );
        assert_eq!(grammar.diagnostics[0].arguments, ["x", "Clod"]);
        assert_eq!(grammar.diagnostics[1].arguments, ["x"]);
        assert_eq!(grammar.diagnostics[2].arguments, ["y"]);
        let spans = grammar
            .diagnostics
            .iter()
            .map(|diagnostic| {
                let range = fixture
                    .parsed
                    .arena
                    .get(diagnostic.node.node)
                    .unwrap()
                    .range;
                &source[range.start.get() as usize..range.end.get() as usize]
            })
            .collect::<Vec<_>>();
        assert_eq!(spans, ["x", "x", "y"]);
        assert_eq!(
            (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            ),
            before,
        );
        assert!(fixture.store.declared_type_links(owner).is_none());
        assert!(fixture.store.value_symbol_links(owner).is_none());
    }

