    #[test]
    fn defaulted_constructor_parameter_properties_preserve_literal_and_optional_arity() {
        for (source, readonly, numeric, text) in [
            (
                "class Model { constructor(public value: number = 1) {} }",
                false,
                true,
                "1",
            ),
            (
                "class Model { constructor(readonly value: string = 'ready') {} }",
                true,
                false,
                "ready",
            ),
            (
                "class Model { constructor(public readonly value: number = 2) {} }",
                true,
                true,
                "2",
            ),
            (
                "class Model { constructor(public value: string = '') {} }",
                false,
                false,
                "",
            ),
            (
                "class Model { constructor(private value: number = 3) {} }",
                false,
                true,
                "3",
            ),
            (
                "class Model { constructor(protected readonly value: string = 'set') {} }",
                true,
                false,
                "set",
            ),
        ] {
            let mut fixture = fixture(source);
            let owner = class_symbol(&fixture, "Model");
            let bound = &fixture.files[&fixture.file];
            let host = host(&fixture.parsed.arena, bound);
            let plan = plan_nongeneric_class_member_query(&fixture.store, &host, owner).unwrap();
            let ClassMemberQueryPlan::Direct(class) = &plan else {
                panic!("a defaulted parameter property belongs to one direct class")
            };
            let constructor = class.class.constructor.unwrap();
            let parameter = constructor.parameter.unwrap();
            let property = parameter.property.unwrap();
            let initializer = parameter.initializer.unwrap();
            assert_ne!(parameter.symbol, property.symbol, "{source}");
            assert_eq!(bound.symbol(parameter.declaration), Some(property.symbol));
            assert_eq!(property.readonly, readonly, "{source}");
            assert_eq!(constructor.minimum_argument_count(), 0, "{source}");
            assert!(fixture.store.type_node_links(initializer).is_none());

            let members =
                execute_nongeneric_class_member_query(&mut fixture.store, &host, &plan).unwrap();

            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            let (expected, regular) = if numeric {
                (
                    bootstrap.number_type,
                    bootstrap
                        .cached_number_literal_type(ts_jsnum::from_string(text))
                        .unwrap(),
                )
            } else {
                (
                    bootstrap.string_type,
                    bootstrap.cached_string_literal_type(text).unwrap(),
                )
            };
            let fresh = fixture.store.fresh_type_of_literal_type(regular).unwrap();
            let signature = fixture
                .store
                .signature(members.default_construct_signature())
                .unwrap();
            assert_eq!(signature.flags(), SignatureFlags::CONSTRUCT, "{source}");
            assert_eq!(signature.parameters(), &[parameter.symbol], "{source}");
            assert_eq!(signature.min_argument_count(), 0, "{source}");
            for symbol in [parameter.symbol, property.symbol] {
                assert_eq!(
                    fixture.store.value_symbol_links(symbol),
                    Some(&ValueSymbolLinks {
                        resolved_type: Some(expected),
                        ..ValueSymbolLinks::default()
                    }),
                    "{source}",
                );
            }
            assert_eq!(
                fixture.store.type_node_links(initializer),
                Some(&TypeNodeLinks {
                    resolved_type: Some(fresh),
                    ..TypeNodeLinks::default()
                }),
                "{source}",
            );
            assert_eq!(
                validate_class_heritage_members(&fixture.store, members.shells().instance_type()),
                ClassHeritageMembersValidation::Valid,
                "{source}",
            );
            let warm = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );

            assert_eq!(
                execute_nongeneric_class_member_query(&mut fixture.store, &host, &plan),
                Ok(members),
                "{source}",
            );
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                warm,
                "{source}",
            );
        }
    }

    #[test]
    fn constructor_date_defaults_preserve_property_modifiers_and_signature_identity() {
        for (modifiers, readonly) in [
            ("readonly", true),
            ("public readonly", true),
            ("private readonly", true),
            ("protected readonly", true),
            ("public", false),
            ("private", false),
            ("protected", false),
        ] {
            let mut fixture = date_constructor_fixture(&format!(
                "class Model {{ constructor({modifiers} timestamp = new Date()) {{}} }}",
            ));
            let owner = class_symbol(&fixture, "Model");
            let bound = &fixture.files[&fixture.file];
            let host = host(&fixture.parsed.arena, bound);
            let plan = plan_nongeneric_class_member_query(&fixture.store, &host, owner).unwrap();
            let ClassMemberQueryPlan::Direct(class) = &plan else {
                panic!("the inferred Date parameter belongs to one direct class")
            };
            let constructor = class.class.constructor.unwrap();
            let parameter = constructor.inferred_date_parameter.unwrap();
            let date = parameter.initializer.symbol();
            assert_ne!(parameter.local_symbol, parameter.property_symbol);
            assert_eq!(
                bound.symbol(parameter.declaration),
                Some(parameter.property_symbol)
            );
            assert_eq!(constructor.minimum_argument_count(), 0);
            assert!(fixture.store.declared_type_links(date).is_none());
            assert!(
                fixture
                    .store
                    .type_node_links(parameter.initializer.node())
                    .is_none()
            );
            let cold = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );
            assert_eq!(
                plan_nongeneric_class_member_query(&fixture.store, &host, owner),
                Ok(plan.clone()),
            );
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                cold,
            );

            let members =
                execute_nongeneric_class_member_query(&mut fixture.store, &host, &plan).unwrap();

            let date_type = fixture
                .store
                .declared_type_links(date)
                .and_then(|links| links.declared_type)
                .unwrap();
            assert_eq!(members.instance_properties(), &[parameter.property_symbol]);
            for symbol in [parameter.local_symbol, parameter.property_symbol] {
                assert_eq!(
                    fixture.store.value_symbol_links(symbol),
                    Some(&ValueSymbolLinks {
                        resolved_type: Some(date_type),
                        ..ValueSymbolLinks::default()
                    }),
                );
            }
            assert_eq!(
                fixture
                    .store
                    .symbol(parameter.property_symbol)
                    .unwrap()
                    .check_flags(),
                if readonly {
                    CheckFlags::READONLY
                } else {
                    CheckFlags::NONE
                },
            );
            assert!(exact_global_date_initializer(
                &fixture.store,
                parameter.initializer.node(),
                date_type,
            ));
            let signature = fixture
                .store
                .signature(members.default_construct_signature())
                .unwrap();
            assert_eq!(signature.declaration(), Some(constructor.declaration));
            assert_eq!(signature.parameters(), &[parameter.local_symbol]);
            assert_eq!(signature.min_argument_count(), 0);
            assert_eq!(
                validate_class_heritage_members(&fixture.store, members.shells().instance_type()),
                ClassHeritageMembersValidation::Valid,
            );
            let warm = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );

            assert_eq!(
                execute_nongeneric_class_member_query(&mut fixture.store, &host, &plan),
                Ok(members),
            );
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                warm,
            );
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Check cold creation, source replay, and the two query contexts.
    fn constructor_date_defaults_keep_array_context_after_member_queries() {
        let library = parse_source_file(concat!(
            "interface Array<T> {} interface ReadonlyArray<T> {} ",
            "interface Date { toISOString(): string; toJSON(key?: any): string; ",
            "readonly labels: string[]; } ",
            "interface DateConstructor { new(): Date; readonly prototype: Date; } ",
            "declare var Date: DateConstructor;",
        ));
        let source = parse_source_file(concat!(
            "declare let existing: Date; ",
            "class Model { constructor(readonly timestamp = new Date()) {} }",
        ));
        let library_file = FileId::new(8_936);
        let source_file = FileId::new(8_937);
        let mut binder = CanonicalBinder::new();
        for (parsed, file, default_library, name) in [
            (&library, library_file, true, "\"/lib.d.ts\""),
            (&source, source_file, false, "\"/model.ts\""),
        ] {
            assert!(parsed.diagnostics.is_empty());
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new_with_default_library(
                        EscapedName::source(name),
                        CanonicalSourceLanguage::TypeScript,
                        default_library,
                        default_library,
                        CanonicalModuleState::Script,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }
        let options = CanonicalCheckerOptions {
            intrinsic: IntrinsicBootstrapOptions {
                strict_null_checks: true,
                exact_optional_property_types: true,
            },
            ..CanonicalCheckerOptions::default()
        };
        let mut context = CanonicalCheckerContext::new(
            binder.finish(),
            vec![(library_file, &library.arena), (source_file, &source.arena)],
            options,
        )
        .unwrap();
        let library_bound = context.file(library_file).unwrap().1.clone();
        let source_bound = context.file(source_file).unwrap().1.clone();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&source.arena, &source_bound),
            ],
            GlobalMergeCompletion::for_test(options.name_resolution),
        )
        .unwrap();
        let store = context.store();
        let globals = store
            .symbol_table(store.intrinsic_bootstrap().unwrap().globals)
            .unwrap();
        let owner = globals.get_source("Model").unwrap();
        let existing = globals.get_source("existing").unwrap();
        let annotation = store
            .symbol(existing)
            .and_then(Symbol::value_declaration)
            .and_then(|declaration| store.source_direct_type_annotation(declaration))
            .unwrap();
        let date_type = context.get_type_from_type_node(annotation).unwrap();
        let mut constituents = [
            date_type,
            context
                .store()
                .intrinsic_bootstrap()
                .unwrap()
                .undefined_type,
        ];
        constituents.sort_unstable();
        assert_eq!(
            context
                .store()
                .intrinsic_bootstrap()
                .unwrap()
                .cached_union_type(&constituents),
            None,
        );
        assert!(
            context
                .store()
                .validate_cached_array_capability(date_type)
                .is_err()
        );
        let query_context = ClassTypeQueryContext::new(context.global_types(), options);
        let plan = plan_nongeneric_class_member_query_with_type_context(
            context.store(),
            &host,
            owner,
            Some(&query_context),
        )
        .unwrap();
        let ClassMemberQueryPlan::Direct(class) = &plan else {
            panic!("Model must retain a direct class plan")
        };
        assert_eq!(
            class.class.type_query_context.as_ref(),
            Some(&query_context)
        );
        let parameter = class
            .class
            .constructor
            .unwrap()
            .inferred_date_parameter
            .unwrap();
        context.check_source_file(source_file).unwrap();
        assert!(context.diagnostics().is_empty());
        let members = context.get_nongeneric_class_members(owner).unwrap();
        let store = context.store();
        for symbol in [parameter.local_symbol, parameter.property_symbol] {
            assert_eq!(
                store.value_symbol_links(symbol).unwrap().resolved_type,
                Some(date_type)
            );
        }
        let call_type =
            optional_constructor_parameter_type(store, date_type, true, parameter.declaration)
                .unwrap()
                .unwrap();
        assert_eq!(
            store.validate_canonical_union_metadata(call_type, &constituents),
            Ok(())
        );
        let snapshot = |store: &CanonicalTypeMapperStore| {
            (
                store.type_len(),
                store.symbol_len(),
                store.signature_len(),
                store.mapper_len(),
                store.index_info_len(),
                store.checker_link_allocated_lengths(),
            )
        };
        let before = snapshot(store);
        for _ in 0..2 {
            context.recheck_source_file(source_file).unwrap();
            assert_eq!(
                context.get_nongeneric_class_members(owner).unwrap(),
                members
            );
            assert_eq!(
                plan_nongeneric_class_member_query_with_type_context(
                    context.store(),
                    &host,
                    owner,
                    Some(&query_context),
                ),
                Ok(plan.clone()),
            );
            assert_eq!(
                optional_constructor_parameter_type_with_context(
                    context.store(),
                    date_type,
                    true,
                    parameter.declaration,
                    Some(&query_context),
                ),
                Ok(Some(call_type)),
            );
            assert_eq!(snapshot(context.store()), before);
        }
        let mut wrong_context = query_context.clone();
        wrong_context.global_types.array_type = wrong_context.global_types.readonly_array_type;
        assert_eq!(
            optional_constructor_parameter_type_with_context(
                context.store(),
                date_type,
                true,
                parameter.declaration,
                Some(&wrong_context),
            ),
            Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
                parameter.declaration
            ))),
        );
        assert_eq!(snapshot(context.store()), before);
        let store = context.store_mut_for_test();
        let initializer = parameter.initializer.node();
        let original = store.signature_links(initializer).cloned().unwrap();
        assert!(store.set_signature_links(
            initializer,
            SignatureLinks {
                resolved_signature: ResolvedSignatureState::Resolved(
                    store.intrinsic_bootstrap().unwrap().any_signature
                ),
                ..SignatureLinks::default()
            },
        ));
        assert_eq!(
            optional_constructor_parameter_type(store, date_type, true, parameter.declaration),
            Err(invariant(ClassInvariant::InvalidPropertyTypeCache(
                parameter.declaration
            ))),
        );
        assert_eq!(snapshot(store), before);
        assert!(store.set_signature_links(initializer, original));
        assert_eq!(
            optional_constructor_parameter_type(store, date_type, true, parameter.declaration),
            Ok(Some(call_type)),
        );
        assert_eq!(snapshot(store), before);
    }

    #[test]
    fn readonly_constructor_date_default_poison_rejects_before_class_publication() {
        for poison in 0..4 {
            let mut fixture = date_constructor_fixture(
                "class Model { constructor(readonly timestamp = new Date()) {} }",
            );
            let owner = class_symbol(&fixture, "Model");
            let bound = &fixture.files[&fixture.file];
            let host = host(&fixture.parsed.arena, bound);
            let plan = plan_nongeneric_class_member_query(&fixture.store, &host, owner).unwrap();
            let ClassMemberQueryPlan::Direct(class) = &plan else {
                panic!("the inferred Date parameter belongs to one direct class")
            };
            let parameter = class
                .class
                .constructor
                .unwrap()
                .inferred_date_parameter
                .unwrap();
            let wrong = fixture.store.intrinsic_bootstrap().unwrap().number_type;
            let expected = match poison {
                0 => {
                    assert!(fixture.store.set_type_node_links(
                        parameter.initializer.node(),
                        TypeNodeLinks {
                            resolved_type: Some(wrong),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    invariant(ClassInvariant::InvalidPropertyTypeCache(
                        parameter.initializer.node(),
                    ))
                }
                1 | 2 => {
                    let symbol = if poison == 1 {
                        parameter.local_symbol
                    } else {
                        parameter.property_symbol
                    };
                    assert!(fixture.store.set_value_symbol_links(
                        symbol,
                        ValueSymbolLinks {
                            resolved_type: Some(wrong),
                            ..ValueSymbolLinks::default()
                        },
                    ));
                    invariant(ClassInvariant::InvalidPropertyValueCache(symbol))
                }
                3 => {
                    let signature = fixture.store.intrinsic_bootstrap().unwrap().any_signature;
                    assert!(fixture.store.set_signature_links(
                        parameter.initializer.node(),
                        SignatureLinks {
                            resolved_signature: ResolvedSignatureState::Resolved(signature),
                            ..SignatureLinks::default()
                        },
                    ));
                    invariant(ClassInvariant::InvalidPropertyTypeCache(
                        parameter.initializer.node(),
                    ))
                }
                _ => unreachable!("Date defaults retain four poisoned-cache cases"),
            };
            let before = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );

            assert_eq!(
                plan_nongeneric_class_member_query(&fixture.store, &host, owner),
                Err(expected),
            );
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                before,
            );
            assert!(fixture.store.declared_type_links(owner).is_none());
            assert!(fixture.store.value_symbol_links(owner).is_none());
            assert!(
                fixture
                    .store
                    .declared_type_links(parameter.initializer.symbol())
                    .is_none()
            );
        }
    }

